def _capture_partition_id_v3(
    *,
    adapter_policy_id: str,
    collector_boot_id: str,
    collector_instance_id: str,
    provider_native_key: str,
) -> str:
    """Reproduce the frozen CaptureSegmentV3 partition identity exactly."""

    return sha256_digest(
        {
            "canonicalization_version": CANONICALIZATION_VERSION,
            "domain": "CapturePartitionV3",
            "payload": {
                "adapter_policy_id": canonical_hash(
                    adapter_policy_id, field="adapter_policy_id"
                ),
                "collector_boot_id": canonical_identifier(
                    collector_boot_id, field="collector_boot_id"
                ),
                "collector_instance_id": canonical_identifier(
                    collector_instance_id, field="collector_instance_id"
                ),
                "provider_native_key": canonical_identifier(
                    provider_native_key, field="provider_native_key"
                ),
            },
            "schema_version": PHYSICAL_MARKET_DATA_SCHEMA_VERSION,
        }
    )


def _capture_lineage_validation_proxy_v4(
    segment: CaptureSegmentV3,
    registry: Mapping[str, CaptureSegmentV3],
    *,
    transport_sessions: Mapping[str, TransportSessionAttestationV4],
    terminal_transport_session_ids: set[str] | frozenset[str],
    captured_transport_session_ids: set[str] | frozenset[str],
) -> CaptureSegmentV3:
    """Normalize only a proven empty-session generation gap for V3 validation.

    The generic V3 validator deliberately remains strict. This projection-only
    proxy changes the candidate generation solely after the signed transport
    parent chain proves that every skipped generation was terminal and captured
    no provider-message segment.
    """

    parent_id = segment.parent_capture_segment_id
    if parent_id is None:
        return segment
    parent = registry.get(parent_id)
    if not isinstance(parent, CaptureSegmentV3):
        return segment
    if segment.connection_generation <= parent.connection_generation + 1:
        return segment

    current_session = transport_sessions.get(segment.connection_id)
    if current_session is None:
        raise CanonicalizationError(
            "capture generation gap current transport session is missing"
        )
    parent_session = transport_sessions.get(parent.connection_id)
    if parent_session is None:
        raise CanonicalizationError(
            "capture generation gap parent transport session is missing"
        )
    if (
        current_session.transport_session_id != segment.connection_id
        or current_session.connection_generation != segment.connection_generation
        or current_session.capture_partition_id != segment.capture_partition_id
        or current_session.collector_instance_id != segment.collector_instance_id
        or current_session.collector_boot_id != segment.collector_boot_id
        or current_session.adapter_policy_id != segment.adapter_policy_id
        or parent_session.transport_session_id != parent.connection_id
        or parent_session.connection_generation != parent.connection_generation
        or parent_session.capture_partition_id != parent.capture_partition_id
        or parent_session.collector_instance_id != parent.collector_instance_id
        or parent_session.collector_boot_id != parent.collector_boot_id
        or parent_session.adapter_policy_id != parent.adapter_policy_id
    ):
        raise CanonicalizationError(
            "capture generation gap differs from its endpoint transport sessions"
        )

    lineage_key = (
        current_session.transport_subscription_policy_id,
        current_session.physical_scope_manifest_id,
        current_session.adapter_policy_id,
        current_session.capture_partition_id,
        current_session.collector_instance_id,
        current_session.collector_boot_id,
        current_session.monotonic_clock_domain_id,
    )
    cursor = current_session
    expected_generation = segment.connection_generation
    while cursor.connection_generation > parent.connection_generation:
        if cursor.connection_generation != expected_generation:
            raise CanonicalizationError(
                "capture generation gap transport lineage skips a generation"
            )
        predecessor_id = cursor.parent_transport_session_id
        predecessor = (
            None if predecessor_id is None else transport_sessions.get(predecessor_id)
        )
        if predecessor is None:
            raise CanonicalizationError(
                "capture generation gap intervening transport session is missing"
            )
        predecessor_lineage_key = (
            predecessor.transport_subscription_policy_id,
            predecessor.physical_scope_manifest_id,
            predecessor.adapter_policy_id,
            predecessor.capture_partition_id,
            predecessor.collector_instance_id,
            predecessor.collector_boot_id,
            predecessor.monotonic_clock_domain_id,
        )
        if (
            predecessor.connection_generation != cursor.connection_generation - 1
            or predecessor_lineage_key != lineage_key
        ):
            raise CanonicalizationError(
                "capture generation gap leaves its partition/boot transport lineage"
            )
        if predecessor.connection_generation > parent.connection_generation:
            if predecessor.transport_session_id not in terminal_transport_session_ids:
                raise CanonicalizationError(
                    "capture generation gap intervening transport session is not terminal"
                )
            if predecessor.transport_session_id in captured_transport_session_ids:
                raise CanonicalizationError(
                    "capture generation gap intervening transport session has captured segments"
                )
        cursor = predecessor
        expected_generation -= 1

    if cursor.transport_session_id != parent.connection_id:
        raise CanonicalizationError(
            "capture generation gap does not descend from the parent capture session"
        )
    return replace(
        segment,
        connection_generation=parent.connection_generation + 1,
    )


class PhysicalProjectionV4Error(RuntimeError):
    """Base failure for the isolated V4 projection."""


class PhysicalProjectionV4ConfigurationError(PhysicalProjectionV4Error):
    """Raised when SQLite or the stored schema is not supported."""


class PhysicalProjectionV4ConflictError(PhysicalProjectionV4Error):
    """Raised when an append conflicts with immutable projected state."""


class PhysicalProjectionV4IdempotencyError(PhysicalProjectionV4ConflictError):
    """Raised when an idempotency key is reused for a different request."""


class PhysicalProjectionV4VerificationError(PhysicalProjectionV4Error):
    """Raised when stored canonical or typed state fails replay."""


class PhysicalProjectionV4WriterFenceError(PhysicalProjectionV4ConflictError):
    """Raised when an operational store loses its application writer epoch."""


class PhysicalProjectionV4ClockError(PhysicalProjectionV4ConflictError):
    """Raised when governed projection time is unavailable or inconsistent."""


@dataclass(frozen=True, slots=True, kw_only=True)
class PhysicalProjectionSqliteEnvironmentObservationV49F:
    """Owner-observed identity and safety settings of the open SQLite store.

    This is deliberately an observation rather than a caller-authored
    environment manifest.  It contains no connection, descriptor, path
    capability, or mutation method.
    """

    database_path: str
    database_device: int
    database_inode: int
    busy_timeout_milliseconds: int
    foreign_keys_enabled: bool
    trusted_schema_enabled: bool
    cell_size_check_enabled: bool
    mmap_size_bytes: int
    journal_mode: str
    synchronous_level: int
    page_size_bytes: int

    def __post_init__(self) -> None:
        path = canonical_identifier(
            self.database_path,
            field="database_path",
            maximum=4096,
        )
        if not Path(path).is_absolute() or os.path.normpath(path) != path:
            raise CanonicalizationError(
                "database_path must be a normalized absolute path"
            )
        object.__setattr__(self, "database_path", path)
        for name, minimum, maximum in (
            ("database_device", 0, None),
            ("database_inode", 1, None),
            ("busy_timeout_milliseconds", 0, 3_600_000),
            ("mmap_size_bytes", 0, (1 << 63) - 1),
            ("synchronous_level", 0, 3),
            ("page_size_bytes", 512, 65_536),
        ):
            object.__setattr__(
                self,
                name,
                canonical_safe_int(
                    getattr(self, name),
                    field=name,
                    minimum=minimum,
                    maximum=maximum,
                ),
            )
        for name in (
            "foreign_keys_enabled",
            "trusted_schema_enabled",
            "cell_size_check_enabled",
        ):
            if type(getattr(self, name)) is not bool:
                raise CanonicalizationError(f"{name} must be an exact boolean")
        mode = canonical_identifier(
            self.journal_mode,
            field="journal_mode",
            maximum=32,
        ).upper()
        if mode != "DELETE":
            raise CanonicalizationError(
                "authoritative SQLite observation requires DELETE journal mode"
            )
        object.__setattr__(self, "journal_mode", mode)
        if not self.foreign_keys_enabled:
            raise CanonicalizationError(
                "authoritative SQLite observation requires foreign keys"
            )
        if self.trusted_schema_enabled:
            raise CanonicalizationError(
                "authoritative SQLite observation forbids trusted_schema"
            )
        if not self.cell_size_check_enabled:
            raise CanonicalizationError(
                "authoritative SQLite observation requires cell_size_check"
            )
        if self.mmap_size_bytes != 0:
            raise CanonicalizationError(
                "authoritative SQLite observation requires mmap_size=0"
            )
        if self.synchronous_level != 3:
            raise CanonicalizationError(
                "authoritative SQLite observation requires synchronous=EXTRA"
            )
        if self.page_size_bytes & (self.page_size_bytes - 1):
            raise CanonicalizationError("SQLite page_size must be a power of two")

    def identity_payload(self) -> dict[str, Any]:
        return {name: getattr(self, name) for name in self.__dataclass_fields__}

    @property
    def sqlite_pragmas(self) -> tuple[tuple[str, str], ...]:
        """Return the exact open-connection PRAGMAs in canonical name order."""

        return (
            ("busy_timeout", str(self.busy_timeout_milliseconds)),
            ("cell_size_check", "1" if self.cell_size_check_enabled else "0"),
            ("foreign_keys", "1" if self.foreign_keys_enabled else "0"),
            ("journal_mode", self.journal_mode),
            ("mmap_size", str(self.mmap_size_bytes)),
            ("page_size", str(self.page_size_bytes)),
            ("synchronous", str(self.synchronous_level)),
            ("trusted_schema", "1" if self.trusted_schema_enabled else "0"),
        )

    @property
    def observation_id(self) -> str:
        return sha256_digest(
            {
                "canonicalization_version": CANONICALIZATION_VERSION,
                "domain": "RiskYieldMMPhysicalProjectionSqliteEnvironmentObservationV49F",
                "payload": self.identity_payload(),
                "schema_version": PHYSICAL_PROJECTION_V4_SCHEMA_VERSION,
            }
        )

    def as_dict(self) -> dict[str, Any]:
        return {**self.identity_payload(), "observation_id": self.observation_id}


