_CLASS_KINDS = {value: key for key, value in _RECORD_PARSERS.items()}

_OPERATIONAL_CHILD_RECORD_KINDS: dict[
    OperationalManifestKindV4, PhysicalRecordKindV4
] = {
    OperationalManifestKindV4.COLLECTOR_RELEASE: (
        PhysicalRecordKindV4.COLLECTOR_RELEASE_MANIFEST
    ),
    OperationalManifestKindV4.DEPENDENCY_LOCK: (
        PhysicalRecordKindV4.DEPENDENCY_LOCK_MANIFEST
    ),
    OperationalManifestKindV4.TLS_TRUST_STORE: (
        PhysicalRecordKindV4.TLS_TRUST_STORE_MANIFEST
    ),
    OperationalManifestKindV4.CLOCK_SOURCE_POLICY: (
        PhysicalRecordKindV4.CLOCK_SOURCE_POLICY_MANIFEST
    ),
    OperationalManifestKindV4.RUNTIME_ENVIRONMENT: (
        PhysicalRecordKindV4.RUNTIME_ENVIRONMENT_MANIFEST
    ),
    OperationalManifestKindV4.COLLECTOR_KEY_AUTHORIZATION: (
        PhysicalRecordKindV4.COLLECTOR_KEY_AUTHORIZATION_MANIFEST
    ),
}
_OPERATIONAL_CHILD_TYPES = (
    CollectorReleaseManifestV4,
    DependencyLockManifestV4,
    TlsTrustStoreManifestV4,
    ClockSourcePolicyManifestV4,
    RuntimeEnvironmentManifestV4,
    CollectorKeyAuthorizationManifestV4,
)


def _record_kind(record: Any) -> PhysicalRecordKindV4:
    kind = _CLASS_KINDS.get(type(record))
    if kind is None:
        raise CanonicalizationError("unsupported physical-projection V4 record")
    return kind


def _record_identity(record: Any) -> str:
    if isinstance(record, DeploymentTrustRootV4):
        return record.trust_root_id
    if isinstance(
        record,
        (
            CollectorReleaseManifestV4,
            DependencyLockManifestV4,
            TlsTrustStoreManifestV4,
            ClockSourcePolicyManifestV4,
            RuntimeEnvironmentManifestV4,
            CollectorKeyAuthorizationManifestV4,
        ),
    ):
        return record.manifest_id
    if isinstance(record, DeploymentBundleApprovalV4):
        return _deployment_bundle_approval_id_v4(record)
    if isinstance(record, ProviderAdapterPolicyV3):
        return record.adapter_policy_id
    if isinstance(record, PhysicalScopeManifestV4):
        return record.physical_scope_manifest_id
    if isinstance(record, TransportSubscriptionPolicyV4):
        return record.transport_subscription_policy_id
    if isinstance(record, TransportSessionAttestationV4):
        return record.transport_session_id
    if isinstance(record, TransportSocketOwnerBindingV4):
        return record.transport_socket_owner_binding_id
    if isinstance(record, RawIngressCommitV4):
        return record.raw_ingress_commit_id
    if type(record) is TransportActorEventV49C:
        return record.transport_actor_event_id
    if isinstance(record, InboundWebSocketProtocolFailureV4):
        return record.inbound_websocket_protocol_failure_id
    if isinstance(record, InboundRfcControlTriggerV4):
        return record.inbound_rfc_control_trigger_id
    if isinstance(record, OutboundControlIntentV4):
        return record.outbound_control_intent_id
    if isinstance(record, OutboundControlWirePreparedV4):
        return record.outbound_control_wire_prepared_id
    if isinstance(record, OutboundControlWritePermitConsumedV4):
        return record.permit_id
    if isinstance(record, OutboundControlDispatchResultV4):
        return record.outbound_control_dispatch_result_id
    if isinstance(record, OutboundSubscriptionIntentV4):
        return record.outbound_subscription_intent_id
    if isinstance(record, SubscriptionAckBindingV4):
        return record.subscription_ack_binding_id
    if isinstance(record, TransportSessionTerminationV4):
        return record.transport_session_termination_id
    if isinstance(record, CaptureSegmentV3):
        return record.capture_segment_id
    if isinstance(record, PhysicalMessageV4):
        return record.physical_message_id
    if isinstance(record, ProviderMessageDispositionV3):
        return record.provider_message_disposition_id
    if isinstance(record, ObservationDerivationV3):
        return record.observation_derivation_id
    if isinstance(record, ObservationRevisionV3):
        return record.observation_revision_id
    if isinstance(record, MessageDispositionV4):
        return record.message_disposition_id
    if isinstance(record, EvidenceTreeHeadV4):
        return record.evidence_tree_head_id
    if isinstance(record, EvidenceCutoffV4):
        return record.evidence_cutoff_id
    if isinstance(record, PhysicalProtocolBindingV4):
        return record.physical_protocol_binding_id
    if isinstance(record, SelectionResultChunkV4):
        return record.selection_result_chunk_id
    if isinstance(record, ObservationSelectionProofV4):
        return record.observation_selection_proof_id
    if isinstance(record, InformationSetV3):
        return record.information_set_id
    if isinstance(record, PhysicalHealthPolicyV4):
        return record.physical_health_policy_id
    if isinstance(record, PhysicalHealthTransitionV4):
        return record.physical_health_transition_id
    if isinstance(record, PhysicalEvidenceGateV4):
        return record.physical_evidence_gate_id
    if type(record) is CapacityMeasurementOperationAttemptV49F:
        assert record.attempt_id is not None
        return record.attempt_id
    if type(record) is CapacityMeasurementOperationTerminalV49F:
        assert record.terminal_id is not None
        return record.terminal_id
    raise CanonicalizationError("unsupported physical-projection V4 record")


def _deployment_bundle_approval_id_v4(
    approval: DeploymentBundleApprovalV4,
) -> str:
    """Return the projection receipt identity for one exact DSSE envelope.

    This content identity distinguishes different envelopes over the same
    bundle. It is deliberately not the signed bundle identity and does not by
    itself imply successful trust-root or closure verification.
    """

    if type(approval) is not DeploymentBundleApprovalV4:
        raise TypeError("approval must be an exact DeploymentBundleApprovalV4")
    return sha256_digest(
        {
            "canonicalization_version": CANONICALIZATION_VERSION,
            "domain": "RiskYieldMMOperationalDeploymentApprovalReceiptV4_5",
            "payload": approval.as_dict(),
            "schema_version": PHYSICAL_PROJECTION_V4_SCHEMA_VERSION,
        }
    )


def _disposition_authority_problem(
    *, scope: PhysicalScopeManifestV4, disposition: MessageDispositionV4
) -> str | None:
    if disposition.adapter_policy_id == scope.primary_adapter_policy_id:
        expected_release = scope.primary_classifier_release_hash
    elif (
        scope.required_status_adapter_policy_id is not None
        and disposition.adapter_policy_id == scope.required_status_adapter_policy_id
    ):
        expected_release = scope.required_status_classifier_release_hash
    else:
        return "disposition adapter policy is outside its physical scope"
    if disposition.classifier_release_hash != expected_release:
        return "disposition classifier release differs from its scoped authority"
    expected_result = classifier_result_id_v4(
        adapter_policy_id=disposition.adapter_policy_id,
        capture_segment_id=disposition.capture_segment_id,
        classifier_release_hash=disposition.classifier_release_hash,
        disposition_kind=disposition.disposition_kind,
        message_receipt_id=disposition.message_receipt_id,
        raw_payload_sha256=disposition.raw_payload_sha256,
        observation_derivation_id=(
            None
            if not disposition.observation_derivation_ids
            else disposition.observation_derivation_ids[0]
        ),
        observation_revision_id=(
            None
            if not disposition.observation_revision_ids
            else disposition.observation_revision_ids[0]
        ),
        duplicate_of_message_receipt_id=(disposition.duplicate_of_message_receipt_id),
        duplicate_of_disposition_id=disposition.duplicate_of_disposition_id,
        provider_diagnostic_code=disposition.provider_diagnostic_code,
        provider_diagnostic_digest=disposition.provider_diagnostic_digest,
    )
    if disposition.classifier_result_id != expected_result:
        return "disposition classifier result differs from deterministic semantics"
    return None


def _parse_mapping(blob: bytes, *, context: str) -> Mapping[str, Any]:
    value = strict_json_loads(blob)
    if not isinstance(value, Mapping):
        raise CanonicalizationError(f"{context} must be a JSON object")
    return value


def _running_event_loop_or_none() -> asyncio.AbstractEventLoop | None:
    try:
        return asyncio.get_running_loop()
    except RuntimeError:
        return None


def _current_asyncio_task_or_none() -> asyncio.Task[Any] | None:
    loop = _running_event_loop_or_none()
    return None if loop is None else asyncio.current_task(loop=loop)


def _is_exact_text_provider_message(envelope: ProviderMessageEnvelopeV3) -> bool:
    """Return whether the captured transport payload was explicitly TEXT."""

    return envelope.message_type is ProviderMessageTypeV3.TEXT


def _parse_record(kind: PhysicalRecordKindV4, blob: bytes) -> Any:
    return _RECORD_PARSERS[kind].from_mapping(_parse_mapping(blob, context=kind.value))


def validate_capacity_measurement_operation_prefix_records_v49f(
    prefix: CapacityMeasurementOperationPrefixV49F,
) -> CapacityMeasurementOperationPrefixV49F:
    """Strictly decode and identify every opaque receipt-span record offline."""

    if type(prefix) is not CapacityMeasurementOperationPrefixV49F:
        raise CanonicalizationError(
            "prefix must be exact CapacityMeasurementOperationPrefixV49F"
        )
    # Reconstructing the lifecycle value first replays receipt continuity,
    # RAW/actor mapping and both prefix identities before projection-specific
    # record kinds are interpreted.
    replay = CapacityMeasurementOperationPrefixV49F.from_mapping(prefix.as_dict())
    for receipt, evidence in zip(replay.projection_receipts, replay.projection_records):
        try:
            kind = PhysicalRecordKindV4(evidence.record_kind)
        except ValueError as exc:
            raise CanonicalizationError(
                "capacity prefix contains an unsupported projection record kind"
            ) from exc
        record = _parse_record(kind, evidence.canonical_record_bytes)
        if (
            _record_identity(record) != evidence.identity_id
            or hashlib.sha256(evidence.canonical_record_bytes).hexdigest()
            != evidence.content_hash
            or receipt.record_kind != kind.value
            or receipt.identity_id != evidence.identity_id
            or receipt.content_hash != evidence.content_hash
        ):
            raise CanonicalizationError(
                "capacity prefix projection record semantics differ from receipt"
            )
    return replay


def _blob_hash(value: str, *, field: str) -> bytes:
    return bytes.fromhex(canonical_hash(value, field=field))


def _hex_hash(value: bytes, *, field: str) -> str:
    if type(value) is not bytes or len(value) != 32:
        raise PhysicalProjectionV4VerificationError(
            f"{field} must contain exactly 32 bytes"
        )
    return value.hex()


def _content_hash(blob: bytes) -> bytes:
    return hashlib.sha256(blob).digest()


def _timestamp_us(value: datetime | str, *, field: str) -> int:
    item = utc_datetime(value, field=field)
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    elapsed = item - epoch
    return (
        elapsed.days * 86_400_000_000
        + elapsed.seconds * 1_000_000
        + elapsed.microseconds
    )


def _optional_timestamp_us(value: datetime | str | None, *, field: str) -> int | None:
    return None if value is None else _timestamp_us(value, field=field)


def _datetime_from_us(value: int) -> datetime:
    return datetime(1970, 1, 1, tzinfo=timezone.utc) + timedelta(microseconds=value)


def _request_hash(operation: str, payload: Mapping[str, Any]) -> bytes:
    return _content_hash(
        canonical_json_bytes(
            {
                "domain": "RiskYieldMMPhysicalProjectionRequestV4",
                "operation": operation,
                "payload": dict(payload),
                "schema_version": PHYSICAL_PROJECTION_V4_SCHEMA_VERSION,
            }
        )
    )


def _information_dependency_root(information_set: InformationSetV3) -> bytes:
    return _blob_hash(
        sha256_digest(
            {
                "dependency_ids": [
                    item.dependency_id for item in information_set.dependencies
                ],
                "domain": "RiskYieldMMInformationDependencySetV4",
            }
        ),
        field="dependency_root",
    )


def _state_dependency_root(information_set: InformationSetV3) -> bytes:
    return _blob_hash(
        sha256_digest(
            {
                "domain": "RiskYieldMMStateDependencySetV4",
                "state_dependency_ids": [
                    item.state_dependency_id
                    for item in information_set.state_dependencies
                ],
            }
        ),
        field="state_dependency_root",
    )


def _receipt_hash(
    *,
    ledger_id: bytes,
    sequence: int,
    previous_receipt_hash: bytes,
    record_kind: PhysicalRecordKindV4,
    identity_id: bytes,
    content_hash: bytes,
) -> bytes:
    """Return the deterministic semantic receipt hash.

    Operational commit time is intentionally excluded.  It remains diagnostic
    metadata and cannot perturb V4 tree-head identities across batch splits.
    """

    return _content_hash(
        canonical_json_bytes(
            {
                "content_hash": content_hash.hex(),
                "domain": "RiskYieldMMPhysicalProjectionReceiptV4",
                "global_sequence": sequence,
                "identity_id": identity_id.hex(),
                "ledger_id": ledger_id.hex(),
                "previous_receipt_hash": previous_receipt_hash.hex(),
                "record_kind": record_kind.value,
            }
        )
    )


def _derive_ledger_id(
    *, nonce: bytes, created_at: str, schema_fingerprint: bytes
) -> bytes:
    return _blob_hash(
        sha256_digest(
            {
                "canonicalization_version": CANONICALIZATION_VERSION,
                "created_at": created_at,
                "domain": "RiskYieldMMPhysicalProjectionLedgerIdentityV4",
                "nonce": nonce.hex(),
                "physical_evidence_schema_version": (
                    PHYSICAL_EVIDENCE_V4_SCHEMA_VERSION
                ),
                "projection_schema_fingerprint": schema_fingerprint.hex(),
                "projection_schema_version": (PHYSICAL_PROJECTION_V4_SCHEMA_VERSION),
                "validation_version": (PHYSICAL_PROJECTION_V4_VALIDATION_VERSION),
            }
        ),
        field="ledger_id",
    )


@dataclass(frozen=True, slots=True, kw_only=True)
class PhysicalProjectionReceiptV4:
    global_sequence: int
    receipt_hash: str
    previous_receipt_hash: str
    record_kind: PhysicalRecordKindV4
    identity_id: str
    content_hash: str
    committed_at: datetime

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "global_sequence",
            canonical_safe_int(
                self.global_sequence, field="global_sequence", minimum=1
            ),
        )
        for field_name in (
            "receipt_hash",
            "previous_receipt_hash",
            "identity_id",
            "content_hash",
        ):
            object.__setattr__(
                self,
                field_name,
                canonical_hash(getattr(self, field_name), field=field_name),
            )
        try:
            kind = (
                self.record_kind
                if isinstance(self.record_kind, PhysicalRecordKindV4)
                else PhysicalRecordKindV4(self.record_kind)
            )
        except (TypeError, ValueError) as exc:
            raise CanonicalizationError("unsupported projection record kind") from exc
        object.__setattr__(self, "record_kind", kind)
        object.__setattr__(
            self,
            "committed_at",
            utc_datetime(self.committed_at, field="committed_at"),
        )


@dataclass(frozen=True, slots=True, kw_only=True)
class CommittedCapacityMeasurementOperationAttemptV49F:
    """Process-local proof that one pre-effect attempt commit returned."""

    attempt: CapacityMeasurementOperationAttemptV49F
    receipt: PhysicalProjectionReceiptV4
    _store_token: object
    _process_id: int
    _thread_id: int
    _event_loop: asyncio.AbstractEventLoop | None
    _asyncio_task: asyncio.Task[Any] | None
    _clock_anchor_monotonic_ns: int | None
    _clock_valid_until: datetime | None
    _kernel_boot_id: str | None
    _time_namespace_id: str | None

    def __post_init__(self) -> None:
        if type(self.attempt) is not CapacityMeasurementOperationAttemptV49F:
            raise CanonicalizationError("committed attempt has an invalid subject")
        if type(self.receipt) is not PhysicalProjectionReceiptV4 or (
            self.receipt.record_kind
            is not PhysicalRecordKindV4.CAPACITY_MEASUREMENT_OPERATION_ATTEMPT_V49F
            or self.receipt.identity_id != self.attempt.attempt_id
        ):
            raise CanonicalizationError("committed attempt has a substituted receipt")


@dataclass(frozen=True, slots=True, kw_only=True)
class CapacityMeasurementAttemptAuthorityV49F:
    """Immutable pre-attempt store facts captured at one quiescent boundary."""

    projection_ledger_id: str
    projection_schema_version: str
    projection_validation_version: str
    projection_schema_fingerprint: str
    projection_store_observation_id: str
    writer_fence_token_sha256: str
    writer_fence_generation: int
    pre_attempt_receipt_sequence: int
    pre_attempt_receipt_hash: str
    retained_raw_dependencies: tuple[CapacityMeasurementRetainedRawDependencyV49F, ...]

    def __post_init__(self) -> None:
        for name in (
            "projection_ledger_id",
            "projection_schema_fingerprint",
            "projection_store_observation_id",
            "writer_fence_token_sha256",
            "pre_attempt_receipt_hash",
        ):
            object.__setattr__(
                self, name, canonical_hash(getattr(self, name), field=name)
            )
        object.__setattr__(
            self,
            "projection_schema_version",
            canonical_identifier(
                self.projection_schema_version,
                field="projection_schema_version",
                maximum=128,
            ),
        )
        object.__setattr__(
            self,
            "projection_validation_version",
            canonical_identifier(
                self.projection_validation_version,
                field="projection_validation_version",
                maximum=128,
            ),
        )
        for name, minimum in (
            ("writer_fence_generation", 1),
            ("pre_attempt_receipt_sequence", 0),
        ):
            object.__setattr__(
                self,
                name,
                canonical_safe_int(getattr(self, name), field=name, minimum=minimum),
            )
        if type(self.retained_raw_dependencies) is not tuple or any(
            type(item) is not CapacityMeasurementRetainedRawDependencyV49F
            for item in self.retained_raw_dependencies
        ):
            raise CanonicalizationError(
                "attempt authority retained RAW dependencies are invalid"
            )


_CAPACITY_STARTUP_RECOVERY_CAPABILITY_TOKEN_V49F = object()


class CapacityMeasurementStartupRecoveryCapabilityV49F:
    """One-shot startup authority over the exact open attempts seen at claim."""

    __slots__ = (
        "_open_attempt_ids",
        "_projection_store_observation_id",
        "_snapshot_id",
        "_store_token",
        "_process_id",
        "_thread_id",
        "_sealed",
    )

    def __init__(
        self,
        *,
        _token: object,
        open_attempt_ids: tuple[str, ...],
        projection_store_observation_id: str,
        store_token: object,
    ) -> None:
        if _token is not _CAPACITY_STARTUP_RECOVERY_CAPABILITY_TOKEN_V49F:
            raise TypeError("startup recovery capabilities are store-minted only")
        if type(open_attempt_ids) is not tuple:
            raise TypeError("open_attempt_ids must be an exact tuple")
        open_ids = tuple(
            canonical_hash(value, field="open_attempt_id") for value in open_attempt_ids
        )
        if len(set(open_ids)) != len(open_ids):
            raise CanonicalizationError(
                "startup recovery capability contains duplicate attempts"
            )
        observation_id = canonical_hash(
            projection_store_observation_id,
            field="projection_store_observation_id",
        )
        object.__setattr__(self, "_open_attempt_ids", open_ids)
        object.__setattr__(self, "_projection_store_observation_id", observation_id)
        object.__setattr__(
            self,
            "_snapshot_id",
            sha256_digest(
                {
                    "domain": "RiskYieldMMCapacityStartupRecoverySnapshotV4_9F",
                    "open_attempt_ids": list(open_ids),
                    "projection_store_observation_id": observation_id,
                }
            ),
        )
        object.__setattr__(self, "_store_token", store_token)
        object.__setattr__(self, "_process_id", os.getpid())
        object.__setattr__(self, "_thread_id", threading.get_ident())
        object.__setattr__(self, "_sealed", True)

    def __setattr__(self, name: str, value: Any) -> None:
        if getattr(self, "_sealed", False):
            raise AttributeError("startup recovery capability is immutable")
        object.__setattr__(self, name, value)

    @property
    def open_attempt_ids(self) -> tuple[str, ...]:
        return self._open_attempt_ids

    @property
    def projection_store_observation_id(self) -> str:
        return self._projection_store_observation_id

    @property
    def snapshot_id(self) -> str:
        return self._snapshot_id


@dataclass(frozen=True, slots=True, kw_only=True)
class ClassificationAppendV4:
    """One V3 classifier result and its exact V4 projection inputs.

    This non-canonical command wrapper prevents callers from admitting a V4
    normalized disposition that merely names nonexistent observation hashes.
    """

    disposition: MessageDispositionV4
    provider_disposition: ProviderMessageDispositionV3
    derivation: ObservationDerivationV3 | None = None
    revision: ObservationRevisionV3 | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.disposition, MessageDispositionV4):
            raise CanonicalizationError("disposition must be MessageDispositionV4")
        if not isinstance(self.provider_disposition, ProviderMessageDispositionV3):
            raise CanonicalizationError(
                "provider_disposition must be ProviderMessageDispositionV3"
            )
        normalized = (
            self.disposition.disposition_kind
            is MessageDispositionKind.NORMALIZED_OBSERVATION
        )
        if normalized:
            if not isinstance(
                self.derivation, ObservationDerivationV3
            ) or not isinstance(self.revision, ObservationRevisionV3):
                raise CanonicalizationError(
                    "normalized classification requires a derivation and revision"
                )
            if (
                self.disposition.observation_derivation_ids
                != (self.derivation.observation_derivation_id,)
                or self.disposition.observation_revision_ids
                != (self.revision.observation_revision_id,)
                or self.provider_disposition.observation_derivation_id
                != self.derivation.observation_derivation_id
                or self.provider_disposition.observation_revision_id
                != self.revision.observation_revision_id
            ):
                raise CanonicalizationError(
                    "normalized classification output identities differ"
                )
        elif self.derivation is not None or self.revision is not None:
            raise CanonicalizationError(
                "non-normalized classification cannot carry observation outputs"
            )


@dataclass(frozen=True, slots=True, kw_only=True)
class ActorProviderMessageCommitResultV49E:
    """Atomic projection result for one completed actor-owned WS message."""

    segment: CaptureSegmentV3
    physical_message: PhysicalMessageV4
    classification: ClassificationAppendV4
    application_event: TransportActorEventV49C
    ack_binding: SubscriptionAckBindingV4 | None = None
    ack_event: TransportActorEventV49C | None = None
    provider_failure_event: TransportActorEventV49C | None = None
    termination: TransportSessionTerminationV4 | None = None

    def __post_init__(self) -> None:
        if (
            not isinstance(self.segment, CaptureSegmentV3)
            or not isinstance(self.physical_message, PhysicalMessageV4)
            or not isinstance(self.classification, ClassificationAppendV4)
            or type(self.application_event) is not TransportActorEventV49C
        ):
            raise CanonicalizationError(
                "actor provider commit result contains an invalid exact record"
            )
        paired = self.ack_binding is not None or self.ack_event is not None
        if paired and not (
            isinstance(self.ack_binding, SubscriptionAckBindingV4)
            and type(self.ack_event) is TransportActorEventV49C
            and self.ack_event.event_kind
            is TransportActorEventKindV49C.SUBSCRIPTION_ACK_BOUND
            and self.ack_binding.transport_session_id
            == self.ack_event.transport_session_id
            == self.application_event.transport_session_id
        ):
            raise CanonicalizationError(
                "actor ACK binding and actor ACK event must be paired"
            )
        failed = self.provider_failure_event is not None or self.termination is not None
        if failed and not (
            type(self.provider_failure_event) is TransportActorEventV49C
            and self.provider_failure_event.event_kind
            is TransportActorEventKindV49C.TERMINAL_TRANSITION
            and type(self.provider_failure_event.payload)
            is TerminalTransitionPayloadV49C
            and self.provider_failure_event.payload.kind
            is TerminalTransitionKindV49C.FATAL
            and self.provider_failure_event.payload.cause_code
            == _V49E_SUBSCRIPTION_ACK_INTEGRITY_FAILURE_CAUSE
            and isinstance(self.termination, TransportSessionTerminationV4)
            and self.termination.reason
            is TransportSessionTerminationReasonV4.TRANSPORT_ERROR
            and self.termination.transport_session_id
            == self.provider_failure_event.transport_session_id
            == self.application_event.transport_session_id
        ):
            raise CanonicalizationError(
                "actor provider failure and signed termination must be paired"
            )
        if paired and failed:
            raise CanonicalizationError(
                "actor provider result cannot both bind and terminalize"
            )


@dataclass(frozen=True, slots=True, kw_only=True)
class ActorAckDeadlineExpiryResultV49E:
    """Atomic timeout result spanning actor and signed session authority."""

    deadline_event: TransportActorEventV49C
    terminal_event: TransportActorEventV49C
    termination: TransportSessionTerminationV4

    def __post_init__(self) -> None:
        if (
            type(self.deadline_event) is not TransportActorEventV49C
            or self.deadline_event.event_kind
            is not TransportActorEventKindV49C.ACK_DEADLINE_EXPIRED
            or type(self.terminal_event) is not TransportActorEventV49C
            or self.terminal_event.event_kind
            is not TransportActorEventKindV49C.TERMINAL_TRANSITION
            or not isinstance(self.termination, TransportSessionTerminationV4)
        ):
            raise CanonicalizationError(
                "ACK deadline result contains unsupported exact records"
            )


@dataclass(frozen=True, slots=True, kw_only=True)
class ActorTerminalConvergenceResultV49E:
    """Indivisible final actor outcome and its signed legacy bridge."""

    terminal_event: TransportActorEventV49C
    termination: TransportSessionTerminationV4

    def __post_init__(self) -> None:
        if (
            type(self.terminal_event) is not TransportActorEventV49C
            or self.terminal_event.event_kind
            is not TransportActorEventKindV49C.TERMINAL_TRANSITION
            or not isinstance(self.termination, TransportSessionTerminationV4)
            or self.termination.transport_session_id
            != self.terminal_event.transport_session_id
        ):
            raise CanonicalizationError(
                "terminal convergence result contains unsupported exact records"
            )


@dataclass(frozen=True, slots=True, kw_only=True)
class _ActorTerminalBridgeV49E:
    reason: TransportSessionTerminationReasonV4
    close_code: int | None
    close_reason_digest: str | None
    detected_at: datetime
    detected_monotonic_ns: int
    detected_monotonic_clock_domain_id: str


@dataclass(frozen=True, slots=True, kw_only=True)
class _ActorPendingSubscriptionAckV49E:
    intent: OutboundSubscriptionIntentV4
    wire_event: TransportActorEventV49C
    first_attempt: KernelSendAttemptPayloadV49C
    completion_event: TransportActorEventV49C
    ack_not_after_monotonic_ns: int
    prior_provider_connection_ids: frozenset[str]


