    @staticmethod
    def _driver_send_deadline_id_v49e(
        *,
        payload: KernelSendFailurePayloadV49E | TlsControlKernelSendFailurePayloadV49E,
    ) -> str:
        return sha256_digest(
            {
                "domain": "RiskYieldMMTlsSendDeadlineNoKernelAcceptanceV4_9E",
                "driver_evidence_nonce_sha256": (payload.driver_evidence_nonce_sha256),
                "send_kind": payload.send_kind,
                "transport_sequence": payload.transport_sequence,
                "ciphertext_batch_sha256": payload.ciphertext_batch_sha256,
                "ciphertext_octets": payload.ciphertext_octets,
                "ciphertext_start_octet": payload.ciphertext_start_octet,
                "requested_octets": payload.requested_octets,
                "exact_slice_sha256": payload.exact_slice_sha256,
                "deadline_ns": payload.shutdown_deadline_monotonic_ns,
                "would_block_count": payload.would_block_count,
            }
        )

    @staticmethod
    def _owner_send_deadline_id_v49e(
        *,
        transport_session_id: str,
        payload: KernelSendFailurePayloadV49E | TlsControlKernelSendFailurePayloadV49E,
        driver_evidence_id: str,
    ) -> str:
        return sha256_digest(
            {
                "domain": "RiskYieldMMOwnerTlsSendDeadlineNoKernelAcceptanceV4_9E",
                "transport_session_id": transport_session_id,
                "kernel_socket_identity": payload.kernel_socket_identity,
                "driver_evidence_nonce_sha256": (payload.driver_evidence_nonce_sha256),
                "send_kind": payload.send_kind,
                "transport_sequence": payload.transport_sequence,
                "ciphertext_batch_sha256": payload.ciphertext_batch_sha256,
                "ciphertext_octets": payload.ciphertext_octets,
                "ciphertext_start_octet": payload.ciphertext_start_octet,
                "requested_octets": payload.requested_octets,
                "exact_slice_sha256": payload.exact_slice_sha256,
                "deadline_ns": payload.shutdown_deadline_monotonic_ns,
                "would_block_count": payload.would_block_count,
                "driver_evidence_id": driver_evidence_id,
            }
        )

    @staticmethod
    def _assert_dual_deadline_classification_v49e(
        *,
        observed_at: datetime,
        observed_monotonic_ns: int,
        deadline_at: datetime,
        deadline_monotonic_ns: int,
        classification: LocalShutdownDeadlineClassificationV49E,
        context: str,
    ) -> None:
        wall_due = observed_at >= deadline_at
        monotonic_due = observed_monotonic_ns >= deadline_monotonic_ns
        expected = (
            LocalShutdownDeadlineClassificationV49E.BOTH_DUE
            if wall_due and monotonic_due
            else (
                LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                if wall_due != monotonic_due
                else LocalShutdownDeadlineClassificationV49E.OWNER_EVIDENCE_BEFORE_BOTH_CLOCKS
            )
        )
        if classification is not expected:
            raise PhysicalProjectionV4ConflictError(
                f"{context} changes the exact dual-clock deadline classification"
            )

    @staticmethod
    def _ciphertext_slice_sha256_v49e(
        *,
        encoded_chunks: Sequence[str],
        start: int,
        octets: int,
    ) -> str:
        try:
            ciphertext = b"".join(
                base64.b64decode(value, validate=True) for value in encoded_chunks
            )
        except Exception as exc:  # pragma: no cover - payload constructor guards this
            raise PhysicalProjectionV4ConflictError(
                "physical send evidence contains undecodable ciphertext"
            ) from exc
        return hashlib.sha256(ciphertext[start : start + octets]).hexdigest()

    def _assert_actor_shutdown_evidence_projection_v49e(
        self,
        event: TransportActorEventV49C,
    ) -> None:
        """Replay command propagation and sealed physical deadline evidence."""

        payload = event.payload
        command_event_id = getattr(
            payload,
            "local_shutdown_command_started_event_id",
            None,
        )
        command: LocalShutdownCommandStartedPayloadV49E | None = None
        if command_event_id is not None:
            _, command = self._load_actor_shutdown_command_v49e(
                transport_session_id=event.transport_session_id,
                command_event_id=command_event_id,
            )
            if (
                hasattr(payload, "shutdown_deadline_monotonic_ns")
                and payload.shutdown_deadline_monotonic_ns
                != command.shutdown_deadline_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "shutdown evidence changes the command BOOTTIME deadline"
                )

        if type(payload) is TlsProtocolOperationStartedPayloadV49E:
            assert command is not None
            if (
                payload.started_at >= command.shutdown_deadline_at
                or payload.started_monotonic_ns
                >= command.shutdown_deadline_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "TLS operation starts outside its command horizon"
                )
            return

        if type(payload) is LocalShutdownDeadlineEvidencePayloadV49E:
            assert command is not None
            expected_owner_id = self._owner_deadline_no_observation_id_v49e(
                transport_session_id=event.transport_session_id,
                kernel_socket_identity=payload.kernel_socket_identity,
                driver_evidence_nonce_sha256=payload.driver_evidence_nonce_sha256,
                operation=payload.operation,
                deadline_ns=payload.shutdown_deadline_monotonic_ns,
            )
            wall_due = payload.observed_at >= command.shutdown_deadline_at
            monotonic_due = (
                payload.observed_monotonic_ns >= command.shutdown_deadline_monotonic_ns
            )
            expected_classification = (
                LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                if wall_due and monotonic_due
                else (
                    LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                    if wall_due != monotonic_due
                    else LocalShutdownDeadlineClassificationV49E.OWNER_EVIDENCE_BEFORE_BOTH_CLOCKS
                )
            )
            if (
                payload.owner_evidence_id != expected_owner_id
                or payload.classification is not expected_classification
                or payload.observed_at != event.recorded_at
                or payload.observed_monotonic_ns != event.recorded_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "local shutdown deadline evidence changes command, owner, "
                    "clock classification, or event observation"
                )
            return

        if type(payload) is TerminalIngressFailurePayloadV49E:
            assert command is not None
            expected_driver_id = self._driver_deadline_after_progress_id_v49e(
                driver_evidence_nonce_sha256=(payload.driver_evidence_nonce_sha256),
                operation=payload.operation,
                deadline_ns=payload.shutdown_deadline_monotonic_ns,
                ciphertext_octets_received=payload.ciphertext_octets_received,
                ciphertext_sha256=payload.ciphertext_sha256,
            )
            expected_owner_id = self._owner_deadline_after_progress_id_v49e(
                transport_session_id=event.transport_session_id,
                kernel_socket_identity=payload.kernel_socket_identity,
                driver_evidence_nonce_sha256=payload.driver_evidence_nonce_sha256,
                operation=payload.operation,
                deadline_ns=payload.shutdown_deadline_monotonic_ns,
                ciphertext_octets_received=payload.ciphertext_octets_received,
                ciphertext_sha256=payload.ciphertext_sha256,
                driver_evidence_id=payload.driver_evidence_id,
            )
            if (
                payload.driver_evidence_id != expected_driver_id
                or payload.owner_evidence_id != expected_owner_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "terminal ingress failure changes its sealed driver/owner evidence"
                )
            self._assert_dual_deadline_classification_v49e(
                observed_at=payload.observed_at,
                observed_monotonic_ns=payload.observed_monotonic_ns,
                deadline_at=command.shutdown_deadline_at,
                deadline_monotonic_ns=command.shutdown_deadline_monotonic_ns,
                classification=(
                    LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                    if payload.failure_kind
                    is TerminalIngressFailureKindV49E.CLOCK_DISAGREEMENT
                    else LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                ),
                context="terminal ingress failure",
            )
            return

        if type(payload) is TlsProtocolOperationFailedPayloadV49E:
            started_event = self._load_actor_event_exact_v49e(
                transport_session_id=event.transport_session_id,
                event_id=payload.tls_protocol_operation_started_event_id,
                event_kind=TransportActorEventKindV49C.TLS_PROTOCOL_OPERATION_STARTED,
                payload_type=TlsProtocolOperationStartedPayloadV49E,
                context="TLS operation failure",
            )
            started = started_event.payload
            assert type(started) is TlsProtocolOperationStartedPayloadV49E
            _, command = self._load_actor_shutdown_command_v49e(
                transport_session_id=event.transport_session_id,
                command_event_id=started.local_shutdown_command_started_event_id,
            )
            if payload.shutdown_deadline_monotonic_ns != (
                command.shutdown_deadline_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "TLS failure changes its command deadline"
                )
            if (
                payload.failure_kind
                is TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_NO_OBSERVATION
            ):
                expected = self._owner_deadline_no_observation_id_v49e(
                    transport_session_id=event.transport_session_id,
                    kernel_socket_identity=(
                        payload.deadline_no_observation_kernel_socket_identity
                    ),
                    driver_evidence_nonce_sha256=(payload.driver_evidence_nonce_sha256),
                    operation=payload.deadline_no_observation_operation,
                    deadline_ns=payload.shutdown_deadline_monotonic_ns,
                )
                if payload.deadline_no_observation_owner_evidence_id != expected:
                    raise PhysicalProjectionV4ConflictError(
                        "TLS no-observation failure changes owner evidence"
                    )
            elif (
                payload.failure_kind
                is TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_AFTER_PROGRESS
            ):
                expected_driver = self._driver_deadline_after_progress_id_v49e(
                    driver_evidence_nonce_sha256=(payload.driver_evidence_nonce_sha256),
                    operation=payload.deadline_after_progress_operation,
                    deadline_ns=payload.shutdown_deadline_monotonic_ns,
                    ciphertext_octets_received=(
                        payload.deadline_after_progress_ciphertext_octets
                    ),
                    ciphertext_sha256=(
                        payload.deadline_after_progress_ciphertext_sha256
                    ),
                )
                expected = self._owner_deadline_after_progress_id_v49e(
                    transport_session_id=event.transport_session_id,
                    kernel_socket_identity=(
                        payload.deadline_after_progress_kernel_socket_identity
                    ),
                    driver_evidence_nonce_sha256=(payload.driver_evidence_nonce_sha256),
                    operation=payload.deadline_after_progress_operation,
                    deadline_ns=payload.shutdown_deadline_monotonic_ns,
                    ciphertext_octets_received=(
                        payload.deadline_after_progress_ciphertext_octets
                    ),
                    ciphertext_sha256=(
                        payload.deadline_after_progress_ciphertext_sha256
                    ),
                    driver_evidence_id=expected_driver,
                )
                if (
                    payload.deadline_after_progress_driver_evidence_id
                    != expected_driver
                    or payload.deadline_after_progress_owner_evidence_id != expected
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "TLS after-progress failure changes driver/owner evidence"
                    )
            elif (
                payload.failure_kind
                is TlsProtocolOperationFailureKindV49E.UNSENDABLE_POST_HANDSHAKE_OUTPUT_AFTER_SHUT_WR
            ):
                expected_driver = sha256_digest(
                    {
                        "domain": "RiskYieldMMUnsendableTlsPostHandshakeOutputV4_9E",
                        "output_sequence": (payload.unsendable_driver_output_sequence),
                        "driver_evidence_nonce_sha256": (
                            payload.driver_evidence_nonce_sha256
                        ),
                        "ciphertext_sha256": (payload.unsendable_ciphertext_sha256),
                        "ciphertext_octets": payload.unsendable_ciphertext_octets,
                    }
                )
                expected_owner = sha256_digest(
                    {
                        "domain": "RiskYieldMMOwnerUnsendableTlsPostHandshakeOutputV4_9E",
                        "transport_session_id": event.transport_session_id,
                        "kernel_socket_identity": (
                            payload.unsendable_kernel_socket_identity
                        ),
                        "driver_unsendable_output_id": expected_driver,
                        "driver_output_sequence": (
                            payload.unsendable_driver_output_sequence
                        ),
                        "driver_evidence_nonce_sha256": (
                            payload.driver_evidence_nonce_sha256
                        ),
                        "ciphertext_sha256": (payload.unsendable_ciphertext_sha256),
                        "ciphertext_octets": payload.unsendable_ciphertext_octets,
                    }
                )
                if (
                    payload.unsendable_driver_evidence_id != expected_driver
                    or payload.unsendable_owner_evidence_id != expected_owner
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "unsendable TLS failure changes driver/owner evidence"
                    )
            deadline_kind = payload.failure_kind in {
                TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_NO_OBSERVATION,
                TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_AFTER_PROGRESS,
            }
            if deadline_kind:
                self._assert_dual_deadline_classification_v49e(
                    observed_at=payload.observed_at,
                    observed_monotonic_ns=payload.observed_monotonic_ns,
                    deadline_at=command.shutdown_deadline_at,
                    deadline_monotonic_ns=command.shutdown_deadline_monotonic_ns,
                    classification=payload.deadline_classification,
                    context="TLS operation failure",
                )
            return

        if type(payload) is KernelSendFailurePayloadV49E:
            self._assert_actor_kernel_send_failure_projection_v49e(event, payload)
            return
        if type(payload) is TlsControlKernelSendFailurePayloadV49E:
            self._assert_actor_tls_control_send_failure_projection_v49e(
                event,
                payload,
            )
            return

        if type(payload) is TcpHalfCloseResultPayloadV49E:
            attempt_event = self._load_actor_event_exact_v49e(
                transport_session_id=event.transport_session_id,
                event_id=payload.tcp_half_close_attempt_event_id,
                event_kind=TransportActorEventKindV49C.TCP_HALF_CLOSE_ATTEMPT,
                payload_type=TcpHalfCloseAttemptPayloadV49E,
                context="TCP half-close result",
            )
            attempt = attempt_event.payload
            assert type(attempt) is TcpHalfCloseAttemptPayloadV49E
            _, command = self._load_actor_shutdown_command_v49e(
                transport_session_id=event.transport_session_id,
                command_event_id=attempt.local_shutdown_command_started_event_id,
            )
            if payload.result_kind in {
                TcpHalfCloseResultKindV49E.DEADLINE_EXPIRED_BEFORE_SYSCALL,
                TcpHalfCloseResultKindV49E.CLOCK_DISAGREEMENT,
            }:
                self._assert_dual_deadline_classification_v49e(
                    observed_at=payload.observed_at,
                    observed_monotonic_ns=payload.observed_monotonic_ns,
                    deadline_at=command.shutdown_deadline_at,
                    deadline_monotonic_ns=attempt.shutdown_deadline_monotonic_ns,
                    classification=(
                        LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                        if payload.result_kind
                        is TcpHalfCloseResultKindV49E.CLOCK_DISAGREEMENT
                        else LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                    ),
                    context="TCP half-close result",
                )

    def _assert_actor_kernel_send_failure_projection_v49e(
        self,
        event: TransportActorEventV49C,
        payload: KernelSendFailurePayloadV49E,
    ) -> None:
        attempt_event = self._load_actor_event_exact_v49e(
            transport_session_id=event.transport_session_id,
            event_id=payload.kernel_send_attempt_event_id,
            event_kind=TransportActorEventKindV49C.KERNEL_SEND_ATTEMPT,
            payload_type=KernelSendAttemptPayloadV49C,
            context="kernel send failure",
        )
        attempt = attempt_event.payload
        assert type(attempt) is KernelSendAttemptPayloadV49C
        tls_event = self._load_actor_event_exact_v49e(
            transport_session_id=event.transport_session_id,
            event_id=attempt.tls_ciphertext_prepared_event_id,
            event_kind=TransportActorEventKindV49C.TLS_CIPHERTEXT_PREPARED,
            payload_type=TlsCiphertextPreparedPayloadV49C,
            context="kernel send failure",
        )
        tls = tls_event.payload
        assert type(tls) is TlsCiphertextPreparedPayloadV49C
        wire_event = self._load_actor_event_exact_v49e(
            transport_session_id=event.transport_session_id,
            event_id=tls.outbound_wire_prepared_event_id,
            event_kind=TransportActorEventKindV49C.OUTBOUND_WIRE_PREPARED,
            payload_type=OutboundWirePreparedPayloadV49C,
            context="kernel send failure",
        )
        wire = wire_event.payload
        assert type(wire) is OutboundWirePreparedPayloadV49C
        exact_names = (
            "tls_ciphertext_prepared_event_id",
            "kernel_attempt_ordinal",
            "ciphertext_batch_sha256",
            "ciphertext_octets",
            "ciphertext_start_octet",
            "requested_octets",
        )
        command: LocalShutdownCommandStartedPayloadV49E | None = None
        if wire.wire_origin is OutboundWireOriginV49C.LOCAL_TERMINAL_COMMAND:
            if payload.local_shutdown_command_started_event_id is None:
                raise PhysicalProjectionV4ConflictError(
                    "local Close send failure loses its command"
                )
            _, command = self._load_actor_shutdown_command_v49e(
                transport_session_id=event.transport_session_id,
                command_event_id=payload.local_shutdown_command_started_event_id,
            )
            deadline_at = command.shutdown_deadline_at
            deadline_ns = command.shutdown_deadline_monotonic_ns
            expected_send_kind = "LOCAL_WEBSOCKET_CLOSE"
        else:
            deadline_at = wire.send_not_after
            deadline_ns = wire.send_not_after_monotonic_ns
            expected_send_kind = "AUTOMATIC_WEBSOCKET_CLOSE"
        if (
            any(
                getattr(payload, name) != getattr(attempt, name) for name in exact_names
            )
            or payload.shutdown_deadline_monotonic_ns != deadline_ns
        ):
            raise PhysicalProjectionV4ConflictError(
                "kernel send failure changes its exact attempt or deadline"
            )
        self._assert_send_failure_evidence_v49e(
            event=event,
            payload=payload,
            encoded_chunks=tls.ordered_ciphertext_chunks_base64,
            deadline_at=deadline_at,
            deadline_ns=deadline_ns,
            expected_send_kind=expected_send_kind,
        )

    def _assert_actor_tls_control_send_failure_projection_v49e(
        self,
        event: TransportActorEventV49C,
        payload: TlsControlKernelSendFailurePayloadV49E,
    ) -> None:
        attempt_event = self._load_actor_event_exact_v49e(
            transport_session_id=event.transport_session_id,
            event_id=payload.tls_control_kernel_send_attempt_event_id,
            event_kind=TransportActorEventKindV49C.TLS_CONTROL_KERNEL_SEND_ATTEMPT,
            payload_type=TlsControlKernelSendAttemptPayloadV49E,
            context="TLS-control send failure",
        )
        attempt = attempt_event.payload
        assert type(attempt) is TlsControlKernelSendAttemptPayloadV49E
        control_event = self._load_actor_event_exact_v49e(
            transport_session_id=event.transport_session_id,
            event_id=attempt.tls_control_ciphertext_prepared_event_id,
            event_kind=TransportActorEventKindV49C.TLS_CONTROL_CIPHERTEXT_PREPARED,
            payload_type=TlsControlCiphertextPreparedPayloadV49E,
            context="TLS-control send failure",
        )
        control = control_event.payload
        assert type(control) is TlsControlCiphertextPreparedPayloadV49E
        _, command = self._load_actor_shutdown_command_v49e(
            transport_session_id=event.transport_session_id,
            command_event_id=payload.local_shutdown_command_started_event_id,
        )
        exact_names = (
            "tls_control_ciphertext_prepared_event_id",
            "local_shutdown_command_started_event_id",
            "shutdown_deadline_monotonic_ns",
            "kernel_attempt_ordinal",
            "ciphertext_batch_sha256",
            "ciphertext_octets",
            "ciphertext_start_octet",
            "requested_octets",
        )
        if any(
            getattr(payload, name) != getattr(attempt, name) for name in exact_names
        ):
            raise PhysicalProjectionV4ConflictError(
                "TLS-control send failure changes its exact attempt"
            )
        self._assert_send_failure_evidence_v49e(
            event=event,
            payload=payload,
            encoded_chunks=control.ordered_ciphertext_chunks_base64,
            deadline_at=command.shutdown_deadline_at,
            deadline_ns=command.shutdown_deadline_monotonic_ns,
            expected_send_kind="TLS_CONTROL",
        )

    def _assert_send_failure_evidence_v49e(
        self,
        *,
        event: TransportActorEventV49C,
        payload: KernelSendFailurePayloadV49E | TlsControlKernelSendFailurePayloadV49E,
        encoded_chunks: Sequence[str],
        deadline_at: datetime,
        deadline_ns: int,
        expected_send_kind: str,
    ) -> None:
        self._assert_dual_deadline_classification_v49e(
            observed_at=payload.observed_at,
            observed_monotonic_ns=payload.observed_monotonic_ns,
            deadline_at=deadline_at,
            deadline_monotonic_ns=deadline_ns,
            classification=(
                LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                if payload.failure_kind is KernelSendFailureKindV49E.CLOCK_DISAGREEMENT
                else LocalShutdownDeadlineClassificationV49E.BOTH_DUE
            ),
            context="kernel send failure",
        )
        if (
            payload.failure_kind
            is KernelSendFailureKindV49E.DEADLINE_EXPIRED_BEFORE_SYSCALL
        ):
            expected = self._owner_deadline_no_observation_id_v49e(
                transport_session_id=event.transport_session_id,
                kernel_socket_identity=payload.kernel_socket_identity,
                driver_evidence_nonce_sha256=payload.driver_evidence_nonce_sha256,
                operation=payload.owner_deadline_operation,
                deadline_ns=payload.shutdown_deadline_monotonic_ns,
            )
            if payload.owner_evidence_id != expected:
                raise PhysicalProjectionV4ConflictError(
                    "pre-syscall send failure changes owner evidence"
                )
        elif (
            payload.failure_kind
            is KernelSendFailureKindV49E.DEADLINE_EXPIRED_NO_KERNEL_ACCEPTANCE
        ):
            exact_slice = self._ciphertext_slice_sha256_v49e(
                encoded_chunks=encoded_chunks,
                start=payload.ciphertext_start_octet,
                octets=payload.requested_octets,
            )
            expected_driver = self._driver_send_deadline_id_v49e(payload=payload)
            expected_owner = self._owner_send_deadline_id_v49e(
                transport_session_id=event.transport_session_id,
                payload=payload,
                driver_evidence_id=expected_driver,
            )
            if (
                payload.exact_slice_sha256 != exact_slice
                or payload.driver_evidence_id != expected_driver
                or payload.owner_evidence_id != expected_owner
                or payload.send_kind != expected_send_kind
            ):
                raise PhysicalProjectionV4ConflictError(
                    "no-kernel-acceptance failure changes exact ciphertext evidence"
                )

    @staticmethod
    def _actor_terminal_state_v49e(
        chain: Sequence[TransportActorEventV49C],
    ) -> TerminalStateV49C:
        if not chain:
            raise PhysicalProjectionV4ConflictError(
                "terminal convergence requires a non-empty actor chain"
            )
        return reduce_transport_actor_chain_v49e(chain)

    @staticmethod
    def _decode_actor_client_frame_payload_v49e(
        wire: OutboundWirePreparedPayloadV49C,
    ) -> bytes:
        """Decode the already-canonical exact masked client frame bytes."""

        try:
            frame = b"".join(
                base64.b64decode(value, validate=True)
                for value in wire.ordered_wire_chunks_base64
            )
        except Exception as exc:
            raise PhysicalProjectionV4ConflictError(
                "outbound Close wire cannot be decoded from canonical chunks"
            ) from exc
        if len(frame) < 6 or frame[0] & 0x0F != 0x08 or not frame[1] & 0x80:
            raise PhysicalProjectionV4ConflictError(
                "outbound Close wire is not one exact masked client Close"
            )
        payload_indicator = frame[1] & 0x7F
        cursor = 2
        if payload_indicator == 126:
            if len(frame) < cursor + 2:
                raise PhysicalProjectionV4ConflictError(
                    "outbound Close wire lacks its extended length"
                )
            payload_octets = int.from_bytes(frame[cursor : cursor + 2], "big")
            cursor += 2
        elif payload_indicator == 127:
            if len(frame) < cursor + 8:
                raise PhysicalProjectionV4ConflictError(
                    "outbound Close wire lacks its extended length"
                )
            payload_octets = int.from_bytes(frame[cursor : cursor + 8], "big")
            cursor += 8
        else:
            payload_octets = payload_indicator
        if len(frame) != cursor + 4 + payload_octets:
            raise PhysicalProjectionV4ConflictError(
                "outbound Close wire length differs from its exact frame"
            )
        mask = frame[cursor : cursor + 4]
        encoded = frame[cursor + 4 :]
        payload = bytes(octet ^ mask[index % 4] for index, octet in enumerate(encoded))
        if (
            len(payload) != wire.logical_payload_octets
            or hashlib.sha256(payload).hexdigest() != wire.logical_payload_sha256
        ):
            raise PhysicalProjectionV4ConflictError(
                "outbound Close payload differs from canonical logical metadata"
            )
        return payload

    @staticmethod
    def _close_metadata_v49e(payload: bytes) -> tuple[int | None, str | None]:
        if not payload:
            return None, None
        if len(payload) < 2:
            raise PhysicalProjectionV4ConflictError(
                "initiating WebSocket Close payload has no complete status code"
            )
        return int.from_bytes(payload[:2], "big"), hashlib.sha256(
            payload[2:]
        ).hexdigest()

    def _first_actor_close_v49e(
        self, chain: Sequence[TransportActorEventV49C]
    ) -> tuple[TransportSessionTerminationReasonV4, int | None, str | None]:
        """Derive origin from the first exact durable WS Close actor marker."""

        peer_close_payloads: list[bytes] = []
        local_close_payloads: dict[str, bytes] = {}
        for event in chain:
            payload = event.payload
            if (
                event.event_kind is TransportActorEventKindV49C.PARSER_TRANSITION
                and type(payload) is ParserTransitionPayloadV49C
                and payload.feed_unit_kind is ParserFeedUnitKindV49C.COMPLETE_FRAME
                and payload.frame is not None
                and payload.frame.opcode is WebSocketOpcodeV49C.CLOSE
            ):
                exact_payload = self._assert_actor_parser_raw_bytes_v49d(event)
                if exact_payload is None:
                    raise PhysicalProjectionV4ConflictError(
                        "peer Close lacks its exact canonical RAW payload"
                    )
                peer_close_payloads.append(exact_payload)
            elif (
                event.event_kind is TransportActorEventKindV49C.OUTBOUND_WIRE_PREPARED
                and type(payload) is OutboundWirePreparedPayloadV49C
                and payload.logical_opcode is WebSocketOpcodeV49C.CLOSE
            ):
                local_close_payloads[payload.outbound_operation_id] = (
                    self._decode_actor_client_frame_payload_v49e(payload)
                )
            elif (
                event.event_kind is TransportActorEventKindV49C.TERMINAL_TRANSITION
                and type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.WS_CLOSE_RECEIVED
            ):
                if not peer_close_payloads:
                    raise PhysicalProjectionV4ConflictError(
                        "peer Close marker lacks its ordered parser predecessor"
                    )
                exact_payload = peer_close_payloads.pop(0)
                code, digest = self._close_metadata_v49e(exact_payload)
                return TransportSessionTerminationReasonV4.REMOTE_CLOSE, code, digest
            elif (
                event.event_kind is TransportActorEventKindV49C.TERMINAL_TRANSITION
                and type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.WS_CLOSE_SENT
            ):
                exact_payload = local_close_payloads.get(payload.obligation_id or "")
                if exact_payload is None:
                    raise PhysicalProjectionV4ConflictError(
                        "local Close marker lacks its exact wire predecessor"
                    )
                code, digest = self._close_metadata_v49e(exact_payload)
                return TransportSessionTerminationReasonV4.LOCAL_CLOSE, code, digest
        raise PhysicalProjectionV4ConflictError(
            "clean terminal actor chain has no durable WebSocket Close marker"
        )

    @staticmethod
    def _payload_clock_v49e(payload: Any) -> tuple[datetime, int] | None:
        if type(payload) is AckDeadlineExpiredPayloadV49E:
            return payload.observed_at, payload.observed_monotonic_ns
        if type(payload) is LocalShutdownCommandStartedPayloadV49E:
            return payload.started_at, payload.started_monotonic_ns
        if type(payload) in {
            KernelSendFailurePayloadV49E,
            LocalShutdownDeadlineEvidencePayloadV49E,
            TerminalIngressFailurePayloadV49E,
            TlsControlKernelSendFailurePayloadV49E,
        }:
            return payload.observed_at, payload.observed_monotonic_ns
        if type(payload) is TlsProtocolOperationFailedPayloadV49E:
            return payload.observed_at, payload.observed_monotonic_ns
        if type(payload) is ParserTransitionPayloadV49C:
            return payload.processed_at, payload.processed_monotonic_ns
        if type(payload) is OutboundDispatchCompletedPayloadV49C:
            return payload.completed_at, payload.completed_monotonic_ns
        if type(payload) is TlsControlKernelSendResultPayloadV49E:
            return payload.observed_at, payload.observed_monotonic_ns
        if type(payload) is TlsShutdownObservedPayloadV49E:
            return payload.observed_at, payload.observed_monotonic_ns
        if type(payload) is TcpHalfCloseResultPayloadV49E:
            return payload.observed_at, payload.observed_monotonic_ns
        return None

    def _clean_decisive_clock_v49e(
        self, chain: Sequence[TransportActorEventV49C]
    ) -> tuple[datetime, int]:
        wires = {
            event.transport_actor_event_id: event.payload
            for event in chain
            if event.event_kind is TransportActorEventKindV49C.OUTBOUND_WIRE_PREPARED
            and type(event.payload) is OutboundWirePreparedPayloadV49C
        }
        controls = {
            event.transport_actor_event_id: event.payload
            for event in chain
            if event.event_kind
            is TransportActorEventKindV49C.TLS_CONTROL_CIPHERTEXT_PREPARED
            and type(event.payload) is TlsControlCiphertextPreparedPayloadV49E
        }
        candidates: list[TransportActorEventV49C] = []
        for event in chain:
            payload = event.payload
            if type(payload) is OutboundDispatchCompletedPayloadV49C:
                wire = wires.get(payload.outbound_wire_prepared_event_id)
                if (
                    type(wire) is OutboundWirePreparedPayloadV49C
                    and wire.logical_opcode is WebSocketOpcodeV49C.CLOSE
                ):
                    candidates.append(event)
            elif type(payload) is TlsControlKernelSendResultPayloadV49E:
                control = controls.get(payload.tls_control_ciphertext_prepared_event_id)
                if (
                    type(control) is TlsControlCiphertextPreparedPayloadV49E
                    and control.control_kind.value == "LOCAL_CLOSE_NOTIFY"
                    and payload.resulting_ciphertext_offset == control.ciphertext_octets
                ):
                    candidates.append(event)
            elif type(payload) is TlsShutdownObservedPayloadV49E:
                candidates.append(event)
            elif (
                type(payload) is TcpHalfCloseResultPayloadV49E
                and payload.result_kind is TcpHalfCloseResultKindV49E.KERNEL_ACCEPTED
            ):
                candidates.append(event)
        if not candidates:
            raise PhysicalProjectionV4ConflictError(
                "clean actor terminal lacks a decisive physical observation"
            )
        decisive = max(candidates, key=lambda item: item.actor_sequence)
        clock = self._payload_clock_v49e(decisive.payload)
        if clock is None:  # pragma: no cover - candidate exhaustiveness guard
            raise AssertionError("clean decisive event has no physical clock")
        return clock

    def _negative_decisive_clock_v49e(
        self,
        chain: Sequence[TransportActorEventV49C],
        *,
        cause: str | None,
    ) -> tuple[datetime, int] | None:
        """Find the physical/deadline fact behind a later terminal marker."""

        def matches(payload: Any) -> bool:
            if cause == V49E_LOCAL_SHUTDOWN_CLOCK_DISAGREEMENT_CAUSE:
                return (
                    (
                        type(payload) is LocalShutdownDeadlineEvidencePayloadV49E
                        and payload.classification
                        is LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                    )
                    or (
                        type(payload)
                        in {
                            KernelSendFailurePayloadV49E,
                            TlsControlKernelSendFailurePayloadV49E,
                        }
                        and payload.failure_kind
                        is KernelSendFailureKindV49E.CLOCK_DISAGREEMENT
                    )
                    or (
                        type(payload) is TlsProtocolOperationFailedPayloadV49E
                        and payload.deadline_classification
                        is LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT
                    )
                    or (
                        type(payload) is TerminalIngressFailurePayloadV49E
                        and payload.failure_kind
                        is TerminalIngressFailureKindV49E.CLOCK_DISAGREEMENT
                    )
                    or (
                        type(payload) is TcpHalfCloseResultPayloadV49E
                        and payload.result_kind
                        is TcpHalfCloseResultKindV49E.CLOCK_DISAGREEMENT
                    )
                )
            if cause == V49E_LOCAL_SHUTDOWN_COMMAND_DEADLINE_EXPIRED_CAUSE:
                return (
                    type(payload) is LocalShutdownDeadlineEvidencePayloadV49E
                    and payload.classification
                    is LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                ) or (
                    type(payload)
                    in {
                        KernelSendFailurePayloadV49E,
                        TlsControlKernelSendFailurePayloadV49E,
                    }
                    and payload.failure_kind
                    is not KernelSendFailureKindV49E.CLOCK_DISAGREEMENT
                    and payload.local_shutdown_command_started_event_id is not None
                )
            if cause == V49E_WEBSOCKET_CLOSE_DEADLINE_EXPIRED_CAUSE:
                return (
                    type(payload) is KernelSendFailurePayloadV49E
                    and payload.failure_kind
                    is not KernelSendFailureKindV49E.CLOCK_DISAGREEMENT
                    and payload.local_shutdown_command_started_event_id is None
                )
            if cause == V49E_TLS_SHUTDOWN_DEADLINE_EXPIRED_CAUSE:
                return (
                    type(payload) is TlsProtocolOperationFailedPayloadV49E
                    and payload.failure_kind
                    is TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_NO_OBSERVATION
                    and payload.deadline_classification
                    is LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                )
            if cause == V49E_TLS_SHUTDOWN_DEADLINE_EXPIRED_AFTER_PROGRESS_CAUSE:
                return (
                    type(payload) is TlsProtocolOperationFailedPayloadV49E
                    and payload.failure_kind
                    is TlsProtocolOperationFailureKindV49E.DEADLINE_EXPIRED_AFTER_PROGRESS
                    and payload.deadline_classification
                    is LocalShutdownDeadlineClassificationV49E.BOTH_DUE
                )
            if (
                cause
                == V49E_TERMINAL_CLOSE_INGRESS_DEADLINE_EXPIRED_AFTER_PROGRESS_CAUSE
            ):
                return (
                    type(payload) is TerminalIngressFailurePayloadV49E
                    and payload.failure_kind
                    is TerminalIngressFailureKindV49E.DEADLINE_EXPIRED_AFTER_PROGRESS
                )
            if cause == V49E_TCP_HALF_CLOSE_DEADLINE_EXPIRED_BEFORE_SYSCALL_CAUSE:
                return (
                    type(payload) is TcpHalfCloseResultPayloadV49E
                    and payload.result_kind
                    is TcpHalfCloseResultKindV49E.DEADLINE_EXPIRED_BEFORE_SYSCALL
                )
            if cause == V49E_TLS_OPERATION_DRIVER_ERROR_CAUSE:
                return (
                    type(payload) is LocalShutdownDeadlineEvidencePayloadV49E
                    and payload.classification
                    is LocalShutdownDeadlineClassificationV49E.OWNER_EVIDENCE_BEFORE_BOTH_CLOCKS
                ) or (
                    type(payload) is TlsProtocolOperationFailedPayloadV49E
                    and (
                        payload.failure_kind
                        is TlsProtocolOperationFailureKindV49E.DRIVER_ERROR
                        or payload.deadline_classification
                        is LocalShutdownDeadlineClassificationV49E.OWNER_EVIDENCE_BEFORE_BOTH_CLOCKS
                    )
                )
            if cause == V49E_TLS_POST_HANDSHAKE_OUTPUT_AFTER_SHUT_WR_CAUSE:
                return (
                    type(payload) is TlsProtocolOperationFailedPayloadV49E
                    and payload.failure_kind
                    is TlsProtocolOperationFailureKindV49E.UNSENDABLE_POST_HANDSHAKE_OUTPUT_AFTER_SHUT_WR
                )
            if cause == V49E_TCP_HALF_CLOSE_ERROR_CAUSE:
                return (
                    type(payload) is TcpHalfCloseResultPayloadV49E
                    and payload.result_kind is TcpHalfCloseResultKindV49E.ERROR
                )
            return False

        for candidate in reversed(tuple(chain)[:-1]):
            if matches(candidate.payload):
                clock = self._payload_clock_v49e(candidate.payload)
                if clock is None:  # pragma: no cover - closed predicate guard
                    raise AssertionError("negative decisive event lacks its clock")
                return clock
        return None

    def _derive_actor_terminal_bridge_v49e(
        self, chain: Sequence[TransportActorEventV49C]
    ) -> _ActorTerminalBridgeV49E:
        exact_chain = tuple(chain)
        if not exact_chain:
            raise PhysicalProjectionV4ConflictError(
                "terminal convergence requires one actor prefix"
            )
        try:
            validate_transport_actor_chain_v49c(exact_chain)
        except CanonicalizationError as exc:
            raise PhysicalProjectionV4ConflictError(
                "terminal convergence does not extend the exact actor chain"
            ) from exc
        terminal_event = exact_chain[-1]
        if (
            terminal_event.event_kind
            is not TransportActorEventKindV49C.TERMINAL_TRANSITION
            or type(terminal_event.payload) is not TerminalTransitionPayloadV49C
        ):
            raise PhysicalProjectionV4ConflictError(
                "terminal convergence tail is not one decisive actor transition"
            )
        state = self._actor_terminal_state_v49e(exact_chain)
        outcome = state.terminal_outcome
        if outcome is None:
            raise PhysicalProjectionV4ConflictError(
                "terminal convergence tail does not produce a final outcome"
            )

        close_code = None
        close_reason_digest = None
        if outcome is TerminalOutcomeV49C.CLEAN_ALL_LAYERS:
            reason, close_code, close_reason_digest = self._first_actor_close_v49e(
                exact_chain
            )
            detected_at, detected_ns = self._clean_decisive_clock_v49e(exact_chain)
        else:
            cause = terminal_event.payload.cause_code
            if (
                outcome is TerminalOutcomeV49C.TIMEOUT
                and cause == "ACK_DEADLINE_EXPIRED"
            ):
                reason = TransportSessionTerminationReasonV4.ACK_TIMEOUT
                deadlines = tuple(
                    event
                    for event in exact_chain
                    if event.event_kind
                    is TransportActorEventKindV49C.ACK_DEADLINE_EXPIRED
                    and type(event.payload) is AckDeadlineExpiredPayloadV49E
                )
                if (
                    not deadlines
                    or deadlines[-1].actor_sequence >= terminal_event.actor_sequence
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "ACK timeout terminal lacks its earlier deadline observation"
                    )
                clock = self._payload_clock_v49e(deadlines[-1].payload)
            elif (
                outcome is TerminalOutcomeV49C.TIMEOUT
                and cause == V49E_WEBSOCKET_CLOSE_DEADLINE_EXPIRED_CAUSE
            ):
                reason = TransportSessionTerminationReasonV4.TRANSPORT_ERROR
                clock = self._negative_decisive_clock_v49e(
                    exact_chain,
                    cause=cause,
                ) or (
                    terminal_event.recorded_at,
                    terminal_event.recorded_monotonic_ns,
                )
            elif outcome is TerminalOutcomeV49C.STORAGE_FAILURE:
                reason = TransportSessionTerminationReasonV4.STORAGE_FAILURE
                clock = None
            elif (
                outcome is TerminalOutcomeV49C.FATAL
                and cause == _V49E_BACKPRESSURE_CAUSE
            ):
                reason = TransportSessionTerminationReasonV4.BACKPRESSURE
                clock = None
            elif (
                outcome is TerminalOutcomeV49C.FATAL
                and cause == _V49E_PROCESS_RESTART_CAUSE
            ):
                reason = TransportSessionTerminationReasonV4.PROCESS_RESTART
                # A restart terminal is itself the first durable observation of
                # process loss.  Reusing the predecessor's physical clock would
                # backdate the signed legacy bridge and make restart recovery
                # depend on the arbitrary payload type at the old actor tail.
                clock = (
                    terminal_event.recorded_at,
                    terminal_event.recorded_monotonic_ns,
                )
            elif (
                outcome is TerminalOutcomeV49C.FATAL and cause == _V49E_SUPERSEDED_CAUSE
            ):
                reason = TransportSessionTerminationReasonV4.SUPERSEDED
                clock = None
            else:
                reason = TransportSessionTerminationReasonV4.TRANSPORT_ERROR
                clock = self._negative_decisive_clock_v49e(
                    exact_chain,
                    cause=cause,
                )
            if clock is None and len(exact_chain) >= 2:
                clock = self._payload_clock_v49e(exact_chain[-2].payload)
            if clock is None:
                detected_at = terminal_event.recorded_at
                detected_ns = terminal_event.recorded_monotonic_ns
            else:
                detected_at, detected_ns = clock

        return _ActorTerminalBridgeV49E(
            reason=reason,
            close_code=close_code,
            close_reason_digest=close_reason_digest,
            detected_at=detected_at,
            detected_monotonic_ns=detected_ns,
            detected_monotonic_clock_domain_id=(
                terminal_event.monotonic_clock_domain_id
            ),
        )

    def _append_transport_actor_event_record_core(
        self,
        event: TransportActorEventV49C,
        *,
        operation_now: datetime,
        allow_raw_event: bool,
    ) -> PhysicalProjectionReceiptV4:
        """Validate and insert one actor event inside the caller's transaction."""

        if type(event) is not TransportActorEventV49C:
            raise CanonicalizationError(
                "event must be an exact TransportActorEventV49C"
            )
        if (
            event.event_kind is TransportActorEventKindV49C.RAW_INGRESS_COMMITTED
        ) != allow_raw_event:
            raise PhysicalProjectionV4ConflictError(
                "RAW actor events are admitted only by the atomic raw append path"
            )
        session, _, _, _, deployment = self._control_authority_context(
            operation_now=operation_now,
            transport_session_id=event.transport_session_id,
            socket_lease_id=event.socket_lease_id,
            connection_generation=event.connection_generation,
            deployment_bundle_id=event.deployment_bundle_id,
            writer_fence_token_sha256=event.writer_fence_token_sha256,
            writer_fence_generation=event.writer_fence_generation,
            monotonic_clock_domain_id=event.monotonic_clock_domain_id,
            transport_subscription_policy_id=(event.transport_subscription_policy_id),
            physical_scope_manifest_id=event.physical_scope_manifest_id,
            adapter_policy_id=event.adapter_policy_id,
            capture_partition_id=event.capture_partition_id,
        )
        self._assert_control_side_effect_open(
            transport_session_id=event.transport_session_id
        )
        if (
            event.recorded_at < session.handshake_completed_at
            or event.recorded_at > operation_now
            or event.recorded_monotonic_ns <= session.handshake_completed_monotonic_ns
        ):
            raise PhysicalProjectionV4ConflictError(
                "transport actor event clocks leave session/receipt chronology"
            )
        if event.driver_policy_id != self._actor_driver_policy_id_v49c(deployment):
            raise PhysicalProjectionV4ConflictError(
                "transport actor event changes the signed driver policy"
            )
        chain = self._load_transport_actor_chain_v49c(event.transport_session_id)
        candidate_chain = (*chain, event)
        try:
            validate_transport_actor_chain_v49c(candidate_chain)
        except CanonicalizationError as exc:
            raise PhysicalProjectionV4ConflictError(
                "transport actor event does not extend the exact durable chain"
            ) from exc
        if (
            self._actor_terminal_state_v49e(candidate_chain).is_terminal
            and not self._v49e_composite_transaction_active
        ):
            raise PhysicalProjectionV4ConflictError(
                "a final actor outcome requires atomic V4.9E legacy convergence"
            )
        self._assert_actor_application_intent_v49c(event)
        self._assert_actor_local_terminal_command_v49e(
            event,
            operation_now=operation_now,
        )
        self._assert_actor_parser_raw_bytes_v49d(event)
        self._assert_actor_application_projection_v49e(event)
        self._assert_actor_ack_projection_v49e(event)
        self._assert_actor_ack_deadline_projection_v49e(event)
        self._assert_actor_tls_driver_projection_v49e(event)
        self._assert_actor_shutdown_evidence_projection_v49e(event)
        if allow_raw_event:
            payload = event.payload
            assert type(payload) is RawIngressCommittedPayloadV49C
            receipt_row = self._connection.execute(
                """
                SELECT c.first_receipt_sequence, r.receipt_hash,
                       r.previous_receipt_hash, r.record_kind, r.identity_id,
                       r.content_hash, r.committed_at
                FROM canonical_records AS c
                JOIN receipts AS r
                  ON r.global_sequence = c.first_receipt_sequence
                WHERE c.identity_id = ?
                """,
                (
                    _blob_hash(
                        payload.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                ),
            ).fetchone()
            if receipt_row is None:
                raise PhysicalProjectionV4ConflictError(
                    "RAW actor event lacks its canonical ingress receipt"
                )
            expected_receipt = CommittedRawIngressV49C.from_projection_receipt(
                ledger_id=self.ledger_id,
                receipt=PhysicalProjectionReceiptV4(
                    global_sequence=int(receipt_row[0]),
                    receipt_hash=bytes(receipt_row[1]).hex(),
                    previous_receipt_hash=bytes(receipt_row[2]).hex(),
                    record_kind=PhysicalRecordKindV4(str(receipt_row[3])),
                    identity_id=bytes(receipt_row[4]).hex(),
                    content_hash=bytes(receipt_row[5]).hex(),
                    committed_at=str(receipt_row[6]),
                ),
            )
            if payload.receipt != expected_receipt:
                raise PhysicalProjectionV4ConflictError(
                    "RAW actor event presents a substituted projection receipt"
                )
        receipt = self._append_record(event, committed_at=operation_now)
        self._connection.execute(
            """
            INSERT INTO transport_actor_events_v49c(
                transport_actor_event_id,
                transport_subscription_policy_id, transport_session_id,
                physical_scope_manifest_id, adapter_policy_id,
                capture_partition_id, socket_lease_id,
                connection_generation, deployment_bundle_id,
                writer_fence_token_sha256, writer_fence_generation,
                monotonic_clock_domain_id, driver_policy_id,
                recorded_at_us, recorded_monotonic_ns,
                actor_sequence, previous_event_id, event_kind, payload_blob,
                source_receipt_sequence, source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                _blob_hash(
                    event.transport_actor_event_id,
                    field="transport_actor_event_id",
                ),
                _blob_hash(
                    event.transport_subscription_policy_id,
                    field="transport_subscription_policy_id",
                ),
                _blob_hash(event.transport_session_id, field="transport_session_id"),
                _blob_hash(
                    event.physical_scope_manifest_id,
                    field="physical_scope_manifest_id",
                ),
                _blob_hash(event.adapter_policy_id, field="adapter_policy_id"),
                _blob_hash(event.capture_partition_id, field="capture_partition_id"),
                _blob_hash(event.socket_lease_id, field="socket_lease_id"),
                event.connection_generation,
                _blob_hash(event.deployment_bundle_id, field="deployment_bundle_id"),
                _blob_hash(
                    event.writer_fence_token_sha256,
                    field="writer_fence_token_sha256",
                ),
                event.writer_fence_generation,
                _blob_hash(
                    event.monotonic_clock_domain_id,
                    field="monotonic_clock_domain_id",
                ),
                _blob_hash(event.driver_policy_id, field="driver_policy_id"),
                _timestamp_us(event.recorded_at, field="recorded_at"),
                event.recorded_monotonic_ns,
                event.actor_sequence,
                None
                if event.previous_event_id is None
                else _blob_hash(event.previous_event_id, field="previous_event_id"),
                event.event_kind.value,
                canonical_json_bytes(event.payload.as_dict()),
                receipt.global_sequence,
                _blob_hash(receipt.content_hash, field="content_hash"),
            ),
        )
        self._fault("after_transport_actor_event_v49c_insert")
        return receipt

    def _append_actor_raw_ingress_event_core_v49c(
        self,
        raw: RawIngressCommitV4,
        *,
        driver_policy_id: str,
        idempotency_key: str,
    ) -> CommittedActorRawIngressV49C:
        """Atomically commit raw bytes and the store-derived actor receipt edge."""

        if type(raw) is not RawIngressCommitV4:
            raise CanonicalizationError("raw must be an exact RawIngressCommitV4")
        driver_id = canonical_hash(driver_policy_id, field="driver_policy_id")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_ACTOR_RAW_INGRESS_V49C"
        request_payload = {
            "driver_policy_id": driver_id,
            "raw": raw.as_dict(),
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded_raw = self._load_record(
                    PhysicalRecordKindV4.RAW_INGRESS_COMMIT,
                    str(replay["raw_ingress_commit_id"]),
                )
                loaded_event = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                    str(replay["transport_actor_event_id"]),
                )
                assert type(loaded_raw) is RawIngressCommitV4
                assert type(loaded_event) is TransportActorEventV49C
                loaded_payload = loaded_event.payload
                assert type(loaded_payload) is RawIngressCommittedPayloadV49C
                return CommittedActorRawIngressV49C(
                    raw=loaded_raw,
                    receipt=loaded_payload.receipt,
                    event=loaded_event,
                )
            operation_now = self._now()
            first_sequence = self._last_receipt()[0] + 1
            raw_receipt = self._append_raw_ingress_record_core(
                raw, operation_now=operation_now
            )
            committed_raw = CommittedRawIngressV49C.from_projection_receipt(
                ledger_id=self.ledger_id,
                receipt=raw_receipt,
            )
            chain = self._load_transport_actor_chain_v49c(raw.transport_session_id)
            previous_event_id = (
                None if not chain else chain[-1].transport_actor_event_id
            )
            prior_raw = next(
                (
                    candidate.payload
                    for candidate in reversed(chain)
                    if candidate.event_kind
                    is TransportActorEventKindV49C.RAW_INGRESS_COMMITTED
                ),
                None,
            )
            if (
                prior_raw is not None
                and type(prior_raw) is not RawIngressCommittedPayloadV49C
            ):
                raise PhysicalProjectionV4VerificationError(
                    "prior RAW actor event has a substituted payload"
                )
            stream_start = 0 if prior_raw is None else prior_raw.stream_end_octet
            chunks = tuple(
                base64.b64decode(value, validate=True)
                for value in raw.raw_ingress_chunks_base64
            )
            payload = RawIngressCommittedPayloadV49C(
                raw_ingress_commit_id=raw.raw_ingress_commit_id,
                receipt=committed_raw,
                ingress_sequence=raw.ingress_sequence,
                previous_raw_ingress_commit_id=(
                    None if prior_raw is None else prior_raw.raw_ingress_commit_id
                ),
                stream_start_octet=stream_start,
                stream_end_octet=stream_start + sum(map(len, chunks)),
                ordered_chunk_octet_lengths=tuple(map(len, chunks)),
                ordered_chunk_sha256=raw.raw_ingress_chunks_sha256,
                raw_ingress_batch_sha256=raw.raw_ingress_batch_sha256,
                received_at=raw.received_at,
                received_monotonic_ns=raw.received_monotonic_ns,
            )
            event = TransportActorEventV49C.create(
                transport_subscription_policy_id=(raw.transport_subscription_policy_id),
                transport_session_id=raw.transport_session_id,
                physical_scope_manifest_id=raw.physical_scope_manifest_id,
                adapter_policy_id=raw.adapter_policy_id,
                capture_partition_id=raw.capture_partition_id,
                socket_lease_id=raw.socket_lease_id,
                connection_generation=raw.connection_generation,
                deployment_bundle_id=raw.deployment_bundle_id,
                writer_fence_token_sha256=raw.writer_fence_token_sha256,
                writer_fence_generation=raw.writer_fence_generation,
                monotonic_clock_domain_id=raw.monotonic_clock_domain_id,
                driver_policy_id=driver_id,
                recorded_at=raw.received_at,
                recorded_monotonic_ns=raw.received_monotonic_ns,
                actor_sequence=len(chain) + 1,
                previous_event_id=previous_event_id,
                event_kind=(TransportActorEventKindV49C.RAW_INGRESS_COMMITTED),
                payload=payload,
            )
            self._append_transport_actor_event_record_core(
                event,
                operation_now=operation_now,
                allow_raw_event=True,
            )
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "raw_ingress_commit_id": raw.raw_ingress_commit_id,
                    "transport_actor_event_id": event.transport_actor_event_id,
                },
            )
            return CommittedActorRawIngressV49C(
                raw=raw,
                receipt=committed_raw,
                event=event,
            )

    def append_actor_raw_ingress_v49c_for_test(
        self,
        raw: RawIngressCommitV4,
        *,
        driver_policy_id: str,
        idempotency_key: str,
    ) -> CommittedActorRawIngressV49C:
        """Explicit non-live harness for the atomic V4.9C raw actor edge."""

        if self.is_live_clock_profile:
            raise PhysicalProjectionV4ClockError(
                "live V4.9C raw ingress requires the retained driver authority"
            )
        return self._append_actor_raw_ingress_event_core_v49c(
            raw,
            driver_policy_id=driver_policy_id,
            idempotency_key=idempotency_key,
        )

    def _append_driver_actor_raw_ingress_v49c(
        self,
        raw: RawIngressCommitV4,
        *,
        authority: Any,
        idempotency_key: str,
    ) -> CommittedActorRawIngressV49C:
        """Live-only raw append derived from this projection's exact owner."""

        from .physical_transport_linux_v4 import LinuxSocketOwnerV4

        if (
            type(authority) is not LinuxSocketOwnerV4
            or not authority.is_live_profile
            or not self._is_bound_to_live_linux_authority(authority)
        ):
            raise PhysicalProjectionV4ClockError(
                "V4.9C raw ingress is not owned by the retained live authority"
            )
        return self._append_actor_raw_ingress_event_core_v49c(
            raw,
            driver_policy_id=authority.driver_policy_id,
            idempotency_key=idempotency_key,
        )

    def _append_transport_actor_event_core_v49c(
        self,
        event: TransportActorEventV49C,
        *,
        idempotency_key: str,
    ) -> TransportActorEventV49C:
        if type(event) is not TransportActorEventV49C:
            raise CanonicalizationError(
                "event must be an exact TransportActorEventV49C"
            )
        if event.event_kind is TransportActorEventKindV49C.RAW_INGRESS_COMMITTED:
            raise PhysicalProjectionV4ConflictError(
                "RAW actor events require the atomic projection append"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_TRANSPORT_ACTOR_EVENT_V49C"
        request = _request_hash(operation, event.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                    str(replay["transport_actor_event_id"]),
                )
                assert type(loaded) is TransportActorEventV49C
                return loaded
            first_sequence = self._last_receipt()[0] + 1
            self._append_transport_actor_event_record_core(
                event,
                operation_now=self._now(),
                allow_raw_event=False,
            )
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={"transport_actor_event_id": event.transport_actor_event_id},
            )
            return event

    def append_transport_actor_event_v49c_for_test(
        self,
        event: TransportActorEventV49C,
        *,
        idempotency_key: str,
    ) -> TransportActorEventV49C:
        """Explicit non-live append for deterministic actor/projection tests."""

        if self.is_live_clock_profile:
            raise PhysicalProjectionV4ClockError(
                "live V4.9C actor events require retained owner authority"
            )
        return self._append_transport_actor_event_core_v49c(
            event, idempotency_key=idempotency_key
        )

    def _append_driver_transport_actor_event_v49c(
        self,
        event: TransportActorEventV49C,
        *,
        authority: Any,
        idempotency_key: str,
    ) -> TransportActorEventV49C:
        """Append a later actor event only for the exact retained live owner."""

        from .physical_transport_linux_v4 import LinuxSocketOwnerV4

        if (
            type(authority) is not LinuxSocketOwnerV4
            or not authority.is_live_profile
            or not self._is_bound_to_live_linux_authority(authority)
            or event.driver_policy_id != authority.driver_policy_id
        ):
            raise PhysicalProjectionV4ClockError(
                "V4.9C event is not owned by the retained live authority"
            )
        return self._append_transport_actor_event_core_v49c(
            event, idempotency_key=idempotency_key
        )

    def _append_transport_actor_event_batch_core_v49c(
        self,
        events: tuple[TransportActorEventV49C, ...],
        *,
        idempotency_key: str,
    ) -> tuple[TransportActorEventV49C, ...]:
        """Atomically append one bounded consecutive non-RAW actor batch."""

        if (
            type(events) is not tuple
            or not 2 <= len(events) <= 8
            or any(
                type(event) is not TransportActorEventV49C
                or event.event_kind is TransportActorEventKindV49C.RAW_INGRESS_COMMITTED
                for event in events
            )
        ):
            raise CanonicalizationError(
                "actor batch requires two through eight exact non-RAW events"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_TRANSPORT_ACTOR_EVENT_BATCH_V49C"
        request = _request_hash(
            operation, {"events": [event.as_dict() for event in events]}
        )
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                raw_ids = replay["transport_actor_event_ids"]
                if not isinstance(raw_ids, list) or len(raw_ids) != len(events):
                    raise PhysicalProjectionV4ConflictError(
                        "actor batch replay has an invalid result shape"
                    )
                loaded = tuple(
                    self._load_record(
                        PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                        str(event_id),
                    )
                    for event_id in raw_ids
                )
                if any(type(event) is not TransportActorEventV49C for event in loaded):
                    raise PhysicalProjectionV4ConflictError(
                        "actor batch replay resolved an unsupported record"
                    )
                return loaded  # type: ignore[return-value]
            first_sequence = self._last_receipt()[0] + 1
            operation_now = self._now()
            for event in events:
                self._append_transport_actor_event_record_core(
                    event,
                    operation_now=operation_now,
                    allow_raw_event=False,
                )
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "transport_actor_event_ids": [
                        event.transport_actor_event_id for event in events
                    ]
                },
            )
            return events

    def append_transport_actor_event_batch_v49c_for_test(
        self,
        events: tuple[TransportActorEventV49C, ...],
        *,
        idempotency_key: str,
    ) -> tuple[TransportActorEventV49C, ...]:
        """Explicit non-live atomic actor-batch append."""

        if self.is_live_clock_profile:
            raise PhysicalProjectionV4ClockError(
                "live V4.9C actor batches require retained owner authority"
            )
        return self._append_transport_actor_event_batch_core_v49c(
            events, idempotency_key=idempotency_key
        )

    def _append_driver_transport_actor_event_batch_v49c(
        self,
        events: tuple[TransportActorEventV49C, ...],
        *,
        authority: Any,
        idempotency_key: str,
    ) -> tuple[TransportActorEventV49C, ...]:
        """Append an atomic actor batch for the exact retained live owner."""

        from .physical_transport_linux_v4 import LinuxSocketOwnerV4

        if (
            type(authority) is not LinuxSocketOwnerV4
            or not authority.is_live_profile
            or not self._is_bound_to_live_linux_authority(authority)
            or any(
                event.driver_policy_id != authority.driver_policy_id for event in events
            )
        ):
            raise PhysicalProjectionV4ClockError(
                "V4.9C actor batch is not owned by retained live authority"
            )
        return self._append_transport_actor_event_batch_core_v49c(
            events, idempotency_key=idempotency_key
        )

    def _assert_actor_provider_message_commit_result_v49e(
        self, result: ActorProviderMessageCommitResultV49E
    ) -> None:
        """Replay the state-dependent ACK decision for a loaded result."""

        application_event = result.application_event
        app = application_event.payload
        if (
            type(app) is not ApplicationMessageCommittedPayloadV49E
            or len(result.segment.envelopes) != 1
        ):
            raise PhysicalProjectionV4VerificationError(
                "actor provider result lacks one exact application message"
            )
        try:
            self._assert_actor_application_projection_v49e(application_event)
        except PhysicalProjectionV4ConflictError as exc:
            raise PhysicalProjectionV4VerificationError(
                "actor provider result changes its application evidence"
            ) from exc
        chain = self._load_transport_actor_chain_v49c(
            application_event.transport_session_id
        )
        positions = tuple(
            index
            for index, event in enumerate(chain)
            if event.transport_actor_event_id
            == application_event.transport_actor_event_id
        )
        if len(positions) != 1:
            raise PhysicalProjectionV4VerificationError(
                "actor provider application event does not occur exactly once"
            )
        position = positions[0]
        prefix = chain[:position]
        application_receipt = self._source_metadata(
            application_event.transport_actor_event_id
        )[0]
        pending = self._pending_actor_subscription_ack_v49e(
            transport_session_id=application_event.transport_session_id,
            chain=prefix,
            received_at=app.received_at,
            received_monotonic_ns=app.received_monotonic_ns,
            before_receipt_sequence=application_receipt,
        )
        subscribe_shaped, raw_object = self._provider_subscribe_shape_v49e(
            result.segment.envelopes[0].raw_payload
        )
        exact_ack = (
            pending is not None
            and subscribe_shaped
            and self._exact_actor_subscription_ack_v49e(
                pending=pending,
                opcode=app.message_opcode,
                payload=raw_object,
                classification=result.classification,
            )
        )
        expected_failure = pending is not None and subscribe_shaped and not exact_ack
        has_ack = result.ack_binding is not None
        has_failure = result.provider_failure_event is not None
        if has_ack != exact_ack or has_failure != expected_failure:
            raise PhysicalProjectionV4VerificationError(
                "actor provider result differs from its causal ACK decision"
            )

        if has_ack:
            assert pending is not None
            assert result.ack_binding is not None and result.ack_event is not None
            if (
                position + 1 >= len(chain)
                or chain[position + 1] != result.ack_event
                or result.ack_event.previous_event_id
                != application_event.transport_actor_event_id
                or result.ack_binding.outbound_subscription_intent_id
                != pending.intent.outbound_subscription_intent_id
            ):
                raise PhysicalProjectionV4VerificationError(
                    "actor provider ACK is not the exact next bound outcome"
                )
            try:
                self._assert_actor_ack_projection_v49e(result.ack_event)
            except PhysicalProjectionV4ConflictError as exc:
                raise PhysicalProjectionV4VerificationError(
                    "actor provider ACK changes its canonical binding"
                ) from exc

        if has_failure:
            failure_event = result.provider_failure_event
            termination = result.termination
            assert failure_event is not None and termination is not None
            failure_payload = failure_event.payload
            if (
                type(failure_payload) is not TerminalTransitionPayloadV49C
                or failure_payload.kind is not TerminalTransitionKindV49C.FATAL
                or failure_payload.cause_code
                != _V49E_SUBSCRIPTION_ACK_INTEGRITY_FAILURE_CAUSE
                or position + 1 >= len(chain)
                or chain[position + 1] != failure_event
                or failure_event.previous_event_id
                != application_event.transport_actor_event_id
                or termination.reason
                is not TransportSessionTerminationReasonV4.TRANSPORT_ERROR
            ):
                raise PhysicalProjectionV4VerificationError(
                    "actor provider integrity failure changes its fixed outcome"
                )
            failure_prefix = chain[: position + 2]
            try:
                bridge = self._derive_actor_terminal_bridge_v49e(failure_prefix)
            except PhysicalProjectionV4ConflictError as exc:
                raise PhysicalProjectionV4VerificationError(
                    "actor provider integrity failure cannot replay terminal authority"
                ) from exc
            expected_termination = (
                application_event.transport_session_id,
                bridge.reason,
                bridge.close_code,
                bridge.close_reason_digest,
                bridge.detected_at,
                bridge.detected_monotonic_ns,
                bridge.detected_monotonic_clock_domain_id,
            )
            actual_termination = (
                termination.transport_session_id,
                termination.reason,
                termination.close_code,
                termination.close_reason_digest,
                termination.detected_at,
                termination.detected_monotonic_ns,
                termination.detected_monotonic_clock_domain_id,
            )
            failure_receipt = self._source_metadata(
                failure_event.transport_actor_event_id
            )[0]
            termination_receipt = self._source_metadata(
                termination.transport_session_termination_id
            )[0]
            if (
                bridge.reason is not TransportSessionTerminationReasonV4.TRANSPORT_ERROR
                or actual_termination != expected_termination
                or termination_receipt != failure_receipt + 1
            ):
                raise PhysicalProjectionV4VerificationError(
                    "actor provider integrity failure changes its signed bridge"
                )

    def _load_actor_provider_message_commit_result_v49e(
        self, result: Mapping[str, Any]
    ) -> ActorProviderMessageCommitResultV49E:
        """Resolve the exact canonical result of one replayed V4.9E command."""

        required = {
            "ack_event_id",
            "application_event_id",
            "capture_segment_id",
            "message_disposition_id",
            "physical_message_id",
            "provider_failure_event_id",
            "provider_message_disposition_id",
            "subscription_ack_binding_id",
            "transport_session_termination_id",
        }
        if set(result) != required:
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message batch result is malformed"
            )
        segment = self._load_record(
            PhysicalRecordKindV4.CAPTURE_SEGMENT,
            str(result["capture_segment_id"]),
        )
        message = self._load_record(
            PhysicalRecordKindV4.PHYSICAL_MESSAGE,
            str(result["physical_message_id"]),
        )
        provider = self._load_record(
            PhysicalRecordKindV4.PROVIDER_MESSAGE_DISPOSITION,
            str(result["provider_message_disposition_id"]),
        )
        disposition = self._load_record(
            PhysicalRecordKindV4.MESSAGE_DISPOSITION,
            str(result["message_disposition_id"]),
        )
        application_event = self._load_record(
            PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
            str(result["application_event_id"]),
        )
        if (
            type(segment) is not CaptureSegmentV3
            or type(message) is not PhysicalMessageV4
            or type(provider) is not ProviderMessageDispositionV3
            or type(disposition) is not MessageDispositionV4
            or type(application_event) is not TransportActorEventV49C
        ):
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message result resolves unsupported records"
            )
        derivation = (
            None
            if not disposition.observation_derivation_ids
            else self._load_record(
                PhysicalRecordKindV4.OBSERVATION_DERIVATION,
                disposition.observation_derivation_ids[0],
            )
        )
        revision = (
            None
            if not disposition.observation_revision_ids
            else self._load_record(
                PhysicalRecordKindV4.OBSERVATION_REVISION,
                disposition.observation_revision_ids[0],
            )
        )
        classification = ClassificationAppendV4(
            disposition=disposition,
            provider_disposition=provider,
            derivation=derivation,
            revision=revision,
        )
        raw_binding_id = result.get("subscription_ack_binding_id")
        raw_ack_event_id = result.get("ack_event_id")
        if (raw_binding_id is None) != (raw_ack_event_id is None):
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message replay has a partial ACK result"
            )
        binding = (
            None
            if raw_binding_id is None
            else self._load_record(
                PhysicalRecordKindV4.SUBSCRIPTION_ACK_BINDING,
                str(raw_binding_id),
            )
        )
        ack_event = (
            None
            if raw_ack_event_id is None
            else self._load_record(
                PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                str(raw_ack_event_id),
            )
        )
        if binding is not None and type(binding) is not SubscriptionAckBindingV4:
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message ACK result resolves the wrong binding type"
            )
        if ack_event is not None and type(ack_event) is not TransportActorEventV49C:
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message ACK result resolves the wrong event type"
            )
        raw_failure_event_id = result.get("provider_failure_event_id")
        raw_termination_id = result.get("transport_session_termination_id")
        if (raw_failure_event_id is None) != (raw_termination_id is None):
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message replay has a partial failure result"
            )
        provider_failure_event = (
            None
            if raw_failure_event_id is None
            else self._load_record(
                PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                str(raw_failure_event_id),
            )
        )
        termination = (
            None
            if raw_termination_id is None
            else self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_TERMINATION,
                str(raw_termination_id),
            )
        )
        if (
            provider_failure_event is not None
            and type(provider_failure_event) is not TransportActorEventV49C
        ):
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message failure resolves the wrong event type"
            )
        if termination is not None and not isinstance(
            termination, TransportSessionTerminationV4
        ):
            raise PhysicalProjectionV4VerificationError(
                "actor provider-message failure resolves the wrong termination type"
            )
        loaded = ActorProviderMessageCommitResultV49E(
            segment=segment,
            physical_message=message,
            classification=classification,
            application_event=application_event,
            ack_binding=binding,
            ack_event=ack_event,
            provider_failure_event=provider_failure_event,
            termination=termination,
        )
        self._assert_actor_provider_message_commit_result_v49e(loaded)
        return loaded

    def _commit_actor_provider_message_core_v49e(
        self,
        *,
        transport_session_id: str,
        source_parser_event_ids: Sequence[str],
        websocket_opcode: WebSocketOpcodeV49C | str,
        raw_payload: bytes,
        collector_received_at: datetime | str,
        collector_received_monotonic_ns: int,
        classified_monotonic_ns: int,
        driver_policy_id: str,
        signer: Any,
        idempotency_key: str,
    ) -> ActorProviderMessageCommitResultV49E:
        """Atomically capture, classify and, when exact, bind one actor ACK.

        The caller supplies parser-derived bytes and clocks only as claims.  The
        projection independently reconstructs the message from canonical parser
        events and derives receipt time from the final contributing RAW slice.
        """

        session_id = canonical_hash(transport_session_id, field="transport_session_id")
        if isinstance(source_parser_event_ids, (str, bytes, bytearray)):
            raise CanonicalizationError(
                "source_parser_event_ids must be a bounded sequence"
            )
        source_ids = tuple(
            canonical_hash(value, field="source_parser_event_ids")
            for value in source_parser_event_ids
        )
        if (
            not source_ids
            or len(source_ids) > 4_096
            or len(set(source_ids)) != len(source_ids)
        ):
            raise CanonicalizationError(
                "source parser event IDs must contain one bounded unique lineage"
            )
        try:
            opcode = (
                websocket_opcode
                if isinstance(websocket_opcode, WebSocketOpcodeV49C)
                else WebSocketOpcodeV49C(websocket_opcode)
            )
        except (TypeError, ValueError) as exc:
            raise CanonicalizationError("unsupported application opcode") from exc
        if opcode not in {WebSocketOpcodeV49C.TEXT, WebSocketOpcodeV49C.BINARY}:
            raise CanonicalizationError("actor provider message must be TEXT or BINARY")
        if type(raw_payload) is not bytes or len(raw_payload) > 1_048_576:
            raise CanonicalizationError(
                "raw_payload must be exact bytes within the V4.9E message bound"
            )
        received_at = utc_datetime(collector_received_at, field="collector_received_at")
        received_ns = canonical_safe_int(
            collector_received_monotonic_ns,
            field="collector_received_monotonic_ns",
            minimum=0,
        )
        classified_ns = canonical_safe_int(
            classified_monotonic_ns,
            field="classified_monotonic_ns",
            minimum=0,
        )
        driver_id = canonical_hash(driver_policy_id, field="driver_policy_id")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "COMMIT_ACTOR_PROVIDER_MESSAGE_V49E"
        request = _request_hash(
            operation,
            {
                "classified_monotonic_ns": classified_ns,
                "collector_received_at": utc_iso(received_at),
                "collector_received_monotonic_ns": received_ns,
                "driver_policy_id": driver_id,
                "raw_payload_base64": base64.b64encode(raw_payload).decode("ascii"),
                "source_parser_event_ids": list(source_ids),
                "transport_session_id": session_id,
                "websocket_opcode": opcode.value,
            },
        )
        component_key = request.hex()
        with self._v49e_composite_transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                return self._load_actor_provider_message_commit_result_v49e(replay)

            operation_now = self._now()
            first_sequence = self._last_receipt()[0] + 1
            chain = self._load_transport_actor_chain_v49c(session_id)
            if not chain:
                raise PhysicalProjectionV4ConflictError(
                    "actor provider message has no durable parser prefix"
                )
            tail = chain[-1]
            if tail.driver_policy_id != driver_id:
                raise PhysicalProjectionV4ConflictError(
                    "actor provider message changes the signed driver policy"
                )
            reconstructed = self._actor_application_message_bytes_v49e(source_ids)
            exact_received_at, exact_received_ns = self._actor_application_receipt_v49e(
                source_ids
            )
            if (
                reconstructed != raw_payload
                or exact_received_at != received_at
                or exact_received_ns != received_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "actor provider message differs from canonical parser/RAW evidence"
                )
            if (
                operation_now < received_at
                or operation_now < tail.recorded_at
                or classified_ns <= tail.recorded_monotonic_ns
                or classified_ns < received_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "actor provider classification clock is not causally ordered"
                )

            session = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION, session_id
            )
            if type(session) is not TransportSessionAttestationV4:
                raise PhysicalProjectionV4VerificationError(
                    "actor provider message session has the wrong record type"
                )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                session.physical_scope_manifest_id,
            )
            adapter = self._load_record(
                PhysicalRecordKindV4.PROVIDER_ADAPTER_POLICY,
                session.adapter_policy_id,
            )
            if (
                type(scope) is not PhysicalScopeManifestV4
                or type(adapter) is not ProviderAdapterPolicyV3
            ):
                raise PhysicalProjectionV4VerificationError(
                    "actor provider message authority records have wrong types"
                )
            pending_ack = self._pending_actor_subscription_ack_v49e(
                transport_session_id=session_id,
                chain=chain,
                received_at=received_at,
                received_monotonic_ns=received_ns,
                before_receipt_sequence=first_sequence,
            )
            subscribe_shaped, raw_provider_object = self._provider_subscribe_shape_v49e(
                raw_payload
            )
            parent_row = self._connection.execute(
                """
                SELECT capture_segment_id, last_collector_sequence
                FROM capture_segments
                WHERE capture_partition_id = ?
                ORDER BY last_collector_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(
                        session.capture_partition_id,
                        field="capture_partition_id",
                    ),
                ),
            ).fetchone()
            parent_id = None if parent_row is None else bytes(parent_row[0]).hex()
            collector_sequence = 1 if parent_row is None else int(parent_row[1]) + 1
            envelope = ProviderMessageEnvelopeV3.from_raw(
                collector_sequence=collector_sequence,
                collector_received_wall_ts=received_at,
                collector_received_monotonic_ns=received_ns,
                message_type=(
                    ProviderMessageTypeV3.TEXT
                    if opcode is WebSocketOpcodeV49C.TEXT
                    else ProviderMessageTypeV3.BINARY
                ),
                raw_payload=raw_payload,
            )
            segment = CaptureSegmentV3(
                adapter_policy_id=session.adapter_policy_id,
                provider_native_key=adapter.provider_native_key,
                collector_instance_id=session.collector_instance_id,
                collector_boot_id=session.collector_boot_id,
                connection_id=session.transport_session_id,
                connection_generation=session.connection_generation,
                subscription_manifest_hash=subscription_manifest_hash_v4(
                    (adapter.channel_or_schema,)
                ),
                vintage=PhysicalVintage.PROSPECTIVE_LIVE,
                envelopes=(envelope,),
                closed_at=operation_now,
                clock_uncertainty_milliseconds=(session.clock_uncertainty_milliseconds),
                parent_capture_segment_id=parent_id,
            )
            if segment.capture_partition_id != session.capture_partition_id:
                raise PhysicalProjectionV4ConflictError(
                    "actor-derived capture partition differs from its session"
                )
            messages = self.append_messages(
                physical_scope_manifest_id=scope.physical_scope_manifest_id,
                segment=segment,
                idempotency_key=f"v49e-{component_key}-message",
            )
            if len(messages) != 1:
                raise PhysicalProjectionV4VerificationError(
                    "actor provider capture did not produce exactly one message"
                )
            message = messages[0]
            classification = self._build_actor_provider_classification_v49e(
                scope=scope,
                segment=segment,
                message=message,
                classified_at=operation_now,
            )
            classified = self.append_classification_batch(
                (classification,),
                idempotency_key=f"v49e-{component_key}-classification",
            )
            if len(classified) != 1 or classified[0][0] != classification.disposition:
                raise PhysicalProjectionV4VerificationError(
                    "actor provider classifier append changed its exact result"
                )

            app_payload = ApplicationMessageCommittedPayloadV49E(
                source_parser_event_ids=source_ids,
                message_opcode=opcode,
                message_payload_octets=len(raw_payload),
                message_payload_sha256=hashlib.sha256(raw_payload).hexdigest(),
                capture_segment_id=segment.capture_segment_id,
                message_receipt_id=envelope.message_receipt_id,
                physical_message_id=message.physical_message_id,
                provider_message_disposition_id=(
                    classification.provider_disposition.provider_message_disposition_id
                ),
                message_disposition_id=(
                    classification.disposition.message_disposition_id
                ),
                disposition_kind=(classification.provider_disposition.disposition_kind),
                received_at=received_at,
                received_monotonic_ns=received_ns,
                classified_at=operation_now,
                classified_monotonic_ns=classified_ns,
            )
            authority_fields = {
                name: getattr(tail, name)
                for name in (
                    "transport_subscription_policy_id",
                    "transport_session_id",
                    "physical_scope_manifest_id",
                    "adapter_policy_id",
                    "capture_partition_id",
                    "socket_lease_id",
                    "connection_generation",
                    "deployment_bundle_id",
                    "writer_fence_token_sha256",
                    "writer_fence_generation",
                    "monotonic_clock_domain_id",
                    "driver_policy_id",
                )
            }
            application_event = TransportActorEventV49C.create(
                **authority_fields,
                recorded_at=operation_now,
                recorded_monotonic_ns=classified_ns,
                actor_sequence=len(chain) + 1,
                previous_event_id=tail.transport_actor_event_id,
                event_kind=(TransportActorEventKindV49C.APPLICATION_MESSAGE_COMMITTED),
                payload=app_payload,
            )
            self._append_transport_actor_event_record_core(
                application_event,
                operation_now=operation_now,
                allow_raw_event=False,
            )

            binding: SubscriptionAckBindingV4 | None = None
            ack_event: TransportActorEventV49C | None = None
            provider_failure_event: TransportActorEventV49C | None = None
            termination: TransportSessionTerminationV4 | None = None
            exact_ack = (
                pending_ack is not None
                and subscribe_shaped
                and self._exact_actor_subscription_ack_v49e(
                    pending=pending_ack,
                    opcode=opcode,
                    payload=raw_provider_object,
                    classification=classification,
                )
            )
            if exact_ack:
                assert pending_ack is not None
                intent = pending_ack.intent
                wire_event = pending_ack.wire_event
                first_attempt = pending_ack.first_attempt
                completion_event = pending_ack.completion_event
                completion = completion_event.payload
                wire = wire_event.payload
                if (
                    type(completion) is not OutboundDispatchCompletedPayloadV49C
                    or type(wire) is not OutboundWirePreparedPayloadV49C
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "actor subscription dispatch has substituted payloads"
                    )
                binding = self.bind_subscription_ack(
                    outbound_subscription_intent_id=(
                        intent.outbound_subscription_intent_id
                    ),
                    message_disposition_id=(
                        classification.disposition.message_disposition_id
                    ),
                    dispatch_started_at=first_attempt.attempted_at,
                    dispatch_completed_at=completion.completed_at,
                    dispatch_started_monotonic_ns=(
                        first_attempt.attempted_monotonic_ns
                    ),
                    dispatch_completed_monotonic_ns=(completion.completed_monotonic_ns),
                    signer=signer,
                    idempotency_key=f"v49e-{component_key}-ack-binding",
                )
                ack_payload = SubscriptionAckBoundPayloadV49E(
                    source_application_message_event_id=(
                        application_event.transport_actor_event_id
                    ),
                    outbound_subscription_intent_id=(
                        intent.outbound_subscription_intent_id
                    ),
                    subscription_dispatch_completed_event_id=(
                        completion_event.transport_actor_event_id
                    ),
                    subscription_ack_binding_id=(binding.subscription_ack_binding_id),
                    provider_message_disposition_id=(
                        binding.provider_message_disposition_id
                    ),
                    message_disposition_id=binding.message_disposition_id,
                    echoed_request_id=binding.echoed_request_id,
                    provider_connection_id=binding.provider_connection_id,
                    request_command_sha256=binding.request_command_sha256,
                    raw_ack_sha256=binding.raw_ack_sha256,
                    dispatch_started_at=binding.dispatch_started_at,
                    dispatch_completed_at=binding.dispatch_completed_at,
                    dispatch_started_monotonic_ns=(
                        binding.dispatch_started_monotonic_ns
                    ),
                    dispatch_completed_monotonic_ns=(
                        binding.dispatch_completed_monotonic_ns
                    ),
                    ack_received_at=binding.ack_received_at,
                    ack_received_monotonic_ns=binding.ack_received_monotonic_ns,
                    ack_not_after=intent.ack_not_after,
                    ack_not_after_monotonic_ns=(pending_ack.ack_not_after_monotonic_ns),
                    bound_at=binding.bound_at,
                    bound_monotonic_ns=classified_ns + 1,
                )
                ack_event = TransportActorEventV49C.create(
                    **authority_fields,
                    recorded_at=operation_now,
                    recorded_monotonic_ns=classified_ns + 1,
                    actor_sequence=len(chain) + 2,
                    previous_event_id=application_event.transport_actor_event_id,
                    event_kind=TransportActorEventKindV49C.SUBSCRIPTION_ACK_BOUND,
                    payload=ack_payload,
                )
                self._append_transport_actor_event_record_core(
                    ack_event,
                    operation_now=operation_now,
                    allow_raw_event=False,
                )
            elif pending_ack is not None and subscribe_shaped:
                terminal_state = self._actor_terminal_state_v49e(
                    (*chain, application_event)
                )
                failure_payload = TerminalTransitionPayloadV49C(
                    transport_session_id=session_id,
                    transition_sequence=terminal_state.transition_sequence + 1,
                    parent_terminal_state_id=terminal_state.terminal_state_id,
                    kind=TerminalTransitionKindV49C.FATAL,
                    cause_code=(_V49E_SUBSCRIPTION_ACK_INTEGRITY_FAILURE_CAUSE),
                )
                provider_failure_event = TransportActorEventV49C.create(
                    **authority_fields,
                    recorded_at=operation_now,
                    recorded_monotonic_ns=classified_ns + 1,
                    actor_sequence=len(chain) + 2,
                    previous_event_id=(application_event.transport_actor_event_id),
                    event_kind=TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    payload=failure_payload,
                )
                self._append_transport_actor_event_record_core(
                    provider_failure_event,
                    operation_now=operation_now,
                    allow_raw_event=False,
                )
                bridge = self._derive_actor_terminal_bridge_v49e(
                    (*chain, application_event, provider_failure_event)
                )
                if (
                    bridge.reason
                    is not TransportSessionTerminationReasonV4.TRANSPORT_ERROR
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "provider ACK integrity failure derived the wrong termination"
                    )
                termination = self.append_transport_session_termination(
                    transport_session_id=session_id,
                    reason=bridge.reason,
                    close_code=bridge.close_code,
                    close_reason_digest=bridge.close_reason_digest,
                    detected_at=bridge.detected_at,
                    detected_monotonic_ns=bridge.detected_monotonic_ns,
                    detected_monotonic_clock_domain_id=(
                        bridge.detected_monotonic_clock_domain_id
                    ),
                    signer=signer,
                    idempotency_key=f"v49e-{component_key}-provider-failure",
                )

            result = {
                "ack_event_id": (
                    None if ack_event is None else ack_event.transport_actor_event_id
                ),
                "application_event_id": (application_event.transport_actor_event_id),
                "capture_segment_id": segment.capture_segment_id,
                "message_disposition_id": (
                    classification.disposition.message_disposition_id
                ),
                "physical_message_id": message.physical_message_id,
                "provider_message_disposition_id": (
                    classification.provider_disposition.provider_message_disposition_id
                ),
                "provider_failure_event_id": (
                    None
                    if provider_failure_event is None
                    else provider_failure_event.transport_actor_event_id
                ),
                "subscription_ack_binding_id": (
                    None if binding is None else binding.subscription_ack_binding_id
                ),
                "transport_session_termination_id": (
                    None
                    if termination is None
                    else termination.transport_session_termination_id
                ),
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return ActorProviderMessageCommitResultV49E(
                segment=segment,
                physical_message=message,
                classification=classification,
                application_event=application_event,
                ack_binding=binding,
                ack_event=ack_event,
                provider_failure_event=provider_failure_event,
                termination=termination,
            )

