    def _converge_actor_terminal_core_v49e(
        self,
        terminal_event: TransportActorEventV49C,
        *,
        signer: Any,
        idempotency_key: str,
    ) -> ActorTerminalConvergenceResultV49E:
        """Atomically append one decisive actor outcome and its legacy bridge."""

        if (
            type(terminal_event) is not TransportActorEventV49C
            or terminal_event.event_kind
            is not TransportActorEventKindV49C.TERMINAL_TRANSITION
            or type(terminal_event.payload) is not TerminalTransitionPayloadV49C
        ):
            raise CanonicalizationError(
                "terminal_event must be one exact actor terminal transition"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "CONVERGE_ACTOR_TERMINAL_V49E"
        request_payload = {"terminal_event": terminal_event.as_dict()}
        request = _request_hash(operation, request_payload)
        with self._v49e_composite_transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                required = {
                    "terminal_event_id",
                    "transport_session_termination_id",
                }
                if set(replay) != required:
                    raise PhysicalProjectionV4VerificationError(
                        "actor terminal replay result is malformed"
                    )
                loaded_event = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_ACTOR_EVENT_V49C,
                    str(replay["terminal_event_id"]),
                )
                loaded_termination = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_SESSION_TERMINATION,
                    str(replay["transport_session_termination_id"]),
                )
                if (
                    type(loaded_event) is not TransportActorEventV49C
                    or loaded_event != terminal_event
                    or not isinstance(loaded_termination, TransportSessionTerminationV4)
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "actor terminal replay does not resolve its exact result pair"
                    )
                chain = self._load_transport_actor_chain_v49c(
                    loaded_event.transport_session_id
                )
                if (
                    not chain
                    or chain[-1].transport_actor_event_id
                    != loaded_event.transport_actor_event_id
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "actor terminal replay no longer owns the actor chain tail"
                    )
                try:
                    bridge = self._derive_actor_terminal_bridge_v49e(chain)
                except PhysicalProjectionV4ConflictError as exc:
                    raise PhysicalProjectionV4VerificationError(
                        "actor terminal replay cannot reconstruct its legacy bridge"
                    ) from exc
                expected_termination = (
                    loaded_event.transport_session_id,
                    bridge.reason,
                    bridge.close_code,
                    bridge.close_reason_digest,
                    bridge.detected_at,
                    bridge.detected_monotonic_ns,
                    bridge.detected_monotonic_clock_domain_id,
                )
                actual_termination = (
                    loaded_termination.transport_session_id,
                    loaded_termination.reason,
                    loaded_termination.close_code,
                    loaded_termination.close_reason_digest,
                    loaded_termination.detected_at,
                    loaded_termination.detected_monotonic_ns,
                    loaded_termination.detected_monotonic_clock_domain_id,
                )
                event_receipt = self._source_metadata(
                    loaded_event.transport_actor_event_id
                )[0]
                termination_receipt = self._source_metadata(
                    loaded_termination.transport_session_termination_id
                )[0]
                if (
                    bridge.reason is TransportSessionTerminationReasonV4.ACK_TIMEOUT
                    or actual_termination != expected_termination
                    or termination_receipt != event_receipt + 1
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "actor terminal replay changes the exact derived convergence"
                    )
                return ActorTerminalConvergenceResultV49E(
                    terminal_event=loaded_event,
                    termination=loaded_termination,
                )

            operation_now = self._now()
            chain = self._load_transport_actor_chain_v49c(
                terminal_event.transport_session_id
            )
            bridge = self._derive_actor_terminal_bridge_v49e((*chain, terminal_event))
            if bridge.reason is TransportSessionTerminationReasonV4.ACK_TIMEOUT:
                raise PhysicalProjectionV4ConflictError(
                    "ACK deadline requires the indivisible deadline convergence path"
                )
            first_sequence = self._last_receipt()[0] + 1
            self._append_transport_actor_event_record_core(
                terminal_event,
                operation_now=operation_now,
                allow_raw_event=False,
            )
            termination = self.append_transport_session_termination(
                transport_session_id=terminal_event.transport_session_id,
                reason=bridge.reason,
                close_code=bridge.close_code,
                close_reason_digest=bridge.close_reason_digest,
                detected_at=bridge.detected_at,
                detected_monotonic_ns=bridge.detected_monotonic_ns,
                detected_monotonic_clock_domain_id=(
                    bridge.detected_monotonic_clock_domain_id
                ),
                signer=signer,
                idempotency_key=f"v49e-{request.hex()}-termination",
            )
            result = {
                "terminal_event_id": terminal_event.transport_actor_event_id,
                "transport_session_termination_id": (
                    termination.transport_session_termination_id
                ),
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return ActorTerminalConvergenceResultV49E(
                terminal_event=terminal_event,
                termination=termination,
            )

    def converge_actor_terminal_v49e_for_test(
        self,
        terminal_event: TransportActorEventV49C,
        *,
        signer: Any,
        idempotency_key: str,
    ) -> ActorTerminalConvergenceResultV49E:
        """Explicit reference-harness entrypoint; never a live authority seam."""

        if self.is_live_clock_profile:
            raise PhysicalProjectionV4ClockError(
                "live V4.9E terminal convergence requires retained owner authority"
            )
        return self._converge_actor_terminal_core_v49e(
            terminal_event,
            signer=signer,
            idempotency_key=idempotency_key,
        )

    def _converge_driver_actor_terminal_v49e(
        self,
        terminal_event: TransportActorEventV49C,
        *,
        authority: Any,
        signer: Any,
        idempotency_key: str,
    ) -> ActorTerminalConvergenceResultV49E:
        from .physical_transport_linux_v4 import LinuxSocketOwnerV4

        if (
            type(authority) is not LinuxSocketOwnerV4
            or not authority.is_live_profile
            or not self._is_bound_to_live_linux_authority(authority)
            or terminal_event.driver_policy_id != authority.driver_policy_id
        ):
            raise PhysicalProjectionV4ClockError(
                "V4.9E terminal convergence is not owned by retained live authority"
            )
        return self._converge_actor_terminal_core_v49e(
            terminal_event,
            signer=signer,
            idempotency_key=idempotency_key,
        )

    def append_inbound_websocket_protocol_failure(
        self,
        failure: InboundWebSocketProtocolFailureV4,
        *,
        idempotency_key: str,
    ) -> InboundWebSocketProtocolFailureV4:
        """Append one reviewed parser failure over prior durable ingress."""

        if type(failure) is not InboundWebSocketProtocolFailureV4:
            raise CanonicalizationError(
                "failure must be an exact InboundWebSocketProtocolFailureV4"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_INBOUND_WEBSOCKET_PROTOCOL_FAILURE_V4_6"
        request = _request_hash(operation, failure.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.INBOUND_WEBSOCKET_PROTOCOL_FAILURE,
                    str(replay["inbound_websocket_protocol_failure_id"]),
                )
                assert isinstance(loaded, InboundWebSocketProtocolFailureV4)
                return loaded
            operation_now = self._now()
            session, _, _, _, deployment = self._control_authority_context(
                operation_now=operation_now,
                transport_session_id=failure.transport_session_id,
                socket_lease_id=failure.socket_lease_id,
                connection_generation=failure.connection_generation,
                deployment_bundle_id=failure.deployment_bundle_id,
                writer_fence_token_sha256=failure.writer_fence_token_sha256,
                writer_fence_generation=failure.writer_fence_generation,
                monotonic_clock_domain_id=failure.monotonic_clock_domain_id,
                transport_subscription_policy_id=(
                    failure.transport_subscription_policy_id
                ),
                physical_scope_manifest_id=failure.physical_scope_manifest_id,
                adapter_policy_id=failure.adapter_policy_id,
                capture_partition_id=failure.capture_partition_id,
            )
            self._assert_control_side_effect_open(
                transport_session_id=failure.transport_session_id
            )
            raw = self._load_record(
                PhysicalRecordKindV4.RAW_INGRESS_COMMIT,
                failure.raw_ingress_commit_id,
            )
            assert isinstance(raw, RawIngressCommitV4)
            exact_fields = (
                "transport_subscription_policy_id",
                "transport_session_id",
                "physical_scope_manifest_id",
                "adapter_policy_id",
                "capture_partition_id",
                "socket_lease_id",
                "connection_generation",
                "deployment_bundle_id",
                "writer_fence_token_sha256",
                "writer_fence_generation",
                "ingress_sequence",
                "raw_ingress_chunks_base64",
                "raw_ingress_chunks_sha256",
                "raw_ingress_batch_sha256",
                "monotonic_clock_domain_id",
            )
            if any(
                getattr(failure, name) != getattr(raw, name) for name in exact_fields
            ) or (
                failure.ingress_sequence != 1
                or failure.frame_offset != 0
                or failure.detected_at < raw.received_at
                or failure.detected_at
                < self._control_record_receipt_clock(raw.raw_ingress_commit_id)
                or failure.detected_at >= deployment.valid_until
                or failure.detected_monotonic_ns <= raw.received_monotonic_ns
                or failure.detected_monotonic_ns
                <= session.handshake_completed_monotonic_ns
                or operation_now < failure.detected_at
            ):
                raise PhysicalProjectionV4ConflictError(
                    "protocol failure differs from raw ingress or active chronology"
                )
            overlap = self._connection.execute(
                """
                SELECT 1 FROM inbound_rfc_control_triggers
                WHERE raw_ingress_commit_id = ?
                """,
                (
                    _blob_hash(
                        failure.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                ),
            ).fetchone()
            if overlap is not None:
                raise PhysicalProjectionV4ConflictError(
                    "protocol failure at the first frame invalidates every later "
                    "RFC control view in the same raw ingress batch"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(failure, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO inbound_websocket_protocol_failures(
                    inbound_websocket_protocol_failure_id,
                    transport_subscription_policy_id, transport_session_id,
                    physical_scope_manifest_id, adapter_policy_id,
                    capture_partition_id, socket_lease_id,
                    connection_generation, deployment_bundle_id,
                    writer_fence_token_sha256, writer_fence_generation,
                    ingress_sequence, raw_ingress_commit_id,
                    raw_ingress_chunks_blob, raw_ingress_chunk_hashes_blob,
                    raw_ingress_batch_sha256, frame_offset,
                    protocol_failure_kind, parser_exception_class_digest,
                    parser_exception_message_digest,
                    logical_close_payload_base64,
                    logical_close_payload_sha256, detected_at_us,
                    monotonic_clock_domain_id, detected_monotonic_ns,
                    fences_session_authority, source_receipt_sequence,
                    source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        failure.inbound_websocket_protocol_failure_id,
                        field="inbound_websocket_protocol_failure_id",
                    ),
                    _blob_hash(
                        failure.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        failure.transport_session_id,
                        field="transport_session_id",
                    ),
                    _blob_hash(
                        failure.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(failure.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        failure.capture_partition_id, field="capture_partition_id"
                    ),
                    _blob_hash(failure.socket_lease_id, field="socket_lease_id"),
                    failure.connection_generation,
                    _blob_hash(
                        failure.deployment_bundle_id, field="deployment_bundle_id"
                    ),
                    _blob_hash(
                        failure.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    failure.writer_fence_generation,
                    failure.ingress_sequence,
                    _blob_hash(
                        failure.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                    canonical_json_bytes(list(failure.raw_ingress_chunks_base64)),
                    canonical_json_bytes(list(failure.raw_ingress_chunks_sha256)),
                    _blob_hash(
                        failure.raw_ingress_batch_sha256,
                        field="raw_ingress_batch_sha256",
                    ),
                    failure.frame_offset,
                    failure.protocol_failure_kind.value,
                    _blob_hash(
                        failure.parser_exception_class_digest,
                        field="parser_exception_class_digest",
                    ),
                    _blob_hash(
                        failure.parser_exception_message_digest,
                        field="parser_exception_message_digest",
                    ),
                    failure.logical_close_payload_base64,
                    _blob_hash(
                        failure.logical_close_payload_sha256,
                        field="logical_close_payload_sha256",
                    ),
                    _timestamp_us(failure.detected_at, field="detected_at"),
                    _blob_hash(
                        failure.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    failure.detected_monotonic_ns,
                    int(failure.fences_session_authority),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_inbound_websocket_protocol_failure_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "inbound_websocket_protocol_failure_id": (
                        failure.inbound_websocket_protocol_failure_id
                    )
                },
            )
            return failure

    def append_inbound_rfc_control_trigger(
        self,
        trigger: InboundRfcControlTriggerV4,
        *,
        idempotency_key: str,
    ) -> InboundRfcControlTriggerV4:
        """Append one exact control-frame view over a prior raw ingress commit."""

        if type(trigger) is not InboundRfcControlTriggerV4:
            raise CanonicalizationError(
                "trigger must be an exact InboundRfcControlTriggerV4"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_INBOUND_RFC_CONTROL_TRIGGER_V4_5"
        request = _request_hash(operation, trigger.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.INBOUND_RFC_CONTROL_TRIGGER,
                    str(replay["inbound_rfc_control_trigger_id"]),
                )
                assert isinstance(loaded, InboundRfcControlTriggerV4)
                return loaded
            operation_now = self._now()
            self._control_authority_context(
                operation_now=operation_now,
                transport_session_id=trigger.transport_session_id,
                socket_lease_id=trigger.socket_lease_id,
                connection_generation=trigger.connection_generation,
                deployment_bundle_id=trigger.deployment_bundle_id,
                writer_fence_token_sha256=trigger.writer_fence_token_sha256,
                writer_fence_generation=trigger.writer_fence_generation,
                monotonic_clock_domain_id=trigger.monotonic_clock_domain_id,
                transport_subscription_policy_id=(
                    trigger.transport_subscription_policy_id
                ),
                physical_scope_manifest_id=trigger.physical_scope_manifest_id,
                adapter_policy_id=trigger.adapter_policy_id,
                capture_partition_id=trigger.capture_partition_id,
            )
            self._assert_control_side_effect_open(
                transport_session_id=trigger.transport_session_id
            )
            raw = self._load_record(
                PhysicalRecordKindV4.RAW_INGRESS_COMMIT,
                trigger.raw_ingress_commit_id,
            )
            assert isinstance(raw, RawIngressCommitV4)
            exact_fields = (
                "transport_subscription_policy_id",
                "transport_session_id",
                "physical_scope_manifest_id",
                "adapter_policy_id",
                "capture_partition_id",
                "socket_lease_id",
                "connection_generation",
                "deployment_bundle_id",
                "writer_fence_token_sha256",
                "writer_fence_generation",
                "ingress_sequence",
                "raw_ingress_chunks_base64",
                "raw_ingress_chunks_sha256",
                "raw_ingress_batch_sha256",
                "received_at",
                "monotonic_clock_domain_id",
                "received_monotonic_ns",
            )
            if any(
                getattr(trigger, name) != getattr(raw, name) for name in exact_fields
            ):
                raise PhysicalProjectionV4ConflictError(
                    "RFC control trigger differs from its durable raw ingress"
                )
            prior = self._connection.execute(
                """
                SELECT ingress_sequence, frame_offset
                FROM inbound_rfc_control_triggers
                WHERE transport_session_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(
                        trigger.transport_session_id, field="transport_session_id"
                    ),
                ),
            ).fetchone()
            if prior is not None and (
                trigger.ingress_sequence < int(prior[0])
                or (
                    trigger.ingress_sequence == int(prior[0])
                    and trigger.frame_offset <= int(prior[1])
                )
            ):
                raise PhysicalProjectionV4ConflictError(
                    "control trigger sequence/offset does not increase"
                )
            overlaps = self._connection.execute(
                """
                SELECT 1 FROM inbound_rfc_control_triggers
                WHERE raw_ingress_commit_id = ?
                  AND frame_offset < ?
                  AND ? < frame_offset + frame_length
                """,
                (
                    _blob_hash(
                        trigger.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                    trigger.frame_offset + trigger.frame_length,
                    trigger.frame_offset,
                ),
            ).fetchone()
            if overlaps is not None:
                raise PhysicalProjectionV4ConflictError(
                    "control trigger overlaps an existing frame in the raw batch"
                )
            failed_raw = self._connection.execute(
                """
                SELECT 1 FROM inbound_websocket_protocol_failures
                WHERE raw_ingress_commit_id = ?
                """,
                (
                    _blob_hash(
                        trigger.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                ),
            ).fetchone()
            if failed_raw is not None:
                raise PhysicalProjectionV4ConflictError(
                    "RFC control trigger follows a first-frame protocol failure "
                    "in the same raw ingress batch"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(trigger, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO inbound_rfc_control_triggers(
                    inbound_rfc_control_trigger_id,
                    transport_subscription_policy_id, transport_session_id,
                    physical_scope_manifest_id, adapter_policy_id,
                    capture_partition_id, socket_lease_id,
                    connection_generation, deployment_bundle_id,
                    writer_fence_token_sha256, writer_fence_generation,
                    ingress_sequence, raw_ingress_commit_id,
                    raw_ingress_chunks_blob, raw_ingress_chunk_hashes_blob,
                    raw_ingress_batch_sha256, frame_offset, frame_length,
                    opcode, payload_base64, payload_sha256, received_at_us,
                    monotonic_clock_domain_id, received_monotonic_ns,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        trigger.inbound_rfc_control_trigger_id,
                        field="inbound_rfc_control_trigger_id",
                    ),
                    _blob_hash(
                        trigger.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        trigger.transport_session_id, field="transport_session_id"
                    ),
                    _blob_hash(
                        trigger.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(trigger.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        trigger.capture_partition_id, field="capture_partition_id"
                    ),
                    _blob_hash(trigger.socket_lease_id, field="socket_lease_id"),
                    trigger.connection_generation,
                    _blob_hash(
                        trigger.deployment_bundle_id, field="deployment_bundle_id"
                    ),
                    _blob_hash(
                        trigger.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    trigger.writer_fence_generation,
                    trigger.ingress_sequence,
                    _blob_hash(
                        trigger.raw_ingress_commit_id,
                        field="raw_ingress_commit_id",
                    ),
                    canonical_json_bytes(list(trigger.raw_ingress_chunks_base64)),
                    canonical_json_bytes(list(trigger.raw_ingress_chunks_sha256)),
                    _blob_hash(
                        trigger.raw_ingress_batch_sha256,
                        field="raw_ingress_batch_sha256",
                    ),
                    trigger.frame_offset,
                    trigger.frame_length,
                    trigger.opcode.value,
                    trigger.payload_base64,
                    _blob_hash(trigger.payload_sha256, field="payload_sha256"),
                    _timestamp_us(trigger.received_at, field="received_at"),
                    _blob_hash(
                        trigger.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    trigger.received_monotonic_ns,
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_inbound_rfc_control_trigger_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "inbound_rfc_control_trigger_id": (
                        trigger.inbound_rfc_control_trigger_id
                    )
                },
            )
            return trigger

    def append_outbound_control_intent(
        self,
        intent: OutboundControlIntentV4,
        *,
        idempotency_key: str,
    ) -> OutboundControlIntentV4:
        """Append one session-local logical heartbeat/Pong/Close intent."""

        if type(intent) is not OutboundControlIntentV4:
            raise CanonicalizationError(
                "intent must be an exact OutboundControlIntentV4"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_OUTBOUND_CONTROL_INTENT_V4_5"
        request = _request_hash(operation, intent.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.OUTBOUND_CONTROL_INTENT,
                    str(replay["outbound_control_intent_id"]),
                )
                assert isinstance(loaded, OutboundControlIntentV4)
                return loaded
            operation_now = self._now()
            session, policy, _, _, deployment = self._control_authority_context(
                operation_now=operation_now,
                transport_session_id=intent.transport_session_id,
                socket_lease_id=intent.socket_lease_id,
                connection_generation=intent.connection_generation,
                deployment_bundle_id=intent.deployment_bundle_id,
                writer_fence_token_sha256=intent.writer_fence_token_sha256,
                writer_fence_generation=intent.writer_fence_generation,
                monotonic_clock_domain_id=intent.monotonic_clock_domain_id,
                transport_subscription_policy_id=(
                    intent.transport_subscription_policy_id
                ),
                physical_scope_manifest_id=intent.physical_scope_manifest_id,
                adapter_policy_id=intent.adapter_policy_id,
                capture_partition_id=intent.capture_partition_id,
            )
            self._assert_control_side_effect_open(
                transport_session_id=intent.transport_session_id,
                allowed_close_trigger_id=(
                    intent.inbound_rfc_control_trigger_id
                    if intent.control_kind is OutboundControlKindV4.RFC_CLOSE_REPLY
                    else None
                ),
                allowed_protocol_failure_id=(
                    intent.protocol_failure_evidence_id
                    if intent.control_kind
                    is OutboundControlKindV4.RFC_PROTOCOL_FAILURE_CLOSE
                    else None
                ),
            )
            if intent.request_id is not None and (
                self._connection.execute(
                    """
                    SELECT 1 FROM outbound_subscription_intents
                    WHERE transport_session_id = ? AND request_id = ?
                    """,
                    (
                        _blob_hash(
                            intent.transport_session_id,
                            field="transport_session_id",
                        ),
                        intent.request_id,
                    ),
                ).fetchone()
                is not None
            ):
                raise PhysicalProjectionV4ConflictError(
                    "control and subscription request IDs collide within a session"
                )
            prior = self._connection.execute(
                """
                SELECT outbound_control_intent_id, control_sequence,
                       authorized_at_us, authorized_monotonic_ns
                FROM outbound_control_intents
                WHERE transport_session_id = ?
                ORDER BY control_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(
                        intent.transport_session_id, field="transport_session_id"
                    ),
                ),
            ).fetchone()
            if prior is None:
                chain_ok = (
                    intent.control_sequence == 1
                    and intent.previous_outbound_control_intent_id is None
                )
            else:
                chain_ok = (
                    intent.control_sequence == int(prior[1]) + 1
                    and intent.previous_outbound_control_intent_id
                    == bytes(prior[0]).hex()
                    and _timestamp_us(intent.authorized_at, field="authorized_at")
                    >= int(prior[2])
                    and intent.authorized_monotonic_ns > int(prior[3])
                )
            if not chain_ok:
                raise PhysicalProjectionV4ConflictError(
                    "outbound control intent does not exactly extend its session chain"
                )
            if (
                intent.authorized_at < session.handshake_completed_at
                or intent.authorized_at < deployment.valid_from
                or intent.authorized_at >= deployment.valid_until
                or intent.send_not_after > deployment.valid_until
                or intent.authorized_monotonic_ns
                <= session.handshake_completed_monotonic_ns
                or operation_now < intent.authorized_at
                or operation_now >= intent.send_not_after
                or (
                    intent.send_not_after - intent.authorized_at
                    > timedelta(seconds=policy.send_deadline_seconds)
                )
                or (
                    intent.send_not_after_monotonic_ns - intent.authorized_monotonic_ns
                    > policy.send_deadline_seconds * 1_000_000_000
                )
            ):
                raise PhysicalProjectionV4ConflictError(
                    "outbound control intent violates session/deployment/send deadline"
                )
            if intent.inbound_rfc_control_trigger_id is not None:
                trigger = self._load_record(
                    PhysicalRecordKindV4.INBOUND_RFC_CONTROL_TRIGGER,
                    intent.inbound_rfc_control_trigger_id,
                )
                assert isinstance(trigger, InboundRfcControlTriggerV4)
                exact = (
                    intent.transport_subscription_policy_id
                    == trigger.transport_subscription_policy_id
                    and intent.transport_session_id == trigger.transport_session_id
                    and intent.physical_scope_manifest_id
                    == trigger.physical_scope_manifest_id
                    and intent.adapter_policy_id == trigger.adapter_policy_id
                    and intent.capture_partition_id == trigger.capture_partition_id
                    and intent.socket_lease_id == trigger.socket_lease_id
                    and intent.connection_generation == trigger.connection_generation
                    and intent.deployment_bundle_id == trigger.deployment_bundle_id
                    and intent.writer_fence_token_sha256
                    == trigger.writer_fence_token_sha256
                    and intent.writer_fence_generation
                    == trigger.writer_fence_generation
                    and intent.inbound_rfc_opcode is trigger.opcode
                    and intent.inbound_rfc_payload_base64 == trigger.payload_base64
                    and intent.logical_payload_base64 == trigger.payload_base64
                    and intent.logical_payload_sha256 == trigger.payload_sha256
                    and intent.monotonic_clock_domain_id
                    == trigger.monotonic_clock_domain_id
                    and intent.authorized_at >= trigger.received_at
                    and intent.authorized_at
                    >= self._control_record_receipt_clock(
                        trigger.inbound_rfc_control_trigger_id
                    )
                    and intent.authorized_monotonic_ns > trigger.received_monotonic_ns
                )
                if not exact:
                    raise PhysicalProjectionV4ConflictError(
                        "reactive control intent differs from its exact raw trigger"
                    )
            elif intent.control_kind in {
                OutboundControlKindV4.RFC_PONG,
                OutboundControlKindV4.RFC_CLOSE_REPLY,
            }:
                raise PhysicalProjectionV4ConflictError(
                    "reactive control intent lacks a durable RFC trigger"
                )
            if intent.control_kind is OutboundControlKindV4.RFC_PROTOCOL_FAILURE_CLOSE:
                assert intent.protocol_failure_evidence_id is not None
                failure = self._load_record(
                    PhysicalRecordKindV4.INBOUND_WEBSOCKET_PROTOCOL_FAILURE,
                    intent.protocol_failure_evidence_id,
                )
                assert isinstance(failure, InboundWebSocketProtocolFailureV4)
                exact_failure_fields = (
                    "transport_subscription_policy_id",
                    "transport_session_id",
                    "physical_scope_manifest_id",
                    "adapter_policy_id",
                    "capture_partition_id",
                    "socket_lease_id",
                    "connection_generation",
                    "deployment_bundle_id",
                    "writer_fence_token_sha256",
                    "writer_fence_generation",
                    "monotonic_clock_domain_id",
                )
                if any(
                    getattr(intent, name) != getattr(failure, name)
                    for name in exact_failure_fields
                ) or (
                    intent.logical_payload_base64
                    != failure.logical_close_payload_base64
                    or intent.logical_payload_sha256
                    != failure.logical_close_payload_sha256
                    or intent.authorized_at < failure.detected_at
                    or intent.authorized_at
                    < self._control_record_receipt_clock(
                        failure.inbound_websocket_protocol_failure_id
                    )
                    or intent.authorized_monotonic_ns <= failure.detected_monotonic_ns
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "protocol-failure Close differs from its exact typed cause"
                    )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(intent, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO outbound_control_intents(
                    outbound_control_intent_id,
                    transport_subscription_policy_id, transport_session_id,
                    physical_scope_manifest_id, adapter_policy_id,
                    capture_partition_id, socket_lease_id,
                    connection_generation, deployment_bundle_id,
                    writer_fence_token_sha256, writer_fence_generation,
                    control_sequence, previous_outbound_control_intent_id,
                    control_kind, scheduled_heartbeat_id,
                    inbound_rfc_control_trigger_id, inbound_rfc_opcode,
                    inbound_rfc_payload_base64, protocol_failure_evidence_id,
                    logical_websocket_opcode, logical_payload_base64,
                    logical_payload_sha256, request_id,
                    fences_session_authority, authorized_at_us,
                    monotonic_clock_domain_id, authorized_monotonic_ns,
                    send_not_after_us, send_not_after_monotonic_ns,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        intent.outbound_control_intent_id,
                        field="outbound_control_intent_id",
                    ),
                    _blob_hash(
                        intent.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        intent.transport_session_id, field="transport_session_id"
                    ),
                    _blob_hash(
                        intent.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(intent.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        intent.capture_partition_id, field="capture_partition_id"
                    ),
                    _blob_hash(intent.socket_lease_id, field="socket_lease_id"),
                    intent.connection_generation,
                    _blob_hash(
                        intent.deployment_bundle_id, field="deployment_bundle_id"
                    ),
                    _blob_hash(
                        intent.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    intent.writer_fence_generation,
                    intent.control_sequence,
                    None
                    if intent.previous_outbound_control_intent_id is None
                    else _blob_hash(
                        intent.previous_outbound_control_intent_id,
                        field="previous_outbound_control_intent_id",
                    ),
                    intent.control_kind.value,
                    None
                    if intent.scheduled_heartbeat_id is None
                    else _blob_hash(
                        intent.scheduled_heartbeat_id,
                        field="scheduled_heartbeat_id",
                    ),
                    None
                    if intent.inbound_rfc_control_trigger_id is None
                    else _blob_hash(
                        intent.inbound_rfc_control_trigger_id,
                        field="inbound_rfc_control_trigger_id",
                    ),
                    None
                    if intent.inbound_rfc_opcode is None
                    else intent.inbound_rfc_opcode.value,
                    intent.inbound_rfc_payload_base64,
                    None
                    if intent.protocol_failure_evidence_id is None
                    else _blob_hash(
                        intent.protocol_failure_evidence_id,
                        field="protocol_failure_evidence_id",
                    ),
                    intent.logical_websocket_opcode.value,
                    intent.logical_payload_base64,
                    _blob_hash(
                        intent.logical_payload_sha256,
                        field="logical_payload_sha256",
                    ),
                    intent.request_id,
                    int(intent.fences_session_authority),
                    _timestamp_us(intent.authorized_at, field="authorized_at"),
                    _blob_hash(
                        intent.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    intent.authorized_monotonic_ns,
                    _timestamp_us(intent.send_not_after, field="send_not_after"),
                    intent.send_not_after_monotonic_ns,
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_outbound_control_intent_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "outbound_control_intent_id": intent.outbound_control_intent_id
                },
            )
            return intent

    def append_outbound_control_wire_prepared(
        self,
        wire: OutboundControlWirePreparedV4,
        *,
        idempotency_key: str,
    ) -> OutboundControlWirePreparedV4:
        """Append the sole exact masked pre-TLS frame for one control intent."""

        if type(wire) is not OutboundControlWirePreparedV4:
            raise CanonicalizationError(
                "wire must be an exact OutboundControlWirePreparedV4"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_OUTBOUND_CONTROL_WIRE_PREPARED_V4_5"
        request = _request_hash(operation, wire.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.OUTBOUND_CONTROL_WIRE_PREPARED,
                    str(replay["outbound_control_wire_prepared_id"]),
                )
                assert isinstance(loaded, OutboundControlWirePreparedV4)
                return loaded
            operation_now = self._now()
            session, _, _, _, deployment = self._control_authority_context(
                operation_now=operation_now,
                transport_session_id=wire.transport_session_id,
                socket_lease_id=wire.socket_lease_id,
                connection_generation=wire.connection_generation,
                deployment_bundle_id=wire.deployment_bundle_id,
                writer_fence_token_sha256=wire.writer_fence_token_sha256,
                writer_fence_generation=wire.writer_fence_generation,
                monotonic_clock_domain_id=wire.monotonic_clock_domain_id,
            )
            intent = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_INTENT,
                wire.outbound_control_intent_id,
            )
            assert isinstance(intent, OutboundControlIntentV4)
            self._assert_control_side_effect_open(
                transport_session_id=wire.transport_session_id,
                allowed_fencing_intent_id=intent.outbound_control_intent_id,
            )
            exact_fields = (
                "transport_session_id",
                "socket_lease_id",
                "connection_generation",
                "deployment_bundle_id",
                "writer_fence_token_sha256",
                "writer_fence_generation",
                "control_kind",
                "logical_websocket_opcode",
                "logical_payload_base64",
                "logical_payload_sha256",
                "monotonic_clock_domain_id",
                "send_not_after",
                "send_not_after_monotonic_ns",
            )
            if any(
                getattr(wire, name) != getattr(intent, name) for name in exact_fields
            ):
                raise PhysicalProjectionV4ConflictError(
                    "prepared control wire differs from its exact intent"
                )
            if (
                wire.prepared_at < intent.authorized_at
                or wire.prepared_at
                < self._control_record_receipt_clock(intent.outbound_control_intent_id)
                or wire.prepared_monotonic_ns <= intent.authorized_monotonic_ns
                or wire.prepared_at >= deployment.valid_until
                or wire.prepared_monotonic_ns
                <= session.handshake_completed_monotonic_ns
                or operation_now < wire.prepared_at
                or operation_now >= wire.send_not_after
            ):
                raise PhysicalProjectionV4ConflictError(
                    "prepared control wire violates intent/session chronology or "
                    "send deadline"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(wire, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO outbound_control_wire_prepared(
                    outbound_control_wire_prepared_id,
                    outbound_control_intent_id, transport_session_id,
                    socket_lease_id, connection_generation,
                    deployment_bundle_id, writer_fence_token_sha256,
                    writer_fence_generation, control_kind,
                    logical_websocket_opcode, logical_payload_base64,
                    logical_payload_sha256, wire_chunks_blob,
                    wire_chunk_hashes_blob, wire_batch_sha256,
                    wire_octet_length, prepared_at_us,
                    monotonic_clock_domain_id, prepared_monotonic_ns,
                    send_not_after_us, send_not_after_monotonic_ns,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        wire.outbound_control_wire_prepared_id,
                        field="outbound_control_wire_prepared_id",
                    ),
                    _blob_hash(
                        wire.outbound_control_intent_id,
                        field="outbound_control_intent_id",
                    ),
                    _blob_hash(wire.transport_session_id, field="transport_session_id"),
                    _blob_hash(wire.socket_lease_id, field="socket_lease_id"),
                    wire.connection_generation,
                    _blob_hash(wire.deployment_bundle_id, field="deployment_bundle_id"),
                    _blob_hash(
                        wire.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    wire.writer_fence_generation,
                    wire.control_kind.value,
                    wire.logical_websocket_opcode.value,
                    wire.logical_payload_base64,
                    _blob_hash(
                        wire.logical_payload_sha256,
                        field="logical_payload_sha256",
                    ),
                    canonical_json_bytes(list(wire.wire_chunks_base64)),
                    canonical_json_bytes(list(wire.wire_chunks_sha256)),
                    _blob_hash(wire.wire_batch_sha256, field="wire_batch_sha256"),
                    wire.wire_octet_length,
                    _timestamp_us(wire.prepared_at, field="prepared_at"),
                    _blob_hash(
                        wire.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    wire.prepared_monotonic_ns,
                    _timestamp_us(wire.send_not_after, field="send_not_after"),
                    wire.send_not_after_monotonic_ns,
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_outbound_control_wire_prepared_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "outbound_control_wire_prepared_id": (
                        wire.outbound_control_wire_prepared_id
                    )
                },
            )
            return wire

    def consume_outbound_control_write_permit(
        self,
        outbound_control_wire_prepared_id: str,
        *,
        permit_consumed_at: datetime,
        permit_consumed_monotonic_ns: int,
        idempotency_key: str,
    ) -> OutboundControlWritePermitConsumedV4:
        """Durably consume attempt one before the caller may touch TLS."""

        wire_id = canonical_hash(
            outbound_control_wire_prepared_id,
            field="outbound_control_wire_prepared_id",
        )
        consumed_at = utc_datetime(permit_consumed_at, field="permit_consumed_at")
        consumed_ns = canonical_safe_int(
            permit_consumed_monotonic_ns,
            field="permit_consumed_monotonic_ns",
            minimum=0,
        )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "CONSUME_OUTBOUND_CONTROL_WRITE_PERMIT_V4_6"
        request_payload = {
            "outbound_control_wire_prepared_id": wire_id,
            "permit_consumed_at": utc_iso(consumed_at),
            "permit_consumed_monotonic_ns": consumed_ns,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                raise PhysicalProjectionV4ConflictError(
                    "write permit is already consumed; replay is evidence only"
                )
            wire = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_WIRE_PREPARED,
                wire_id,
            )
            assert isinstance(wire, OutboundControlWirePreparedV4)
            consumed = self._connection.execute(
                """
                SELECT permit_id FROM outbound_control_write_permits_consumed
                WHERE outbound_control_wire_prepared_id = ?
                """,
                (
                    _blob_hash(
                        wire.outbound_control_wire_prepared_id,
                        field="outbound_control_wire_prepared_id",
                    ),
                ),
            ).fetchone()
            if consumed is not None:
                raise PhysicalProjectionV4ConflictError(
                    "write permit is already consumed; replay is evidence only"
                )
            operation_now = self._now()
            session, _, _, _, deployment = self._control_authority_context(
                operation_now=operation_now,
                transport_session_id=wire.transport_session_id,
                socket_lease_id=wire.socket_lease_id,
                connection_generation=wire.connection_generation,
                deployment_bundle_id=wire.deployment_bundle_id,
                writer_fence_token_sha256=wire.writer_fence_token_sha256,
                writer_fence_generation=wire.writer_fence_generation,
                monotonic_clock_domain_id=wire.monotonic_clock_domain_id,
            )
            intent = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_INTENT,
                wire.outbound_control_intent_id,
            )
            assert isinstance(intent, OutboundControlIntentV4)
            self._assert_control_side_effect_open(
                transport_session_id=wire.transport_session_id,
                allowed_fencing_intent_id=intent.outbound_control_intent_id,
            )
            if (
                consumed_at
                < self._control_record_receipt_clock(
                    wire.outbound_control_wire_prepared_id
                )
                or consumed_at >= deployment.valid_until
                or consumed_ns <= session.handshake_completed_monotonic_ns
                or operation_now < consumed_at
                or operation_now >= wire.send_not_after
                or consumed_at >= wire.send_not_after
                or consumed_ns >= wire.send_not_after_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "write-permit consumption violates durable wire, authority, "
                    "or send deadlines"
                )
            permit = OutboundControlWritePermitConsumedV4(
                outbound_control_intent_id=wire.outbound_control_intent_id,
                outbound_control_wire_prepared_id=(
                    wire.outbound_control_wire_prepared_id
                ),
                transport_session_id=wire.transport_session_id,
                socket_lease_id=wire.socket_lease_id,
                connection_generation=wire.connection_generation,
                deployment_bundle_id=wire.deployment_bundle_id,
                writer_fence_token_sha256=wire.writer_fence_token_sha256,
                writer_fence_generation=wire.writer_fence_generation,
                control_kind=wire.control_kind,
                wire_batch_sha256=wire.wire_batch_sha256,
                wire_octet_length=wire.wire_octet_length,
                one_shot_attempt_ordinal=1,
                wire_prepared_at=wire.prepared_at,
                monotonic_clock_domain_id=wire.monotonic_clock_domain_id,
                wire_prepared_monotonic_ns=wire.prepared_monotonic_ns,
                permit_consumed_at=consumed_at,
                permit_consumed_monotonic_ns=consumed_ns,
                send_not_after=wire.send_not_after,
                send_not_after_monotonic_ns=wire.send_not_after_monotonic_ns,
            )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(permit, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO outbound_control_write_permits_consumed(
                    permit_id, outbound_control_intent_id,
                    outbound_control_wire_prepared_id,
                    transport_session_id, socket_lease_id,
                    connection_generation, deployment_bundle_id,
                    writer_fence_token_sha256, writer_fence_generation,
                    control_kind, wire_batch_sha256, wire_octet_length,
                    one_shot_attempt_ordinal, wire_prepared_at_us,
                    monotonic_clock_domain_id, wire_prepared_monotonic_ns,
                    permit_consumed_at_us, permit_consumed_monotonic_ns,
                    send_not_after_us, send_not_after_monotonic_ns,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(permit.permit_id, field="permit_id"),
                    _blob_hash(
                        permit.outbound_control_intent_id,
                        field="outbound_control_intent_id",
                    ),
                    _blob_hash(
                        permit.outbound_control_wire_prepared_id,
                        field="outbound_control_wire_prepared_id",
                    ),
                    _blob_hash(
                        permit.transport_session_id, field="transport_session_id"
                    ),
                    _blob_hash(permit.socket_lease_id, field="socket_lease_id"),
                    permit.connection_generation,
                    _blob_hash(
                        permit.deployment_bundle_id, field="deployment_bundle_id"
                    ),
                    _blob_hash(
                        permit.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    permit.writer_fence_generation,
                    permit.control_kind.value,
                    _blob_hash(permit.wire_batch_sha256, field="wire_batch_sha256"),
                    permit.wire_octet_length,
                    permit.one_shot_attempt_ordinal,
                    _timestamp_us(permit.wire_prepared_at, field="wire_prepared_at"),
                    _blob_hash(
                        permit.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    permit.wire_prepared_monotonic_ns,
                    _timestamp_us(
                        permit.permit_consumed_at, field="permit_consumed_at"
                    ),
                    permit.permit_consumed_monotonic_ns,
                    _timestamp_us(permit.send_not_after, field="send_not_after"),
                    permit.send_not_after_monotonic_ns,
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_outbound_control_write_permit_consumed_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={"permit_id": permit.permit_id},
            )
            return permit

    def classify_outbound_control_orphans(
        self,
        transport_session_id: str,
    ) -> OutboundControlOrphanClassificationV4:
        """Classify one session's crash prefixes without mutating or retrying."""

        session_id = canonical_hash(transport_session_id, field="transport_session_id")
        session_row = self._connection.execute(
            """
            SELECT connection_generation
            FROM transport_session_attestations
            WHERE transport_session_id = ?
            """,
            (_blob_hash(session_id, field="transport_session_id"),),
        ).fetchone()
        if session_row is None:
            raise PhysicalProjectionV4ConflictError(
                "orphan classification requires an admitted transport session"
            )
        binding = self._connection.execute(
            """
            SELECT socket_lease_id, writer_fence_token_sha256,
                   writer_fence_generation
            FROM transport_control_socket_bindings
            WHERE transport_session_id = ?
            """,
            (_blob_hash(session_id, field="transport_session_id"),),
        ).fetchone()
        if binding is None:
            raise PhysicalProjectionV4VerificationError(
                "transport session lacks its required eager socket-owner binding"
            )
        terminal = (
            self._connection.execute(
                """
                SELECT 1 FROM transport_session_terminations
                WHERE transport_session_id = ?
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            ).fetchone()
            is not None
        )
        prepared = tuple(
            bytes(row[0]).hex()
            for row in self._connection.execute(
                """
                SELECT w.outbound_control_wire_prepared_id
                FROM outbound_control_wire_prepared AS w
                LEFT JOIN outbound_control_write_permits_consumed AS p
                  ON p.outbound_control_wire_prepared_id =
                     w.outbound_control_wire_prepared_id
                WHERE p.permit_id IS NULL
                  AND w.transport_session_id = ?
                ORDER BY w.source_receipt_sequence
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            )
        )
        consumed = tuple(
            bytes(row[0]).hex()
            for row in self._connection.execute(
                """
                SELECT p.permit_id
                FROM outbound_control_write_permits_consumed AS p
                LEFT JOIN outbound_control_dispatch_results AS d
                  ON d.permit_id = p.permit_id
                WHERE d.outbound_control_dispatch_result_id IS NULL
                  AND p.transport_session_id = ?
                ORDER BY p.source_receipt_sequence
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            )
        )
        return OutboundControlOrphanClassificationV4(
            transport_session_id=session_id,
            connection_generation=int(session_row[0]),
            socket_lease_id=bytes(binding[0]).hex(),
            writer_fence_token_sha256=bytes(binding[1]).hex(),
            writer_fence_generation=int(binding[2]),
            session_is_terminal=terminal,
            prepared_without_permit_ids=prepared,
            permit_without_result_ids=consumed,
        )

    def append_outbound_control_dispatch_result(
        self,
        dispatch: OutboundControlDispatchResultV4,
        *,
        idempotency_key: str,
    ) -> OutboundControlDispatchResultV4:
        """Append the sole signed one-shot outcome for one prepared frame."""

        if type(dispatch) is not OutboundControlDispatchResultV4:
            raise CanonicalizationError(
                "dispatch must be an exact OutboundControlDispatchResultV4"
            )
        dispatch.verify_signature()
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_OUTBOUND_CONTROL_DISPATCH_RESULT_V4_6"
        request = _request_hash(operation, dispatch.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.OUTBOUND_CONTROL_DISPATCH_RESULT,
                    str(replay["outbound_control_dispatch_result_id"]),
                )
                assert isinstance(loaded, OutboundControlDispatchResultV4)
                return loaded
            operation_now = self._now()
            permit = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_WRITE_PERMIT_CONSUMED,
                dispatch.permit_id,
            )
            wire = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_WIRE_PREPARED,
                dispatch.outbound_control_wire_prepared_id,
            )
            intent = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_CONTROL_INTENT,
                dispatch.outbound_control_intent_id,
            )
            assert isinstance(permit, OutboundControlWritePermitConsumedV4)
            assert isinstance(wire, OutboundControlWirePreparedV4)
            assert isinstance(intent, OutboundControlIntentV4)
            session = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION,
                dispatch.transport_session_id,
            )
            assert isinstance(session, TransportSessionAttestationV4)
            policy = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SUBSCRIPTION_POLICY,
                session.transport_subscription_policy_id,
            )
            assert isinstance(policy, TransportSubscriptionPolicyV4)
            deployment_row = self._connection.execute(
                """
                SELECT deployment_bundle_approval_id
                FROM deployment_bundle_approvals
                WHERE deployment_bundle_id = ?
                """,
                (
                    _blob_hash(
                        permit.deployment_bundle_id,
                        field="deployment_bundle_id",
                    ),
                ),
            ).fetchone()
            if deployment_row is None:
                raise PhysicalProjectionV4ConflictError(
                    "dispatch permit lacks its admitted deployment"
                )
            deployment = self._load_verified_deployment_capability(
                bytes(deployment_row[0]).hex()
            )
            self._assert_control_side_effect_open(
                transport_session_id=dispatch.transport_session_id,
                allowed_fencing_intent_id=intent.outbound_control_intent_id,
                allowed_orphaned_permit_id=permit.permit_id,
            )
            active_fence = self._read_and_validate_transport_writer_fence()
            if active_fence is None or (
                not active_fence[1]
                or active_fence[0] != dispatch.writer_fence_generation
                or not secrets.compare_digest(
                    active_fence[2],
                    _blob_hash(
                        dispatch.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                )
            ):
                raise PhysicalProjectionV4WriterFenceError(
                    "dispatch continuation lost its original writer fence"
                )
            exact_permit_fields = (
                "outbound_control_intent_id",
                "outbound_control_wire_prepared_id",
                "transport_session_id",
                "socket_lease_id",
                "connection_generation",
                "deployment_bundle_id",
                "writer_fence_token_sha256",
                "writer_fence_generation",
                "control_kind",
                "wire_batch_sha256",
                "wire_octet_length",
                "one_shot_attempt_ordinal",
                "monotonic_clock_domain_id",
                "send_not_after",
                "send_not_after_monotonic_ns",
            )
            if any(
                getattr(dispatch, name) != getattr(permit, name)
                for name in exact_permit_fields
            ) or (
                permit.outbound_control_wire_prepared_id
                != wire.outbound_control_wire_prepared_id
                or permit.outbound_control_intent_id
                != intent.outbound_control_intent_id
                or dispatch.wire_prepared_at != permit.wire_prepared_at
                or dispatch.wire_prepared_monotonic_ns
                != permit.wire_prepared_monotonic_ns
                or dispatch.dispatch_started_at <= permit.permit_consumed_at
                or dispatch.dispatch_started_monotonic_ns
                <= permit.permit_consumed_monotonic_ns
                or dispatch.collector_attestation_key_id
                != deployment.collector_attestation_key_id
                or dispatch.collector_attestation_public_key_hex
                != deployment.collector_attestation_public_key_hex
                or dispatch.collector_attestation_key_id
                != policy.collector_attestation_key_id
                or dispatch.collector_attestation_public_key_hex
                != policy.collector_attestation_public_key_hex
                or dispatch.collector_attestation_key_id
                != session.collector_attestation_key_id
                or dispatch.collector_attestation_public_key_hex
                != session.collector_attestation_public_key_hex
                or dispatch.dispatch_started_at
                < self._control_record_receipt_clock(permit.permit_id)
                or dispatch.dispatch_started_monotonic_ns
                <= session.handshake_completed_monotonic_ns
                or operation_now < dispatch.dispatch_outcome_at
            ):
                raise PhysicalProjectionV4ConflictError(
                    "signed control dispatch is not the exact non-authorizing "
                    "continuation of its durable permit"
                )
            socket_row = self._connection.execute(
                """
                SELECT socket_lease_id, deployment_bundle_id,
                       writer_fence_token_sha256, writer_fence_generation,
                       connection_generation, monotonic_clock_domain_id
                FROM transport_control_socket_bindings
                WHERE transport_session_id = ?
                """,
                (
                    _blob_hash(
                        dispatch.transport_session_id,
                        field="transport_session_id",
                    ),
                ),
            ).fetchone()
            expected_socket = (
                dispatch.socket_lease_id,
                dispatch.deployment_bundle_id,
                dispatch.writer_fence_token_sha256,
                dispatch.writer_fence_generation,
                dispatch.connection_generation,
                dispatch.monotonic_clock_domain_id,
            )
            if (
                socket_row is None
                or (
                    bytes(socket_row[0]).hex(),
                    bytes(socket_row[1]).hex(),
                    bytes(socket_row[2]).hex(),
                    int(socket_row[3]),
                    int(socket_row[4]),
                    bytes(socket_row[5]).hex(),
                )
                != expected_socket
            ):
                raise PhysicalProjectionV4ConflictError(
                    "dispatch continuation differs from its durable socket binding"
                )
            termination_row = self._connection.execute(
                """
                SELECT detected_at_us, detected_monotonic_ns,
                       detected_monotonic_clock_domain_id
                FROM transport_session_terminations
                WHERE transport_session_id = ?
                """,
                (
                    _blob_hash(
                        dispatch.transport_session_id,
                        field="transport_session_id",
                    ),
                ),
            ).fetchone()
            if termination_row is not None and (
                bytes(termination_row[2]).hex() != dispatch.monotonic_clock_domain_id
                or _timestamp_us(
                    dispatch.dispatch_outcome_at,
                    field="dispatch_outcome_at",
                )
                >= int(termination_row[0])
                or dispatch.dispatch_outcome_monotonic_ns >= int(termination_row[1])
            ):
                raise PhysicalProjectionV4ConflictError(
                    "late dispatch evidence does not prove that its complete "
                    "writer observation predates terminal session detection"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(dispatch, committed_at=operation_now)
            self._connection.execute(
                """
                INSERT INTO outbound_control_dispatch_results(
                    outbound_control_dispatch_result_id,
                    outbound_control_intent_id,
                    outbound_control_wire_prepared_id,
                    transport_session_id, socket_lease_id,
                    connection_generation, deployment_bundle_id,
                    writer_fence_token_sha256, writer_fence_generation,
                    control_kind, wire_batch_sha256, wire_octet_length,
                    permit_id, permit_consumed, one_shot_attempt_ordinal,
                    disposition, wire_prepared_at_us,
                    monotonic_clock_domain_id, wire_prepared_monotonic_ns,
                    dispatch_started_at_us, dispatch_started_monotonic_ns,
                    dispatch_outcome_at_us, dispatch_outcome_monotonic_ns,
                    send_not_after_us, send_not_after_monotonic_ns,
                    bytes_submitted_to_tls, error_class_digest,
                    collector_attestation_key_id,
                    collector_attestation_public_key, signature,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        dispatch.outbound_control_dispatch_result_id,
                        field="outbound_control_dispatch_result_id",
                    ),
                    _blob_hash(
                        dispatch.outbound_control_intent_id,
                        field="outbound_control_intent_id",
                    ),
                    _blob_hash(
                        dispatch.outbound_control_wire_prepared_id,
                        field="outbound_control_wire_prepared_id",
                    ),
                    _blob_hash(
                        dispatch.transport_session_id, field="transport_session_id"
                    ),
                    _blob_hash(dispatch.socket_lease_id, field="socket_lease_id"),
                    dispatch.connection_generation,
                    _blob_hash(
                        dispatch.deployment_bundle_id, field="deployment_bundle_id"
                    ),
                    _blob_hash(
                        dispatch.writer_fence_token_sha256,
                        field="writer_fence_token_sha256",
                    ),
                    dispatch.writer_fence_generation,
                    dispatch.control_kind.value,
                    _blob_hash(dispatch.wire_batch_sha256, field="wire_batch_sha256"),
                    dispatch.wire_octet_length,
                    _blob_hash(dispatch.permit_id, field="permit_id"),
                    int(dispatch.permit_consumed),
                    dispatch.one_shot_attempt_ordinal,
                    dispatch.disposition.value,
                    _timestamp_us(dispatch.wire_prepared_at, field="wire_prepared_at"),
                    _blob_hash(
                        dispatch.monotonic_clock_domain_id,
                        field="monotonic_clock_domain_id",
                    ),
                    dispatch.wire_prepared_monotonic_ns,
                    _timestamp_us(
                        dispatch.dispatch_started_at, field="dispatch_started_at"
                    ),
                    dispatch.dispatch_started_monotonic_ns,
                    _timestamp_us(
                        dispatch.dispatch_outcome_at, field="dispatch_outcome_at"
                    ),
                    dispatch.dispatch_outcome_monotonic_ns,
                    _timestamp_us(dispatch.send_not_after, field="send_not_after"),
                    dispatch.send_not_after_monotonic_ns,
                    dispatch.bytes_submitted_to_tls,
                    None
                    if dispatch.error_class_digest is None
                    else _blob_hash(
                        dispatch.error_class_digest, field="error_class_digest"
                    ),
                    _blob_hash(
                        dispatch.collector_attestation_key_id,
                        field="collector_attestation_key_id",
                    ),
                    bytes.fromhex(dispatch.collector_attestation_public_key_hex),
                    bytes.fromhex(dispatch.signature_hex),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_outbound_control_dispatch_result_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "outbound_control_dispatch_result_id": (
                        dispatch.outbound_control_dispatch_result_id
                    )
                },
            )
            return dispatch

    def authorize_outbound_subscription_intent(
        self,
        transport_session_id: str,
        *,
        idempotency_key: str,
    ) -> OutboundSubscriptionIntentV4:
        """Create the sole permitted topic and exact outbound command internally."""

        session_id = canonical_hash(transport_session_id, field="transport_session_id")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "AUTHORIZE_OUTBOUND_SUBSCRIPTION_INTENT_V4_5"
        request_payload = {"transport_session_id": session_id}
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.OUTBOUND_SUBSCRIPTION_INTENT,
                    str(replay["outbound_subscription_intent_id"]),
                )
                assert isinstance(loaded, OutboundSubscriptionIntentV4)
                return loaded
            self._assert_control_side_effect_open(transport_session_id=session_id)
            session = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION, session_id
            )
            policy = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SUBSCRIPTION_POLICY,
                session.transport_subscription_policy_id,
            )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                session.physical_scope_manifest_id,
            )
            adapter = self._load_record(
                PhysicalRecordKindV4.PROVIDER_ADAPTER_POLICY,
                session.adapter_policy_id,
            )
            assert isinstance(session, TransportSessionAttestationV4)
            assert isinstance(policy, TransportSubscriptionPolicyV4)
            assert isinstance(scope, PhysicalScopeManifestV4)
            assert isinstance(adapter, ProviderAdapterPolicyV3)
            owner_row = self._connection.execute(
                """
                SELECT deployment_bundle_id, connection_generation,
                       monotonic_clock_domain_id, writer_fence_token_sha256,
                       writer_fence_generation
                FROM transport_control_socket_bindings
                WHERE transport_session_id = ?
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            ).fetchone()
            if owner_row is None:
                raise PhysicalProjectionV4ConflictError(
                    "subscription authorization requires an eager socket-owner binding"
                )
            fence = self._read_and_validate_transport_writer_fence()
            if fence is None or (
                not fence[1]
                or fence[0] != int(owner_row[4])
                or not secrets.compare_digest(fence[2], bytes(owner_row[3]))
            ):
                raise PhysicalProjectionV4WriterFenceError(
                    "subscription owner binding does not name the active writer fence"
                )
            if (
                session.physical_scope_manifest_id != scope.physical_scope_manifest_id
                or scope.primary_adapter_policy_id != adapter.adapter_policy_id
                or session.adapter_policy_id != adapter.adapter_policy_id
                or bytes(owner_row[0]).hex() != session.deployment_bundle_id
                or int(owner_row[1]) != session.connection_generation
                or bytes(owner_row[2]).hex() != session.monotonic_clock_domain_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "transport session or eager owner no longer resolves exact authority"
                )
            terminated = self._connection.execute(
                """
                SELECT 1 FROM transport_session_terminations
                WHERE transport_session_id = ?
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            ).fetchone()
            if terminated is not None:
                raise PhysicalProjectionV4ConflictError(
                    "terminated transport session cannot authorize subscriptions"
                )
            inflight = int(
                self._connection.execute(
                    """
                    SELECT count(*)
                    FROM outbound_subscription_intents AS i
                    LEFT JOIN subscription_ack_bindings AS b
                      ON b.outbound_subscription_intent_id =
                         i.outbound_subscription_intent_id
                    WHERE i.transport_session_id = ?
                      AND b.subscription_ack_binding_id IS NULL
                    """,
                    (_blob_hash(session_id, field="transport_session_id"),),
                ).fetchone()[0]
            )
            if inflight >= policy.maximum_inflight_subscriptions:
                raise PhysicalProjectionV4ConflictError(
                    "transport session already has its maximum unacknowledged intents"
                )
            authorized = self._now()
            if authorized < session.handshake_completed_at:
                raise PhysicalProjectionV4ConflictError(
                    "subscription authorization predates session handshake"
                )
            intent = build_outbound_subscription_intent_v4(
                transport_subscription_policy_id=(
                    session.transport_subscription_policy_id
                ),
                transport_session_id=session.transport_session_id,
                physical_scope_manifest_id=session.physical_scope_manifest_id,
                adapter_policy_id=session.adapter_policy_id,
                capture_partition_id=session.capture_partition_id,
                connection_generation=session.connection_generation,
                intent_nonce=secrets.token_hex(32),
                request_id=f"rym_{secrets.token_hex(16)}",
                topic=adapter.channel_or_schema,
                authorized_at=authorized,
                send_not_after=authorized
                + timedelta(seconds=policy.send_deadline_seconds),
                ack_not_after=authorized
                + timedelta(seconds=policy.ack_deadline_seconds),
            )
            if len(intent.request_id) > policy.maximum_request_id_length:
                raise PhysicalProjectionV4ConflictError(
                    "projection-generated request ID exceeds transport policy"
                )
            if (
                self._connection.execute(
                    """
                    SELECT 1 FROM outbound_control_intents
                    WHERE transport_session_id = ? AND request_id = ?
                    """,
                    (
                        _blob_hash(session_id, field="transport_session_id"),
                        intent.request_id,
                    ),
                ).fetchone()
                is not None
            ):
                raise PhysicalProjectionV4ConflictError(
                    "subscription and control request IDs collide within a session"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(intent)
            self._connection.execute(
                """
                INSERT INTO outbound_subscription_intents(
                    outbound_subscription_intent_id,
                    transport_subscription_policy_id, transport_session_id,
                    physical_scope_manifest_id, adapter_policy_id,
                    capture_partition_id, connection_generation, intent_nonce,
                    request_id, operation, topics_blob,
                    subscription_manifest_hash, websocket_opcode,
                    command_base64, command_sha256, authorized_at_us,
                    send_not_after_us, ack_not_after_us,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        intent.outbound_subscription_intent_id,
                        field="outbound_subscription_intent_id",
                    ),
                    _blob_hash(
                        intent.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        intent.transport_session_id, field="transport_session_id"
                    ),
                    _blob_hash(
                        intent.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(intent.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        intent.capture_partition_id, field="capture_partition_id"
                    ),
                    intent.connection_generation,
                    _blob_hash(intent.intent_nonce, field="intent_nonce"),
                    intent.request_id,
                    intent.operation,
                    canonical_json_bytes(list(intent.topics)),
                    _blob_hash(
                        intent.subscription_manifest_hash,
                        field="subscription_manifest_hash",
                    ),
                    intent.websocket_opcode,
                    intent.command_base64,
                    _blob_hash(intent.command_sha256, field="command_sha256"),
                    _timestamp_us(intent.authorized_at, field="authorized_at"),
                    _timestamp_us(intent.send_not_after, field="send_not_after"),
                    _timestamp_us(intent.ack_not_after, field="ack_not_after"),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_outbound_subscription_intent_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "outbound_subscription_intent_id": (
                        intent.outbound_subscription_intent_id
                    )
                },
            )
            return intent

    def bind_subscription_ack(
        self,
        *,
        outbound_subscription_intent_id: str,
        message_disposition_id: str,
        dispatch_started_at: datetime | str,
        dispatch_completed_at: datetime | str,
        dispatch_started_monotonic_ns: int,
        dispatch_completed_monotonic_ns: int,
        signer: Any,
        idempotency_key: str,
    ) -> SubscriptionAckBindingV4:
        """Bind one signed dispatch to its exact captured and classified ACK."""

        intent_id = canonical_hash(
            outbound_subscription_intent_id,
            field="outbound_subscription_intent_id",
        )
        disposition_id = canonical_hash(
            message_disposition_id, field="message_disposition_id"
        )
        dispatch_started = utc_datetime(
            dispatch_started_at, field="dispatch_started_at"
        )
        dispatch_completed = utc_datetime(
            dispatch_completed_at, field="dispatch_completed_at"
        )
        started_monotonic = canonical_safe_int(
            dispatch_started_monotonic_ns,
            field="dispatch_started_monotonic_ns",
            minimum=0,
        )
        completed_monotonic = canonical_safe_int(
            dispatch_completed_monotonic_ns,
            field="dispatch_completed_monotonic_ns",
            minimum=0,
        )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "BIND_SUBSCRIPTION_ACK_V4_5"
        request_payload = {
            "dispatch_completed_at": utc_iso(dispatch_completed),
            "dispatch_completed_monotonic_ns": completed_monotonic,
            "dispatch_started_at": utc_iso(dispatch_started),
            "dispatch_started_monotonic_ns": started_monotonic,
            "message_disposition_id": disposition_id,
            "outbound_subscription_intent_id": intent_id,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.SUBSCRIPTION_ACK_BINDING,
                    str(replay["subscription_ack_binding_id"]),
                )
                assert isinstance(loaded, SubscriptionAckBindingV4)
                return loaded
            intent = self._load_record(
                PhysicalRecordKindV4.OUTBOUND_SUBSCRIPTION_INTENT, intent_id
            )
            session = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION,
                intent.transport_session_id,
            )
            policy = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SUBSCRIPTION_POLICY,
                intent.transport_subscription_policy_id,
            )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                intent.physical_scope_manifest_id,
            )
            adapter = self._load_record(
                PhysicalRecordKindV4.PROVIDER_ADAPTER_POLICY,
                intent.adapter_policy_id,
            )
            disposition = self._load_record(
                PhysicalRecordKindV4.MESSAGE_DISPOSITION, disposition_id
            )
            assert isinstance(intent, OutboundSubscriptionIntentV4)
            assert isinstance(session, TransportSessionAttestationV4)
            assert isinstance(policy, TransportSubscriptionPolicyV4)
            assert isinstance(scope, PhysicalScopeManifestV4)
            assert isinstance(adapter, ProviderAdapterPolicyV3)
            assert isinstance(disposition, MessageDispositionV4)
            self._assert_control_side_effect_open(
                transport_session_id=session.transport_session_id
            )
            latest_intent = self._connection.execute(
                """
                SELECT outbound_subscription_intent_id
                FROM outbound_subscription_intents
                WHERE transport_session_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(
                        session.transport_session_id, field="transport_session_id"
                    ),
                ),
            ).fetchone()
            if latest_intent is None or bytes(latest_intent[0]).hex() != intent_id:
                raise PhysicalProjectionV4ConflictError(
                    "ACK cannot bind a superseded subscription intent"
                )
            if (
                self._connection.execute(
                    "SELECT 1 FROM transport_session_terminations WHERE transport_session_id = ?",
                    (
                        _blob_hash(
                            session.transport_session_id, field="transport_session_id"
                        ),
                    ),
                ).fetchone()
                is not None
            ):
                raise PhysicalProjectionV4ConflictError(
                    "terminated transport session cannot bind a late ACK"
                )
            row = self._connection.execute(
                """
                SELECT m.physical_message_id, m.capture_segment_id,
                       m.message_receipt_id, m.scope_message_sequence,
                       p.provider_message_disposition_id
                FROM message_dispositions AS d
                JOIN physical_messages AS m
                  ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
                 AND m.scope_message_sequence = d.scope_message_sequence
                JOIN disposition_provenance AS p
                  ON p.message_disposition_id = d.message_disposition_id
                WHERE d.message_disposition_id = ?
                """,
                (_blob_hash(disposition_id, field="message_disposition_id"),),
            ).fetchone()
            if row is None:
                raise PhysicalProjectionV4ConflictError(
                    "ACK disposition lacks exact capture/classifier provenance"
                )
            message = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_MESSAGE, bytes(row[0]).hex()
            )
            segment = self._load_record(
                PhysicalRecordKindV4.CAPTURE_SEGMENT, bytes(row[1]).hex()
            )
            provider = self._load_record(
                PhysicalRecordKindV4.PROVIDER_MESSAGE_DISPOSITION,
                bytes(row[4]).hex(),
            )
            assert isinstance(message, PhysicalMessageV4)
            assert isinstance(segment, CaptureSegmentV3)
            assert isinstance(provider, ProviderMessageDispositionV3)
            envelopes = tuple(
                envelope
                for envelope in segment.envelopes
                if envelope.message_receipt_id == message.message_receipt_id
            )
            if len(envelopes) != 1:
                raise PhysicalProjectionV4ConflictError(
                    "ACK message does not resolve exactly one captured envelope"
                )
            envelope = envelopes[0]
            if not _is_exact_text_provider_message(envelope):
                raise PhysicalProjectionV4ConflictError(
                    "captured ACK must be an exact TEXT provider frame"
                )
            raw_ack = strict_json_loads(envelope.raw_payload)
            if not isinstance(raw_ack, Mapping) or set(raw_ack) != {
                "conn_id",
                "op",
                "req_id",
                "ret_msg",
                "success",
            }:
                raise PhysicalProjectionV4ConflictError(
                    "captured ACK does not have the exact bindable schema"
                )
            if (
                raw_ack.get("success") is not True
                or raw_ack.get("op") != "subscribe"
                or raw_ack.get("ret_msg") != ""
                or not isinstance(raw_ack.get("req_id"), str)
                or not raw_ack["req_id"]
                or raw_ack["req_id"] != intent.request_id
                or not isinstance(raw_ack.get("conn_id"), str)
                or not raw_ack["conn_id"]
            ):
                raise PhysicalProjectionV4ConflictError(
                    "captured ACK does not exactly echo its intent or identify a "
                    "nonempty provider connection"
                )
            prior_provider_connections = {
                str(value)
                for (value,) in self._connection.execute(
                    """
                    SELECT provider_connection_id
                    FROM subscription_ack_bindings
                    WHERE transport_session_id = ?
                    """,
                    (
                        _blob_hash(
                            session.transport_session_id,
                            field="transport_session_id",
                        ),
                    ),
                )
            }
            if prior_provider_connections and prior_provider_connections != {
                str(raw_ack["conn_id"])
            }:
                raise PhysicalProjectionV4ConflictError(
                    "provider connection identity changed within one local session"
                )
            if (
                disposition.disposition_kind
                is not MessageDispositionKind.CONTROL_SUBSCRIPTION_ACK
                or provider.disposition_kind
                is not MessageDispositionKind.CONTROL_SUBSCRIPTION_ACK
                or disposition.physical_message_id != message.physical_message_id
                or disposition.capture_segment_id != segment.capture_segment_id
                or disposition.message_receipt_id != message.message_receipt_id
                or disposition.raw_payload_sha256 != envelope.raw_payload_sha256
                or message.physical_scope_manifest_id
                != intent.physical_scope_manifest_id
                or message.adapter_policy_id != intent.adapter_policy_id
                or provider.adapter_policy_id != message.adapter_policy_id
                or provider.capture_segment_id != segment.capture_segment_id
                or provider.message_receipt_id != message.message_receipt_id
                or provider.raw_payload_sha256 != envelope.raw_payload_sha256
                or disposition.physical_scope_manifest_id
                != intent.physical_scope_manifest_id
                or disposition.adapter_policy_id != intent.adapter_policy_id
                or message.capture_segment_id != segment.capture_segment_id
                or message.message_receipt_id != envelope.message_receipt_id
                or message.raw_payload_sha256 != envelope.raw_payload_sha256
                or provider.raw_payload_sha256 != envelope.raw_payload_sha256
                or segment.adapter_policy_id != intent.adapter_policy_id
                or segment.capture_partition_id != intent.capture_partition_id
                or segment.connection_generation != intent.connection_generation
                or segment.connection_id != intent.transport_session_id
                or segment.subscription_manifest_hash
                != intent.subscription_manifest_hash
            ):
                raise PhysicalProjectionV4ConflictError(
                    "ACK capture/classifier chain differs from its transport intent"
                )
            chronology = tuple(
                self._source_metadata(identity)[0]
                for identity in (
                    policy.transport_subscription_policy_id,
                    session.transport_session_id,
                    intent.outbound_subscription_intent_id,
                    segment.capture_segment_id,
                    message.physical_message_id,
                    provider.provider_message_disposition_id,
                    disposition.message_disposition_id,
                )
            )
            if chronology != tuple(sorted(chronology)) or len(set(chronology)) != len(
                chronology
            ):
                raise PhysicalProjectionV4ConflictError(
                    "ACK authority records are not in strict causal receipt order"
                )
            if not (
                intent.authorized_at <= dispatch_started <= dispatch_completed
                and dispatch_started <= intent.send_not_after
                and dispatch_completed
                < envelope.collector_received_wall_ts
                <= intent.ack_not_after
                and started_monotonic >= session.handshake_completed_monotonic_ns
                and started_monotonic
                <= completed_monotonic
                < envelope.collector_received_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "dispatch or ACK falls outside its signed causal deadlines"
                )
            bound_at = self._now()
            if bound_at < envelope.collector_received_wall_ts:
                raise PhysicalProjectionV4ConflictError(
                    "projection binding clock predates the captured ACK"
                )
            binding = SubscriptionAckBindingV4.create_signed(
                signer=signer,
                transport_subscription_policy_id=(
                    policy.transport_subscription_policy_id
                ),
                transport_session_id=session.transport_session_id,
                outbound_subscription_intent_id=(
                    intent.outbound_subscription_intent_id
                ),
                physical_scope_manifest_id=scope.physical_scope_manifest_id,
                adapter_policy_id=adapter.adapter_policy_id,
                capture_partition_id=session.capture_partition_id,
                connection_generation=session.connection_generation,
                capture_segment_id=segment.capture_segment_id,
                physical_message_id=message.physical_message_id,
                message_receipt_id=message.message_receipt_id,
                scope_message_sequence=message.scope_message_sequence,
                provider_message_disposition_id=(
                    provider.provider_message_disposition_id
                ),
                message_disposition_id=disposition.message_disposition_id,
                raw_ack_sha256=envelope.raw_payload_sha256,
                echoed_request_id=str(raw_ack["req_id"]),
                provider_connection_id=str(raw_ack["conn_id"]),
                request_command_sha256=intent.command_sha256,
                dispatch_started_at=dispatch_started,
                dispatch_completed_at=dispatch_completed,
                dispatch_started_monotonic_ns=started_monotonic,
                dispatch_completed_monotonic_ns=completed_monotonic,
                ack_received_at=envelope.collector_received_wall_ts,
                ack_received_monotonic_ns=(envelope.collector_received_monotonic_ns),
                bound_at=bound_at,
            )
            if (
                binding.collector_attestation_key_id
                != policy.collector_attestation_key_id
                or binding.collector_attestation_public_key_hex
                != policy.collector_attestation_public_key_hex
                or binding.collector_attestation_key_id
                != session.collector_attestation_key_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "ACK dispatch signer differs from the registered session key"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(binding)
            self._connection.execute(
                """
                INSERT INTO subscription_ack_bindings(
                    subscription_ack_binding_id,
                    transport_subscription_policy_id, transport_session_id,
                    outbound_subscription_intent_id,
                    physical_scope_manifest_id, adapter_policy_id,
                    capture_partition_id, connection_generation,
                    capture_segment_id, physical_message_id,
                    message_receipt_id, scope_message_sequence,
                    provider_message_disposition_id, message_disposition_id,
                    raw_ack_sha256, echoed_request_id,
                    provider_connection_id, request_command_sha256,
                    dispatch_started_at_us, dispatch_completed_at_us,
                    dispatch_started_monotonic_ns,
                    dispatch_completed_monotonic_ns, ack_received_at_us,
                    ack_received_monotonic_ns, bound_at_us,
                    collector_attestation_key_id,
                    collector_attestation_public_key,
                    dispatch_attestation_signature,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        binding.subscription_ack_binding_id,
                        field="subscription_ack_binding_id",
                    ),
                    _blob_hash(
                        binding.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        binding.transport_session_id,
                        field="transport_session_id",
                    ),
                    _blob_hash(
                        binding.outbound_subscription_intent_id,
                        field="outbound_subscription_intent_id",
                    ),
                    _blob_hash(
                        binding.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(binding.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        binding.capture_partition_id, field="capture_partition_id"
                    ),
                    binding.connection_generation,
                    _blob_hash(binding.capture_segment_id, field="capture_segment_id"),
                    _blob_hash(
                        binding.physical_message_id, field="physical_message_id"
                    ),
                    _blob_hash(binding.message_receipt_id, field="message_receipt_id"),
                    binding.scope_message_sequence,
                    _blob_hash(
                        binding.provider_message_disposition_id,
                        field="provider_message_disposition_id",
                    ),
                    _blob_hash(
                        binding.message_disposition_id,
                        field="message_disposition_id",
                    ),
                    _blob_hash(binding.raw_ack_sha256, field="raw_ack_sha256"),
                    binding.echoed_request_id,
                    binding.provider_connection_id,
                    _blob_hash(
                        binding.request_command_sha256,
                        field="request_command_sha256",
                    ),
                    _timestamp_us(
                        binding.dispatch_started_at, field="dispatch_started_at"
                    ),
                    _timestamp_us(
                        binding.dispatch_completed_at,
                        field="dispatch_completed_at",
                    ),
                    binding.dispatch_started_monotonic_ns,
                    binding.dispatch_completed_monotonic_ns,
                    _timestamp_us(binding.ack_received_at, field="ack_received_at"),
                    binding.ack_received_monotonic_ns,
                    _timestamp_us(binding.bound_at, field="bound_at"),
                    _blob_hash(
                        binding.collector_attestation_key_id,
                        field="collector_attestation_key_id",
                    ),
                    bytes.fromhex(binding.collector_attestation_public_key_hex),
                    bytes.fromhex(binding.dispatch_attestation_signature_hex),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_subscription_ack_binding_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "subscription_ack_binding_id": (binding.subscription_ack_binding_id)
                },
            )
            return binding

    def append_transport_session_termination(
        self,
        *,
        transport_session_id: str,
        reason: Any,
        detected_at: datetime | str,
        detected_monotonic_ns: int,
        detected_monotonic_clock_domain_id: str,
        signer: Any,
        idempotency_key: str,
        close_code: int | None = None,
        close_reason_digest: str | None = None,
    ) -> TransportSessionTerminationV4:
        """Construct and append the sole signed terminal event for a session."""

        session_id = canonical_hash(transport_session_id, field="transport_session_id")
        detected = utc_datetime(detected_at, field="detected_at")
        detected_monotonic = canonical_safe_int(
            detected_monotonic_ns, field="detected_monotonic_ns", minimum=0
        )
        detected_monotonic_domain = canonical_hash(
            detected_monotonic_clock_domain_id,
            field="detected_monotonic_clock_domain_id",
        )
        normalized_close_digest = (
            None
            if close_reason_digest is None
            else canonical_hash(close_reason_digest, field="close_reason_digest")
        )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        reason_value = reason.value if isinstance(reason, Enum) else str(reason)
        operation = "APPEND_TRANSPORT_SESSION_TERMINATION_V4_5"
        request_payload = {
            "close_code": close_code,
            "close_reason_digest": normalized_close_digest,
            "detected_at": utc_iso(detected),
            "detected_monotonic_ns": detected_monotonic,
            "detected_monotonic_clock_domain_id": detected_monotonic_domain,
            "reason": reason_value,
            "transport_session_id": session_id,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            if (
                not self._v49e_composite_transaction_active
                and self._connection.execute(
                    """
                    SELECT 1 FROM transport_actor_events_v49c
                    WHERE transport_session_id = ? LIMIT 1
                    """,
                    (_blob_hash(session_id, field="transport_session_id"),),
                ).fetchone()
                is not None
            ):
                raise PhysicalProjectionV4ConflictError(
                    "actor-owned sessions require atomic V4.9E terminal convergence"
                )
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_SESSION_TERMINATION,
                    str(replay["transport_session_termination_id"]),
                )
                assert isinstance(loaded, TransportSessionTerminationV4)
                return loaded
            session = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION, session_id
            )
            policy = self._load_record(
                PhysicalRecordKindV4.TRANSPORT_SUBSCRIPTION_POLICY,
                session.transport_subscription_policy_id,
            )
            assert isinstance(session, TransportSessionAttestationV4)
            assert isinstance(policy, TransportSubscriptionPolicyV4)
            same_monotonic_domain = (
                detected_monotonic_domain == session.monotonic_clock_domain_id
            )
            if detected < session.handshake_completed_at or (
                same_monotonic_domain
                and detected_monotonic <= session.handshake_completed_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "transport termination predates its completed handshake"
                )
            if (
                not same_monotonic_domain
                and reason_value
                != TransportSessionTerminationReasonV4.PROCESS_RESTART.value
            ):
                raise PhysicalProjectionV4ConflictError(
                    "cross-domain transport termination requires PROCESS_RESTART"
                )
            recorded_at = self._now()
            if recorded_at < detected:
                raise PhysicalProjectionV4ConflictError(
                    "projection termination clock predates detection"
                )
            latest_dispatch = self._connection.execute(
                """
                SELECT dispatch_outcome_at_us, dispatch_outcome_monotonic_ns,
                       monotonic_clock_domain_id
                FROM outbound_control_dispatch_results
                WHERE transport_session_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (_blob_hash(session_id, field="transport_session_id"),),
            ).fetchone()
            if latest_dispatch is not None and (
                _timestamp_us(detected, field="detected_at") <= int(latest_dispatch[0])
                or (
                    bytes(latest_dispatch[2]).hex() == detected_monotonic_domain
                    and detected_monotonic <= int(latest_dispatch[1])
                )
            ):
                raise PhysicalProjectionV4ConflictError(
                    "transport termination detection does not follow the last "
                    "durable control dispatch outcome"
                )
            termination = TransportSessionTerminationV4.create_signed(
                signer=signer,
                transport_subscription_policy_id=(
                    session.transport_subscription_policy_id
                ),
                transport_session_id=session.transport_session_id,
                physical_scope_manifest_id=session.physical_scope_manifest_id,
                capture_partition_id=session.capture_partition_id,
                connection_generation=session.connection_generation,
                reason=reason,
                close_code=close_code,
                close_reason_digest=normalized_close_digest,
                detected_at=detected,
                detected_monotonic_ns=detected_monotonic,
                detected_monotonic_clock_domain_id=detected_monotonic_domain,
                recorded_at=recorded_at,
            )
            if (
                termination.collector_attestation_key_id
                != policy.collector_attestation_key_id
                or termination.collector_attestation_public_key_hex
                != policy.collector_attestation_public_key_hex
                or termination.collector_attestation_key_id
                != session.collector_attestation_key_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "transport termination signer differs from the session key"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(termination)
            self._connection.execute(
                """
                INSERT INTO transport_session_terminations(
                    transport_session_termination_id,
                    transport_subscription_policy_id, transport_session_id,
                    physical_scope_manifest_id, capture_partition_id,
                    connection_generation, reason, close_code,
                    close_reason_digest, detected_at_us,
                    detected_monotonic_ns,
                    detected_monotonic_clock_domain_id, recorded_at_us,
                    collector_attestation_key_id,
                    collector_attestation_public_key, signature,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        termination.transport_session_termination_id,
                        field="transport_session_termination_id",
                    ),
                    _blob_hash(
                        termination.transport_subscription_policy_id,
                        field="transport_subscription_policy_id",
                    ),
                    _blob_hash(
                        termination.transport_session_id,
                        field="transport_session_id",
                    ),
                    _blob_hash(
                        termination.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(
                        termination.capture_partition_id,
                        field="capture_partition_id",
                    ),
                    termination.connection_generation,
                    termination.reason.value,
                    termination.close_code,
                    None
                    if termination.close_reason_digest is None
                    else _blob_hash(
                        termination.close_reason_digest,
                        field="close_reason_digest",
                    ),
                    _timestamp_us(termination.detected_at, field="detected_at"),
                    termination.detected_monotonic_ns,
                    _blob_hash(
                        termination.detected_monotonic_clock_domain_id,
                        field="detected_monotonic_clock_domain_id",
                    ),
                    _timestamp_us(termination.recorded_at, field="recorded_at"),
                    _blob_hash(
                        termination.collector_attestation_key_id,
                        field="collector_attestation_key_id",
                    ),
                    bytes.fromhex(termination.collector_attestation_public_key_hex),
                    bytes.fromhex(termination.signature_hex),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_transport_session_termination_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "transport_session_termination_id": (
                        termination.transport_session_termination_id
                    )
                },
            )
            return termination

    @staticmethod
    def _actor_recovery_payload_v49e(
        state: TerminalStateV49C,
        *,
        kind: TerminalTransitionKindV49C,
        obligation_layer: OutboundObligationLayerV49C | None = None,
        obligation_id: str | None = None,
        send_attempt_id: str | None = None,
        cause_code: str | None = None,
    ) -> TerminalTransitionPayloadV49C:
        return TerminalTransitionPayloadV49C(
            transport_session_id=state.transport_session_id,
            transition_sequence=state.transition_sequence + 1,
            parent_terminal_state_id=state.terminal_state_id,
            kind=kind,
            obligation_layer=obligation_layer,
            obligation_id=obligation_id,
            send_attempt_id=send_attempt_id,
            cause_code=cause_code,
        )

    @staticmethod
    def _actor_recovery_event_v49e(
        chain: Sequence[TransportActorEventV49C],
        *,
        event_kind: TransportActorEventKindV49C,
        payload: Any,
        detected_at: datetime,
        detected_monotonic_ns: int,
        detected_monotonic_clock_domain_id: str,
    ) -> TransportActorEventV49C:
        """Build one deterministic, effect-free successor to a durable prefix.

        A host restart can change the monotonic clock domain, while an actor
        chain is permanently bound to its admitted session domain.  In that
        case the successor uses the smallest advancing actor-order value; the
        signed bridge remains explicitly a PROCESS_RESTART rather than
        pretending that the new boot's monotonic sample belongs to the old
        domain.
        """

        if not chain:
            raise PhysicalProjectionV4ConflictError(
                "actor recovery requires a non-empty durable prefix"
            )
        tail = chain[-1]
        if detected_at < tail.recorded_at:
            raise PhysicalProjectionV4ConflictError(
                "process-restart detection predates the actor chain tail"
            )
        recorded_monotonic_ns = tail.recorded_monotonic_ns + 1
        if detected_monotonic_clock_domain_id == tail.monotonic_clock_domain_id:
            recorded_monotonic_ns = max(
                recorded_monotonic_ns,
                detected_monotonic_ns,
            )
        return TransportActorEventV49C.create(
            transport_subscription_policy_id=(tail.transport_subscription_policy_id),
            transport_session_id=tail.transport_session_id,
            physical_scope_manifest_id=tail.physical_scope_manifest_id,
            adapter_policy_id=tail.adapter_policy_id,
            capture_partition_id=tail.capture_partition_id,
            socket_lease_id=tail.socket_lease_id,
            connection_generation=tail.connection_generation,
            deployment_bundle_id=tail.deployment_bundle_id,
            writer_fence_token_sha256=tail.writer_fence_token_sha256,
            writer_fence_generation=tail.writer_fence_generation,
            monotonic_clock_domain_id=tail.monotonic_clock_domain_id,
            driver_policy_id=tail.driver_policy_id,
            recorded_at=detected_at,
            recorded_monotonic_ns=recorded_monotonic_ns,
            actor_sequence=tail.actor_sequence + 1,
            previous_event_id=tail.transport_actor_event_id,
            event_kind=event_kind,
            payload=payload,
        )

    @staticmethod
    def _actor_recovery_key_v49e(
        *,
        prefix: str,
        session_id: str,
        action: str,
        event_id: str,
    ) -> str:
        # Keep the public 128-character prefix while remaining below the
        # projection's 256-character operation-key ceiling.
        return f"{prefix}-{session_id[:24]}-{action}-{event_id[:24]}"

    def _reconcile_actor_process_restart_v49e(
        self,
        *,
        transport_session_id: str,
        detected_at: datetime,
        detected_monotonic_ns: int,
        detected_monotonic_clock_domain_id: str,
        signer: Any,
        idempotency_prefix: str,
    ) -> TransportSessionTerminationV4:
        """Recover one actor prefix without repeating TLS or socket effects."""

        for _ in range(32):
            chain = self._load_transport_actor_chain_v49c(transport_session_id)
            state = self._actor_terminal_state_v49e(chain)
            if state.is_terminal:
                raise PhysicalProjectionV4VerificationError(
                    "final actor session lacks its exact paired legacy termination"
                )
            tail = chain[-1]
            payload = tail.payload
            terminal_kind: TerminalTransitionKindV49C | None = None
            terminal_cause: str | None = None

            def event_for(
                event_kind: TransportActorEventKindV49C,
                next_payload: Any,
                current_chain: Sequence[TransportActorEventV49C] = chain,
            ) -> TransportActorEventV49C:
                return self._actor_recovery_event_v49e(
                    current_chain,
                    event_kind=event_kind,
                    payload=next_payload,
                    detected_at=detected_at,
                    detected_monotonic_ns=detected_monotonic_ns,
                    detected_monotonic_clock_domain_id=(
                        detected_monotonic_clock_domain_id
                    ),
                )

            def append_recovery_event(
                candidate: TransportActorEventV49C,
                *,
                action: str,
            ) -> None:
                self._append_transport_actor_event_core_v49c(
                    candidate,
                    idempotency_key=self._actor_recovery_key_v49e(
                        prefix=idempotency_prefix,
                        session_id=transport_session_id,
                        action=action,
                        event_id=candidate.transport_actor_event_id,
                    ),
                )

            events_by_id = {event.transport_actor_event_id: event for event in chain}

            # Marker repair is pure bookkeeping over already durable evidence.
            # Preserve actor order when both a peer and local Close marker were
            # interrupted; never reconstruct or transmit protocol bytes here.
            close_parser_events = tuple(
                event
                for event in chain
                if event.event_kind is TransportActorEventKindV49C.PARSER_TRANSITION
                and type(event.payload) is ParserTransitionPayloadV49C
                and event.payload.frame is not None
                and event.payload.frame.opcode is WebSocketOpcodeV49C.CLOSE
            )
            received_marker_count = sum(
                1
                for event in chain
                if event.event_kind is TransportActorEventKindV49C.TERMINAL_TRANSITION
                and type(event.payload) is TerminalTransitionPayloadV49C
                and event.payload.kind is TerminalTransitionKindV49C.WS_CLOSE_RECEIVED
            )
            marked_close_wires = {
                event.payload.obligation_id
                for event in chain
                if event.event_kind is TransportActorEventKindV49C.TERMINAL_TRANSITION
                and type(event.payload) is TerminalTransitionPayloadV49C
                and event.payload.kind is TerminalTransitionKindV49C.WS_CLOSE_SENT
            }
            missing_markers: list[
                tuple[
                    int,
                    TerminalTransitionKindV49C,
                    OutboundObligationLayerV49C | None,
                    str | None,
                ]
            ] = []
            if received_marker_count < len(close_parser_events):
                source = close_parser_events[received_marker_count]
                missing_markers.append(
                    (
                        source.actor_sequence,
                        TerminalTransitionKindV49C.WS_CLOSE_RECEIVED,
                        None,
                        None,
                    )
                )
            for event in chain:
                wire = event.payload
                if (
                    event.event_kind
                    is TransportActorEventKindV49C.OUTBOUND_WIRE_PREPARED
                    and type(wire) is OutboundWirePreparedPayloadV49C
                    and wire.logical_opcode is WebSocketOpcodeV49C.CLOSE
                    and wire.outbound_operation_id not in marked_close_wires
                ):
                    missing_markers.append(
                        (
                            event.actor_sequence,
                            TerminalTransitionKindV49C.WS_CLOSE_SENT,
                            OutboundObligationLayerV49C.WEBSOCKET_CLOSE,
                            wire.outbound_operation_id,
                        )
                    )
            if missing_markers:
                _, marker_kind, layer, obligation_id = min(missing_markers)
                marker_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=marker_kind,
                        obligation_layer=layer,
                        obligation_id=obligation_id,
                    ),
                )
                append_recovery_event(marker_event, action="websocket-marker")
                continue

            if type(payload) is KernelSendAttemptPayloadV49C:
                tls_event = events_by_id.get(payload.tls_ciphertext_prepared_event_id)
                tls = None if tls_event is None else tls_event.payload
                wire_event = (
                    None
                    if type(tls) is not TlsCiphertextPreparedPayloadV49C
                    else events_by_id.get(tls.outbound_wire_prepared_event_id)
                )
                wire = None if wire_event is None else wire_event.payload
                if type(wire) is not OutboundWirePreparedPayloadV49C:
                    raise PhysicalProjectionV4VerificationError(
                        "kernel attempt recovery lacks its exact wire obligation"
                    )
                obligation_id = wire.outbound_operation_id
                if (
                    state.tls_close_notify_sent
                    and not state.tls_close_notify_fully_kernel_accepted
                    and state.tls_close_notify_obligation_id == obligation_id
                ):
                    layer = OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY
                elif (
                    state.ws_close_sent
                    and not state.ws_output_fully_kernel_accepted
                    and state.ws_output_obligation_id == obligation_id
                ):
                    layer = OutboundObligationLayerV49C.WEBSOCKET_CLOSE
                elif wire.logical_opcode is not WebSocketOpcodeV49C.CLOSE:
                    layer = OutboundObligationLayerV49C.APPLICATION_DATA
                else:
                    raise PhysicalProjectionV4VerificationError(
                        "Close kernel attempt lacks its durable WS_CLOSE_SENT marker"
                    )
                started_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=TerminalTransitionKindV49C.SEND_ATTEMPT_STARTED,
                        obligation_layer=layer,
                        obligation_id=obligation_id,
                        send_attempt_id=tail.transport_actor_event_id,
                    ),
                )
                append_recovery_event(started_event, action="send-started-marker")
                continue

            if type(payload) is TlsControlKernelSendAttemptPayloadV49E:
                control_event = events_by_id.get(
                    payload.tls_control_ciphertext_prepared_event_id
                )
                control = None if control_event is None else control_event.payload
                if type(control) is not TlsControlCiphertextPreparedPayloadV49E:
                    raise PhysicalProjectionV4VerificationError(
                        "TLS-control attempt recovery lacks its exact artifact"
                    )
                layer = (
                    OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY
                    if control.control_kind
                    is TlsControlOutputKindV49E.LOCAL_CLOSE_NOTIFY
                    else OutboundObligationLayerV49C.TLS_OPAQUE_CONTROL
                )
                started_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=TerminalTransitionKindV49C.SEND_ATTEMPT_STARTED,
                        obligation_layer=layer,
                        obligation_id=control_event.transport_actor_event_id,
                        send_attempt_id=tail.transport_actor_event_id,
                    ),
                )
                append_recovery_event(
                    started_event,
                    action="tls-control-send-started-marker",
                )
                continue

            if state.has_pending_send_attempt:
                attempt_id = state.pending_send_attempt_id
                layer = state.pending_send_obligation_layer
                obligation_id = state.pending_send_obligation_id
                if attempt_id is None or layer is None or obligation_id is None:
                    raise PhysicalProjectionV4VerificationError(
                        "pending actor send lacks its exact terminal identities"
                    )
                attempt_event = events_by_id.get(attempt_id)
                if attempt_event is None or type(attempt_event.payload) not in {
                    KernelSendAttemptPayloadV49C,
                    TlsControlKernelSendAttemptPayloadV49E,
                }:
                    raise PhysicalProjectionV4VerificationError(
                        "pending actor send lacks its exact durable attempt"
                    )
                generic_result = next(
                    (
                        event
                        for event in reversed(chain)
                        if type(event.payload) is KernelSendResultPayloadV49C
                        and event.payload.kernel_send_attempt_event_id == attempt_id
                    ),
                    None,
                )
                tls_control_result = next(
                    (
                        event
                        for event in reversed(chain)
                        if type(event.payload) is TlsControlKernelSendResultPayloadV49E
                        and event.payload.tls_control_kernel_send_attempt_event_id
                        == attempt_id
                    ),
                    None,
                )
                generic_failure = next(
                    (
                        event
                        for event in reversed(chain)
                        if type(event.payload) is KernelSendFailurePayloadV49E
                        and event.payload.kernel_send_attempt_event_id == attempt_id
                    ),
                    None,
                )
                tls_control_failure = next(
                    (
                        event
                        for event in reversed(chain)
                        if type(event.payload) is TlsControlKernelSendFailurePayloadV49E
                        and event.payload.tls_control_kernel_send_attempt_event_id
                        == attempt_id
                    ),
                    None,
                )
                conclusive_outcome = (
                    generic_result
                    or tls_control_result
                    or generic_failure
                    or tls_control_failure
                )
                if conclusive_outcome is not None:
                    resolved_event = event_for(
                        TransportActorEventKindV49C.TERMINAL_TRANSITION,
                        self._actor_recovery_payload_v49e(
                            state,
                            kind=TerminalTransitionKindV49C.SEND_ATTEMPT_RESOLVED,
                            obligation_layer=layer,
                            obligation_id=obligation_id,
                            send_attempt_id=attempt_id,
                        ),
                    )
                    append_recovery_event(
                        resolved_event,
                        action="send-resolved-marker",
                    )
                    continue
                unknown_cause = (
                    V49E_TLS_CONTROL_SEND_OUTCOME_UNKNOWN_CAUSE
                    if type(attempt_event.payload)
                    is TlsControlKernelSendAttemptPayloadV49E
                    else V49C_RECOVERY_UNKNOWN_SEND_CAUSE
                )
                unknown_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=TerminalTransitionKindV49C.UNKNOWN_SEND,
                        obligation_layer=layer,
                        obligation_id=obligation_id,
                        send_attempt_id=attempt_id,
                        cause_code=unknown_cause,
                    ),
                )
                result = self._converge_actor_terminal_core_v49e(
                    unknown_event,
                    signer=signer,
                    idempotency_key=self._actor_recovery_key_v49e(
                        prefix=idempotency_prefix,
                        session_id=transport_session_id,
                        action="unknown-send",
                        event_id=unknown_event.transport_actor_event_id,
                    ),
                )
                return result.termination

            if (
                type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.SEND_ATTEMPT_RESOLVED
            ):
                generic_failure_event = next(
                    (
                        event
                        for event in reversed(chain[:-1])
                        if type(event.payload) is KernelSendFailurePayloadV49E
                        and event.payload.kernel_send_attempt_event_id
                        == payload.send_attempt_id
                    ),
                    None,
                )
                tls_failure_event = next(
                    (
                        event
                        for event in reversed(chain[:-1])
                        if type(event.payload) is TlsControlKernelSendFailurePayloadV49E
                        and event.payload.tls_control_kernel_send_attempt_event_id
                        == payload.send_attempt_id
                    ),
                    None,
                )
                failure_event = generic_failure_event or tls_failure_event
                if failure_event is not None:
                    failure = failure_event.payload
                    assert type(failure) in {
                        KernelSendFailurePayloadV49E,
                        TlsControlKernelSendFailurePayloadV49E,
                    }
                    clock_disagreement = (
                        failure.failure_kind
                        is KernelSendFailureKindV49E.CLOCK_DISAGREEMENT
                    )
                    failure_cause = (
                        V49E_LOCAL_SHUTDOWN_CLOCK_DISAGREEMENT_CAUSE
                        if clock_disagreement
                        else (
                            V49E_LOCAL_SHUTDOWN_COMMAND_DEADLINE_EXPIRED_CAUSE
                            if failure.local_shutdown_command_started_event_id
                            is not None
                            else V49E_WEBSOCKET_CLOSE_DEADLINE_EXPIRED_CAUSE
                        )
                    )
                    terminal_event = event_for(
                        TransportActorEventKindV49C.TERMINAL_TRANSITION,
                        self._actor_recovery_payload_v49e(
                            state,
                            kind=(
                                TerminalTransitionKindV49C.FATAL
                                if clock_disagreement
                                else TerminalTransitionKindV49C.TIMEOUT
                            ),
                            cause_code=failure_cause,
                        ),
                    )
                    result = self._converge_actor_terminal_core_v49e(
                        terminal_event,
                        signer=signer,
                        idempotency_key=self._actor_recovery_key_v49e(
                            prefix=idempotency_prefix,
                            session_id=transport_session_id,
                            action="send-failure-terminal",
                            event_id=terminal_event.transport_actor_event_id,
                        ),
                    )
                    return result.termination

            if (
                type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.SEND_ATTEMPT_RESOLVED
                and payload.obligation_layer
                in {
                    OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY,
                    OutboundObligationLayerV49C.TLS_OPAQUE_CONTROL,
                }
            ):
                result_event = next(
                    (
                        event
                        for event in reversed(chain[:-1])
                        if type(event.payload) is TlsControlKernelSendResultPayloadV49E
                        and event.payload.tls_control_kernel_send_attempt_event_id
                        == payload.send_attempt_id
                    ),
                    None,
                )
                if result_event is None:
                    raise PhysicalProjectionV4VerificationError(
                        "TLS-control resolution marker lacks its exact result"
                    )
                result_payload = result_event.payload
                assert type(result_payload) is TlsControlKernelSendResultPayloadV49E
                control_event = events_by_id.get(
                    result_payload.tls_control_ciphertext_prepared_event_id
                )
                control = None if control_event is None else control_event.payload
                if type(control) is not TlsControlCiphertextPreparedPayloadV49E:
                    raise PhysicalProjectionV4VerificationError(
                        "TLS-control result recovery lacks its exact artifact"
                    )
                if (
                    result_payload.resulting_ciphertext_offset
                    == control.ciphertext_octets
                    and control.control_kind
                    is TlsControlOutputKindV49E.LOCAL_CLOSE_NOTIFY
                ):
                    sent_event = event_for(
                        TransportActorEventKindV49C.TERMINAL_TRANSITION,
                        self._actor_recovery_payload_v49e(
                            state,
                            kind=TerminalTransitionKindV49C.TLS_CLOSE_NOTIFY_SENT,
                            obligation_layer=(
                                OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY
                            ),
                            obligation_id=control_event.transport_actor_event_id,
                        ),
                    )
                    append_recovery_event(sent_event, action="tls-sent-marker")
                    continue
                if (
                    result_payload.resulting_ciphertext_offset
                    < control.ciphertext_octets
                ):
                    terminal_kind = TerminalTransitionKindV49C.FATAL
                    terminal_cause = V49E_TLS_OPERATION_DRIVER_ERROR_CAUSE
                else:
                    terminal_kind = None
                    terminal_cause = None
            if (
                type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.TLS_CLOSE_NOTIFY_SENT
            ):
                accepted_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=(
                            TerminalTransitionKindV49C.OUTBOUND_OBLIGATION_FULLY_KERNEL_ACCEPTED
                        ),
                        obligation_layer=OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY,
                        obligation_id=payload.obligation_id,
                    ),
                )
                append_recovery_event(accepted_event, action="tls-accepted-marker")
                continue

            if type(payload) is TlsShutdownObservedPayloadV49E:
                marker_kind = (
                    TerminalTransitionKindV49C.TLS_CLOSE_NOTIFY_RECEIVED
                    if payload.observation_kind
                    is TlsShutdownObservationKindV49E.PEER_CLOSE_NOTIFY
                    else TerminalTransitionKindV49C.TCP_EOF_RECEIVED
                )
                marker_payload = self._actor_recovery_payload_v49e(
                    state,
                    kind=marker_kind,
                )
                marker_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    marker_payload,
                )
                prospective = advance_terminal_state_v49c(state, marker_payload)
                if prospective.is_terminal:
                    result = self._converge_actor_terminal_core_v49e(
                        marker_event,
                        signer=signer,
                        idempotency_key=self._actor_recovery_key_v49e(
                            prefix=idempotency_prefix,
                            session_id=transport_session_id,
                            action="shutdown-observation-marker",
                            event_id=marker_event.transport_actor_event_id,
                        ),
                    )
                    return result.termination
                append_recovery_event(
                    marker_event,
                    action="shutdown-observation-marker",
                )
                continue

            if (
                type(payload) is TcpHalfCloseResultPayloadV49E
                and payload.result_kind is TcpHalfCloseResultKindV49E.KERNEL_ACCEPTED
            ):
                fin_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=TerminalTransitionKindV49C.TCP_FIN_SENT,
                    ),
                )
                append_recovery_event(fin_event, action="tcp-fin-marker")
                continue

            if type(payload) is OutboundDispatchCompletedPayloadV49C:
                wire_event = events_by_id.get(payload.outbound_wire_prepared_event_id)
                wire = None if wire_event is None else wire_event.payload
                if (
                    type(wire) is OutboundWirePreparedPayloadV49C
                    and wire.logical_opcode is WebSocketOpcodeV49C.CLOSE
                ):
                    accepted_event = event_for(
                        TransportActorEventKindV49C.TERMINAL_TRANSITION,
                        self._actor_recovery_payload_v49e(
                            state,
                            kind=(
                                TerminalTransitionKindV49C.OUTBOUND_OBLIGATION_FULLY_KERNEL_ACCEPTED
                            ),
                            obligation_layer=(
                                OutboundObligationLayerV49C.WEBSOCKET_CLOSE
                            ),
                            obligation_id=wire.outbound_operation_id,
                        ),
                    )
                    append_recovery_event(
                        accepted_event,
                        action="websocket-accepted-marker",
                    )
                    continue

            if type(payload) is TlsControlCiphertextPreparedPayloadV49E:
                if payload.control_kind is TlsControlOutputKindV49E.LOCAL_CLOSE_NOTIFY:
                    prepared_event = event_for(
                        TransportActorEventKindV49C.TERMINAL_TRANSITION,
                        self._actor_recovery_payload_v49e(
                            state,
                            kind=(TerminalTransitionKindV49C.TLS_CLOSE_NOTIFY_PREPARED),
                            obligation_layer=(
                                OutboundObligationLayerV49C.TLS_CLOSE_NOTIFY
                            ),
                            obligation_id=tail.transport_actor_event_id,
                        ),
                    )
                    append_recovery_event(
                        prepared_event,
                        action="tls-prepared-marker",
                    )
                    continue
                terminal_kind = TerminalTransitionKindV49C.FATAL
                terminal_cause = V49E_TLS_OPERATION_DRIVER_ERROR_CAUSE
            elif (
                type(payload) is TerminalTransitionPayloadV49C
                and payload.kind is TerminalTransitionKindV49C.TLS_CLOSE_NOTIFY_PREPARED
            ):
                terminal_kind = TerminalTransitionKindV49C.FATAL
                terminal_cause = V49E_TLS_OPERATION_DRIVER_ERROR_CAUSE

            if type(payload) is LocalShutdownDeadlineEvidencePayloadV49E:
                terminal_kind, terminal_cause = {
                    LocalShutdownDeadlineClassificationV49E.BOTH_DUE: (
                        TerminalTransitionKindV49C.TIMEOUT,
                        V49E_LOCAL_SHUTDOWN_COMMAND_DEADLINE_EXPIRED_CAUSE,
                    ),
                    LocalShutdownDeadlineClassificationV49E.CLOCK_DISAGREEMENT: (
                        TerminalTransitionKindV49C.FATAL,
                        V49E_LOCAL_SHUTDOWN_CLOCK_DISAGREEMENT_CAUSE,
                    ),
                    LocalShutdownDeadlineClassificationV49E.OWNER_EVIDENCE_BEFORE_BOTH_CLOCKS: (
                        TerminalTransitionKindV49C.FATAL,
                        V49E_TLS_OPERATION_DRIVER_ERROR_CAUSE,
                    ),
                }[payload.classification]
            elif type(payload) is TerminalIngressFailurePayloadV49E:
                terminal_kind, terminal_cause = (
                    (
                        TerminalTransitionKindV49C.FATAL,
                        V49E_LOCAL_SHUTDOWN_CLOCK_DISAGREEMENT_CAUSE,
                    )
                    if payload.failure_kind
                    is TerminalIngressFailureKindV49E.CLOCK_DISAGREEMENT
                    else (
                        TerminalTransitionKindV49C.TIMEOUT,
                        V49E_TERMINAL_CLOSE_INGRESS_DEADLINE_EXPIRED_AFTER_PROGRESS_CAUSE,
                    )
                )

            if type(payload) is TlsProtocolOperationStartedPayloadV49E:
                command_event = events_by_id.get(
                    payload.local_shutdown_command_started_event_id
                )
                command = None if command_event is None else command_event.payload
                if type(command) is not LocalShutdownCommandStartedPayloadV49E:
                    raise PhysicalProjectionV4VerificationError(
                        "started TLS recovery lacks its shutdown command"
                    )
                failure_event = event_for(
                    TransportActorEventKindV49C.TLS_PROTOCOL_OPERATION_FAILED,
                    TlsProtocolOperationFailedPayloadV49E(
                        tls_protocol_operation_started_event_id=(
                            tail.transport_actor_event_id
                        ),
                        tls_operation_id=payload.tls_operation_id,
                        purpose=payload.purpose,
                        driver_evidence_nonce_sha256=(
                            payload.driver_evidence_nonce_sha256
                        ),
                        failure_kind=(TlsProtocolOperationFailureKindV49E.DRIVER_ERROR),
                        deadline_classification=None,
                        shutdown_deadline_monotonic_ns=(
                            command.shutdown_deadline_monotonic_ns
                        ),
                        unsendable_driver_output_sequence=None,
                        unsendable_driver_evidence_id=None,
                        unsendable_owner_evidence_id=None,
                        unsendable_kernel_socket_identity=None,
                        unsendable_ciphertext_sha256=None,
                        unsendable_ciphertext_octets=None,
                        deadline_no_observation_owner_evidence_id=None,
                        deadline_no_observation_kernel_socket_identity=None,
                        deadline_no_observation_operation=None,
                        deadline_after_progress_owner_evidence_id=None,
                        deadline_after_progress_driver_evidence_id=None,
                        deadline_after_progress_kernel_socket_identity=None,
                        deadline_after_progress_operation=None,
                        deadline_after_progress_ciphertext_sha256=None,
                        deadline_after_progress_ciphertext_octets=None,
                        observed_at=detected_at,
                        observed_monotonic_ns=max(
                            tail.recorded_monotonic_ns + 1,
                            (
                                detected_monotonic_ns
                                if detected_monotonic_clock_domain_id
                                == tail.monotonic_clock_domain_id
                                else 0
                            ),
                        ),
                    ),
                )
                self._append_transport_actor_event_core_v49c(
                    failure_event,
                    idempotency_key=self._actor_recovery_key_v49e(
                        prefix=idempotency_prefix,
                        session_id=transport_session_id,
                        action="tls-operation-failed",
                        event_id=failure_event.transport_actor_event_id,
                    ),
                )
                continue

            if type(payload) is TlsProtocolOperationFailedPayloadV49E:
                terminal_kind, terminal_cause = (
                    classify_tls_protocol_operation_failure_v49e(payload)
                )
            elif type(payload) is TcpHalfCloseAttemptPayloadV49E:
                terminal_kind = TerminalTransitionKindV49C.FATAL
                terminal_cause = V49E_TCP_HALF_CLOSE_OUTCOME_UNKNOWN_CAUSE
            elif type(
                payload
            ) is TcpHalfCloseResultPayloadV49E and payload.result_kind in {
                TcpHalfCloseResultKindV49E.DEADLINE_EXPIRED_BEFORE_SYSCALL,
                TcpHalfCloseResultKindV49E.CLOCK_DISAGREEMENT,
                TcpHalfCloseResultKindV49E.ERROR,
            }:
                terminal_kind, terminal_cause = {
                    TcpHalfCloseResultKindV49E.DEADLINE_EXPIRED_BEFORE_SYSCALL: (
                        TerminalTransitionKindV49C.TIMEOUT,
                        V49E_TCP_HALF_CLOSE_DEADLINE_EXPIRED_BEFORE_SYSCALL_CAUSE,
                    ),
                    TcpHalfCloseResultKindV49E.CLOCK_DISAGREEMENT: (
                        TerminalTransitionKindV49C.FATAL,
                        V49E_LOCAL_SHUTDOWN_CLOCK_DISAGREEMENT_CAUSE,
                    ),
                    TcpHalfCloseResultKindV49E.ERROR: (
                        TerminalTransitionKindV49C.FATAL,
                        V49E_TCP_HALF_CLOSE_ERROR_CAUSE,
                    ),
                }[payload.result_kind]

            if terminal_kind is not None and terminal_cause is not None:
                terminal_event = event_for(
                    TransportActorEventKindV49C.TERMINAL_TRANSITION,
                    self._actor_recovery_payload_v49e(
                        state,
                        kind=terminal_kind,
                        cause_code=terminal_cause,
                    ),
                )
                result = self._converge_actor_terminal_core_v49e(
                    terminal_event,
                    signer=signer,
                    idempotency_key=self._actor_recovery_key_v49e(
                        prefix=idempotency_prefix,
                        session_id=transport_session_id,
                        action="fixed-terminal",
                        event_id=terminal_event.transport_actor_event_id,
                    ),
                )
                return result.termination

            restart_event = event_for(
                TransportActorEventKindV49C.TERMINAL_TRANSITION,
                self._actor_recovery_payload_v49e(
                    state,
                    kind=TerminalTransitionKindV49C.FATAL,
                    cause_code=_V49E_PROCESS_RESTART_CAUSE,
                ),
            )
            try:
                validate_transport_actor_chain_v49c((*chain, restart_event))
            except CanonicalizationError as exc:
                unresolved = type(payload).__name__
                if state.has_pending_send_attempt:
                    unresolved = "pending kernel-send outcome"
                elif type(payload) is TlsControlKernelSendAttemptPayloadV49E:
                    unresolved = "TLS-control kernel-send attempt"
                raise PhysicalProjectionV4ConflictError(
                    "actor process-restart recovery is quarantined because its "
                    f"exact next successor remains unresolved: {unresolved}"
                ) from exc
            result = self._converge_actor_terminal_core_v49e(
                restart_event,
                signer=signer,
                idempotency_key=self._actor_recovery_key_v49e(
                    prefix=idempotency_prefix,
                    session_id=transport_session_id,
                    action="process-restart",
                    event_id=restart_event.transport_actor_event_id,
                ),
            )
            return result.termination

        raise PhysicalProjectionV4VerificationError(
            "actor process-restart recovery exceeded its bounded pure-local suffix"
        )

    def reconcile_unterminated_transport_sessions(
        self,
        *,
        detected_at: datetime | str,
        detected_monotonic_ns: int,
        detected_monotonic_clock_domain_id: str,
        signer: Any,
        idempotency_prefix: str,
    ) -> tuple[TransportSessionTerminationV4, ...]:
        """Terminate every open session before a new runtime becomes READY.

        The initial snapshot is read before any append.  Each effect-free actor
        marker is committed with a content-derived idempotency key, while the
        decisive actor event and signed legacy bridge share one transaction. A
        crash can therefore leave only a valid strict recovery prefix; the next
        startup reconstructs its exact next step. This method never repeats TLS
        or socket effects, authorizes a successor, synthesizes a positive kernel
        result, or replays an old outbound intent.
        """

        detected = utc_datetime(detected_at, field="detected_at")
        detected_monotonic = canonical_safe_int(
            detected_monotonic_ns, field="detected_monotonic_ns", minimum=0
        )
        detected_domain = canonical_hash(
            detected_monotonic_clock_domain_id,
            field="detected_monotonic_clock_domain_id",
        )
        prefix = canonical_identifier(
            idempotency_prefix, field="idempotency_prefix", maximum=128
        )
        self._validate_runtime()
        # Audit every actor bridge before mutating any legacy session.  A final
        # actor tail without its adjacent signed pair is corruption, not an
        # invitation to append a competing startup termination.
        try:
            self._connection.execute("BEGIN")
            self._verify_projection_bijection()
            self._verify_transport_actor_authority_v49c()
            self._verify_capacity_measurement_lifecycle_v49f()
            self._verify_actor_terminal_bridges_v49e()
            open_session_ids = tuple(
                bytes(row[0]).hex()
                for row in self._connection.execute(
                    """
                    SELECT session.transport_session_id
                    FROM transport_session_attestations AS session
                    LEFT JOIN transport_session_terminations AS terminal
                      ON terminal.transport_session_id = session.transport_session_id
                    WHERE terminal.transport_session_id IS NULL
                    ORDER BY session.source_receipt_sequence
                    """
                )
            )
            self._connection.commit()
        except CanonicalizationError as exc:
            self._connection.rollback()
            raise PhysicalProjectionV4VerificationError(
                "transport actor recovery prefix fails canonical replay"
            ) from exc
        except BaseException:
            self._connection.rollback()
            raise
        reconciled: list[TransportSessionTerminationV4] = []
        for session_id in open_session_ids:
            chain = self._load_transport_actor_chain_v49c(session_id)
            if chain:
                reconciled.append(
                    self._reconcile_actor_process_restart_v49e(
                        transport_session_id=session_id,
                        detected_at=detected,
                        detected_monotonic_ns=detected_monotonic,
                        detected_monotonic_clock_domain_id=detected_domain,
                        signer=signer,
                        idempotency_prefix=prefix,
                    )
                )
            else:
                reconciled.append(
                    self.append_transport_session_termination(
                        transport_session_id=session_id,
                        reason=TransportSessionTerminationReasonV4.PROCESS_RESTART,
                        detected_at=detected,
                        detected_monotonic_ns=detected_monotonic,
                        detected_monotonic_clock_domain_id=detected_domain,
                        signer=signer,
                        idempotency_key=f"{prefix}-{session_id}",
                    )
                )
        return tuple(reconciled)

    def _capture_segment_registry(self) -> dict[str, CaptureSegmentV3]:
        registry: dict[str, CaptureSegmentV3] = {}
        for (identity_blob,) in self._connection.execute(
            "SELECT capture_segment_id FROM capture_segments"
        ):
            identity = bytes(identity_blob).hex()
            segment = self._load_record(PhysicalRecordKindV4.CAPTURE_SEGMENT, identity)
            assert isinstance(segment, CaptureSegmentV3)
            registry[identity] = segment
        return registry

    def _validate_capture_segment_admission(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        segment: CaptureSegmentV3,
    ) -> None:
        if segment.adapter_policy_id not in {
            scope.primary_adapter_policy_id,
            scope.required_status_adapter_policy_id,
        }:
            raise PhysicalProjectionV4ConflictError(
                "capture segment adapter policy is outside the physical scope"
            )
        policy = self._registered_adapter_policy(segment.adapter_policy_id)
        if policy is None:
            if scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4:
                raise PhysicalProjectionV4ConflictError(
                    "authoritative capture adapter policy is not registered"
                )
        else:
            if segment.provider_native_key != policy.provider_native_key:
                raise PhysicalProjectionV4ConflictError(
                    "capture segment provider instrument differs from adapter policy"
                )
            if (
                segment.vintage is PhysicalVintage.PROSPECTIVE_LIVE
                and segment.envelopes[0].collector_received_wall_ts < policy.frozen_at
            ):
                raise PhysicalProjectionV4ConflictError(
                    "prospective capture predates its frozen adapter policy"
                )
        authoritative_session: TransportSessionAttestationV4 | None = None
        if (
            scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4
            and segment.adapter_policy_id == scope.primary_adapter_policy_id
            and segment.vintage is PhysicalVintage.PROSPECTIVE_LIVE
        ):
            try:
                transport_session_id = canonical_hash(
                    segment.connection_id, field="connection_id"
                )
            except CanonicalizationError as exc:
                raise PhysicalProjectionV4ConflictError(
                    "prospective primary capture connection is not a local "
                    "transport-session identity"
                ) from exc
            try:
                session = self._load_record(
                    PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION,
                    transport_session_id,
                )
            except PhysicalProjectionV4ConflictError as exc:
                raise PhysicalProjectionV4ConflictError(
                    "prospective primary capture has no attested transport session"
                ) from exc
            assert isinstance(session, TransportSessionAttestationV4)
            if (
                session.physical_scope_manifest_id != scope.physical_scope_manifest_id
                or session.adapter_policy_id != segment.adapter_policy_id
                or session.capture_partition_id != segment.capture_partition_id
                or session.collector_instance_id != segment.collector_instance_id
                or session.collector_boot_id != segment.collector_boot_id
                or session.connection_generation != segment.connection_generation
                or session.transport_session_id != segment.connection_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "prospective primary capture differs from its attested session"
                )
            authoritative_session = session
            self._assert_control_side_effect_open(
                transport_session_id=session.transport_session_id
            )
            if (
                self._connection.execute(
                    "SELECT 1 FROM transport_session_terminations WHERE transport_session_id = ?",
                    (
                        _blob_hash(
                            session.transport_session_id, field="transport_session_id"
                        ),
                    ),
                ).fetchone()
                is not None
            ):
                raise PhysicalProjectionV4ConflictError(
                    "terminated transport session cannot admit later capture"
                )
            intent_row = self._connection.execute(
                """
                SELECT outbound_subscription_intent_id
                FROM outbound_subscription_intents
                WHERE transport_session_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(
                        session.transport_session_id, field="transport_session_id"
                    ),
                ),
            ).fetchone()
            intent = (
                None
                if intent_row is None
                else self._load_record(
                    PhysicalRecordKindV4.OUTBOUND_SUBSCRIPTION_INTENT,
                    bytes(intent_row[0]).hex(),
                )
            )
            if intent is not None and not isinstance(
                intent, OutboundSubscriptionIntentV4
            ):
                raise PhysicalProjectionV4VerificationError(
                    "prospective capture intent has the wrong record type"
                )
            if policy is None:
                raise PhysicalProjectionV4VerificationError(
                    "authoritative prospective capture has no registered adapter policy"
                )
            expected_manifest_hash = subscription_manifest_hash_v4(
                (policy.channel_or_schema,)
            )
            if (
                segment.subscription_manifest_hash != expected_manifest_hash
                or (
                    intent is not None
                    and (
                        intent.subscription_manifest_hash != expected_manifest_hash
                        or segment.envelopes[0].collector_received_wall_ts
                        < intent.authorized_at
                    )
                )
                or segment.envelopes[0].collector_received_wall_ts
                < session.handshake_completed_at
                or segment.envelopes[0].collector_received_monotonic_ns
                <= session.handshake_completed_monotonic_ns
            ):
                raise PhysicalProjectionV4ConflictError(
                    "prospective primary capture does not follow its current intent"
                )
        registry = self._capture_segment_registry()
        try:
            validation_segment = segment
            parent = (
                None
                if segment.parent_capture_segment_id is None
                else registry.get(segment.parent_capture_segment_id)
            )
            if (
                authoritative_session is not None
                and isinstance(parent, CaptureSegmentV3)
                and segment.connection_generation > parent.connection_generation + 1
            ):
                transport_sessions: dict[str, TransportSessionAttestationV4] = {}
                for (identity_blob,) in self._connection.execute(
                    "SELECT transport_session_id FROM transport_session_attestations"
                ):
                    identity = bytes(identity_blob).hex()
                    loaded = self._load_record(
                        PhysicalRecordKindV4.TRANSPORT_SESSION_ATTESTATION,
                        identity,
                    )
                    assert isinstance(loaded, TransportSessionAttestationV4)
                    transport_sessions[identity] = loaded
                terminal_transport_session_ids = {
                    bytes(row[0]).hex()
                    for row in self._connection.execute(
                        "SELECT transport_session_id FROM transport_session_terminations"
                    )
                }
                validation_segment = _capture_lineage_validation_proxy_v4(
                    segment,
                    registry,
                    transport_sessions=transport_sessions,
                    terminal_transport_session_ids=(terminal_transport_session_ids),
                    captured_transport_session_ids={
                        registered.connection_id for registered in registry.values()
                    },
                )
            validate_capture_segment_lineage(validation_segment, registry)
        except CanonicalizationError as exc:
            raise PhysicalProjectionV4ConflictError(
                "capture segment lineage is invalid"
            ) from exc
        registered_message_ids = {
            message_receipt_id
            for registered in registry.values()
            for message_receipt_id in registered.message_receipt_ids
        }
        if registered_message_ids.intersection(segment.message_receipt_ids):
            raise PhysicalProjectionV4ConflictError(
                "provider message occurrence is already registered in a segment"
            )
        scope_blob = _blob_hash(
            scope.physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        partition_scopes = {
            bytes(row[0])
            for row in self._connection.execute(
                """
                SELECT DISTINCT physical_scope_manifest_id FROM capture_segments
                WHERE capture_partition_id = ?
                """,
                (
                    _blob_hash(
                        segment.capture_partition_id, field="capture_partition_id"
                    ),
                ),
            )
        }
        if partition_scopes and partition_scopes != {scope_blob}:
            raise PhysicalProjectionV4ConflictError(
                "capture partition lineage cannot cross physical scopes"
            )
        adapter_scope_rows = self._connection.execute(
            """
            SELECT DISTINCT c.physical_scope_manifest_id, s.health_policy_id
            FROM capture_segments AS c
            JOIN physical_scopes AS s
              ON s.physical_scope_manifest_id = c.physical_scope_manifest_id
            WHERE c.adapter_policy_id = ?
            """,
            (_blob_hash(segment.adapter_policy_id, field="adapter_policy_id"),),
        ).fetchall()
        reviewed_health_blob = _blob_hash(
            REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4, field="health_policy_id"
        )
        if any(
            bytes(existing_scope) != scope_blob
            and (
                scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4
                or bytes(existing_health) == reviewed_health_blob
            )
            for existing_scope, existing_health in adapter_scope_rows
        ):
            raise PhysicalProjectionV4ConflictError(
                "authoritative adapter stream cannot be split across scopes"
            )

    def _validated_scope_adapter_policies(
        self, scope: PhysicalScopeManifestV4
    ) -> tuple[ProviderAdapterPolicyV3, ProviderAdapterPolicyV3]:
        if (
            scope.required_status_adapter_policy_id is None
            or scope.required_status_classifier_release_hash is None
        ):
            raise PhysicalProjectionV4ConflictError(
                "reviewed V4.3 health requires a status adapter policy"
            )
        primary = self._registered_adapter_policy(scope.primary_adapter_policy_id)
        if primary is None:
            raise PhysicalProjectionV4ConflictError(
                "primary adapter policy is not registered"
            )
        status = self._registered_adapter_policy(
            scope.required_status_adapter_policy_id
        )
        if status is None:
            raise PhysicalProjectionV4ConflictError(
                "required status adapter policy is not registered"
            )

        common_scope = (
            scope.provider_id,
            scope.venue_id,
            scope.environment_id,
            scope.asset_id,
            scope.concrete_contract_id,
            scope.timeframe_id,
            scope.calendar_manifest_id,
        )
        primary_scope = (
            primary.provider_id,
            primary.venue_id,
            primary.environment_id,
            primary.asset_id,
            primary.concrete_contract_id,
            primary.timeframe_id,
            primary.calendar_manifest_id,
        )
        status_scope = (
            status.provider_id,
            status.venue_id,
            status.environment_id,
            status.asset_id,
            status.concrete_contract_id,
            status.timeframe_id,
            status.calendar_manifest_id,
        )
        if (
            primary.message_classifier_release_hash
            != scope.primary_classifier_release_hash
            or primary_scope != common_scope
            or primary.adapter_kind is not ProviderAdapterKind.BYBIT_V5_PUBLIC_KLINE
            or primary.data_use is not ProviderDataUse.TRADING_AUTHORITY
            or not primary.requires_instrument_status
            or primary.base_interval_seconds != 60
            or primary.frozen_at > scope.frozen_at
        ):
            raise PhysicalProjectionV4ConflictError(
                "primary adapter policy differs from its authoritative scope binding"
            )
        if (
            status.message_classifier_release_hash
            != scope.required_status_classifier_release_hash
            or status_scope != common_scope
            or status.adapter_kind is not ProviderAdapterKind.BYBIT_V5_INSTRUMENT_INFO
            or status.data_use is not ProviderDataUse.RECONCILIATION_ONLY
            or status.requires_instrument_status
            or status.base_interval_seconds != primary.base_interval_seconds
            or status.frozen_at > scope.frozen_at
        ):
            raise PhysicalProjectionV4ConflictError(
                "status adapter policy differs from its reconciliation scope binding"
            )
        if primary.provider_native_key != status.provider_native_key:
            raise PhysicalProjectionV4ConflictError(
                "primary and status adapter policies bind different provider instruments"
            )
        return primary, status

    def _prior_normalized_occurrences(
        self,
        *,
        physical_scope_manifest_id: str,
        adapter_policy_id: str,
        before_scope_message_sequence: int,
    ) -> tuple[tuple[CaptureSegmentV3, ProviderMessageDispositionV3], ...]:
        rows = self._connection.execute(
            """
            SELECT p.provider_message_disposition_id, m.capture_segment_id
            FROM message_dispositions AS d
            JOIN disposition_provenance AS p
              ON p.message_disposition_id = d.message_disposition_id
            JOIN physical_messages AS m
              ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
             AND m.scope_message_sequence = d.scope_message_sequence
            WHERE d.physical_scope_manifest_id = ?
              AND m.adapter_policy_id = ?
              AND d.disposition_kind = 'NORMALIZED_OBSERVATION'
              AND d.scope_message_sequence < ?
            ORDER BY d.scope_message_sequence
            """,
            (
                _blob_hash(
                    physical_scope_manifest_id,
                    field="physical_scope_manifest_id",
                ),
                _blob_hash(adapter_policy_id, field="adapter_policy_id"),
                before_scope_message_sequence,
            ),
        ).fetchall()
        return tuple(
            (
                self._load_record(
                    PhysicalRecordKindV4.CAPTURE_SEGMENT,
                    bytes(capture_segment_id).hex(),
                ),
                self._load_record(
                    PhysicalRecordKindV4.PROVIDER_MESSAGE_DISPOSITION,
                    bytes(provider_disposition_id).hex(),
                ),
            )
            for provider_disposition_id, capture_segment_id in rows
        )

    def _build_actor_provider_classification_v49e(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        segment: CaptureSegmentV3,
        message: PhysicalMessageV4,
        classified_at: datetime,
    ) -> ClassificationAppendV4:
        """Replay the reviewed classifier for one actor-derived message.

        The runtime supplies exact completed WebSocket bytes, never a claimed
        disposition.  This projection-owned helper derives the V3 result from
        the registered adapter and resolves duplicate/revision lineage from the
        transaction's causal prefix before constructing its V4 projection.
        """

        policy = self._registered_adapter_policy(message.adapter_policy_id)
        if policy is None:
            raise PhysicalProjectionV4ConflictError(
                "actor provider message uses an unregistered adapter policy"
            )
        capture_receipt = self.get_receipt(message.raw_capture_receipt_sequence)
        if (
            capture_receipt.record_kind is not PhysicalRecordKindV4.CAPTURE_SEGMENT
            or capture_receipt.identity_id != segment.capture_segment_id
        ):
            raise PhysicalProjectionV4ConflictError(
                "actor provider message lacks its exact capture receipt"
            )
        prior = self._prior_normalized_occurrences(
            physical_scope_manifest_id=scope.physical_scope_manifest_id,
            adapter_policy_id=policy.adapter_policy_id,
            before_scope_message_sequence=message.scope_message_sequence,
        )

        def classify(
            *, parent_revision_id: str | None = None
        ) -> tuple[
            ProviderMessageDispositionV3,
            ObservationDerivationV3 | None,
            ObservationRevisionV3 | None,
        ]:
            return build_bybit_v5_message_disposition(
                adapter_policy=policy,
                segment=segment,
                message_receipt_id=message.message_receipt_id,
                source_member_key=scope.source_member_key,
                instrument_mapping_id=scope.instrument_mapping_id,
                durably_appended_ts=capture_receipt.committed_at,
                normalized_at=classified_at,
                available_at=classified_at,
                classified_at=classified_at,
                parent_observation_revision_id=parent_revision_id,
                correction_reason=(
                    None if parent_revision_id is None else "PROVIDER_REVISION"
                ),
                prior_normalized_occurrences=prior,
            )

        provider, derivation, revision = classify()
        if revision is not None:
            prior_revisions = tuple(
                self._load_record(
                    PhysicalRecordKindV4.OBSERVATION_REVISION, bytes(row[0]).hex()
                )
                for row in self._connection.execute(
                    "SELECT observation_revision_id FROM observation_revisions"
                )
            )
            same_key = tuple(
                item
                for item in prior_revisions
                if isinstance(item, ObservationRevisionV3)
                and item.observation_key == revision.observation_key
            )
            if same_key:
                parent_ids = {
                    item.parent_observation_revision_id
                    for item in same_key
                    if item.parent_observation_revision_id is not None
                }
                heads = tuple(
                    item
                    for item in same_key
                    if item.observation_revision_id not in parent_ids
                )
                if len(heads) != 1:
                    raise PhysicalProjectionV4ConflictError(
                        "actor provider revision prefix has no unique causal head"
                    )
                provider, derivation, revision = classify(
                    parent_revision_id=heads[0].observation_revision_id
                )

        duplicate_v4_id: str | None = None
        if provider.disposition_kind is MessageDispositionKind.EXACT_DUPLICATE:
            row = self._connection.execute(
                """
                SELECT message_disposition_id
                FROM disposition_provenance
                WHERE provider_message_disposition_id = ?
                """,
                (
                    _blob_hash(
                        provider.duplicate_of_disposition_id,
                        field="duplicate_of_disposition_id",
                    ),
                ),
            ).fetchone()
            if row is None:
                raise PhysicalProjectionV4ConflictError(
                    "actor duplicate classification lacks its V4 predecessor"
                )
            duplicate_v4_id = bytes(row[0]).hex()
        disposition = message_disposition_from_v3(
            message=message,
            disposition=provider,
            duplicate_of_v4_disposition_id=duplicate_v4_id,
        )
        return ClassificationAppendV4(
            disposition=disposition,
            provider_disposition=provider,
            derivation=derivation,
            revision=revision,
        )

    def _validate_registered_classification(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        message: PhysicalMessageV4,
        classification: ClassificationAppendV4,
    ) -> None:
        policy = self._registered_adapter_policy(message.adapter_policy_id)
        if policy is None:
            if scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4:
                raise PhysicalProjectionV4ConflictError(
                    "authoritative classification adapter policy is not registered"
                )
            return
        segment = self._load_record(
            PhysicalRecordKindV4.CAPTURE_SEGMENT, message.capture_segment_id
        )
        assert isinstance(segment, CaptureSegmentV3)
        capture_receipt = self.get_receipt(message.raw_capture_receipt_sequence)
        if (
            capture_receipt.record_kind is not PhysicalRecordKindV4.CAPTURE_SEGMENT
            or capture_receipt.identity_id != segment.capture_segment_id
        ):
            raise PhysicalProjectionV4ConflictError(
                "message raw-capture receipt does not identify its capture segment"
            )
        provider = classification.provider_disposition
        revision = classification.revision
        derivation = classification.derivation
        normalized = (
            provider.disposition_kind is MessageDispositionKind.NORMALIZED_OBSERVATION
        )
        if normalized:
            assert derivation is not None and revision is not None
            if revision.durably_appended_ts != capture_receipt.committed_at:
                raise PhysicalProjectionV4ConflictError(
                    "observation durable clock differs from capture receipt"
                )
            try:
                validate_raw_normalization_v3(
                    policy=policy,
                    segment=segment,
                    derivation=derivation,
                    revision=revision,
                )
            except CanonicalizationError as exc:
                raise PhysicalProjectionV4ConflictError(
                    "raw normalization differs from registered adapter policy"
                ) from exc
        prior = self._prior_normalized_occurrences(
            physical_scope_manifest_id=scope.physical_scope_manifest_id,
            adapter_policy_id=policy.adapter_policy_id,
            before_scope_message_sequence=message.scope_message_sequence,
        )
        try:
            expected_provider, expected_derivation, expected_revision = (
                build_bybit_v5_message_disposition(
                    adapter_policy=policy,
                    segment=segment,
                    message_receipt_id=message.message_receipt_id,
                    source_member_key=(
                        scope.source_member_key
                        if revision is None
                        else revision.source_member_key
                    ),
                    instrument_mapping_id=(
                        scope.instrument_mapping_id
                        if revision is None
                        else revision.instrument_mapping_id
                    ),
                    durably_appended_ts=capture_receipt.committed_at,
                    normalized_at=(
                        provider.classified_at
                        if revision is None
                        else revision.normalized_at
                    ),
                    available_at=(
                        provider.classified_at
                        if revision is None
                        else revision.available_at
                    ),
                    classified_at=provider.classified_at,
                    parent_observation_revision_id=(
                        None
                        if revision is None
                        else revision.parent_observation_revision_id
                    ),
                    correction_reason=(
                        None if revision is None else revision.correction_reason
                    ),
                    prior_normalized_occurrences=prior,
                )
            )
        except CanonicalizationError as exc:
            raise PhysicalProjectionV4ConflictError(
                "provider classification cannot be replayed under its adapter policy"
            ) from exc
        if provider != expected_provider:
            raise PhysicalProjectionV4ConflictError(
                "provider disposition differs from deterministic classifier replay"
            )
        if derivation != expected_derivation or revision != expected_revision:
            raise PhysicalProjectionV4ConflictError(
                "normalized outputs differ from deterministic classifier replay"
            )

    def append_scope(
        self,
        scope: PhysicalScopeManifestV4,
        *,
        idempotency_key: str,
    ) -> PhysicalScopeManifestV4:
        if not isinstance(scope, PhysicalScopeManifestV4):
            raise CanonicalizationError("scope must be PhysicalScopeManifestV4")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_SCOPE_V4"
        request = _request_hash(operation, scope.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                return self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                    str(replay["physical_scope_manifest_id"]),
                )
            if scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4:
                self._validated_scope_adapter_policies(scope)
                existing = self._connection.execute(
                    """
                    SELECT physical_scope_manifest_id FROM physical_scopes
                    WHERE primary_adapter_policy_id = ? AND health_policy_id = ?
                    LIMIT 1
                    """,
                    (
                        _blob_hash(
                            scope.primary_adapter_policy_id,
                            field="primary_adapter_policy_id",
                        ),
                        _blob_hash(
                            REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4,
                            field="health_policy_id",
                        ),
                    ),
                ).fetchone()
                if existing is not None:
                    raise PhysicalProjectionV4ConflictError(
                        "reviewed primary adapter policy already belongs to a scope"
                    )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(scope)
            self._connection.execute(
                """
                INSERT INTO physical_scopes(
                    physical_scope_manifest_id, source_member_key,
                    instrument_mapping_id, primary_adapter_policy_id,
                    primary_classifier_release_hash,
                    required_status_adapter_policy_id,
                    required_status_classifier_release_hash, health_policy_id,
                    frozen_at_us, source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        scope.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(scope.source_member_key, field="source_member_key"),
                    _blob_hash(
                        scope.instrument_mapping_id, field="instrument_mapping_id"
                    ),
                    _blob_hash(
                        scope.primary_adapter_policy_id,
                        field="primary_adapter_policy_id",
                    ),
                    _blob_hash(
                        scope.primary_classifier_release_hash,
                        field="primary_classifier_release_hash",
                    ),
                    None
                    if scope.required_status_adapter_policy_id is None
                    else _blob_hash(
                        scope.required_status_adapter_policy_id,
                        field="required_status_adapter_policy_id",
                    ),
                    None
                    if scope.required_status_classifier_release_hash is None
                    else _blob_hash(
                        scope.required_status_classifier_release_hash,
                        field="required_status_classifier_release_hash",
                    ),
                    _blob_hash(scope.health_policy_id, field="health_policy_id"),
                    _timestamp_us(scope.frozen_at, field="frozen_at"),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_scope_projection_insert")
            result = {"physical_scope_manifest_id": scope.physical_scope_manifest_id}
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return scope

    def append_messages(
        self,
        *,
        physical_scope_manifest_id: str,
        segment: CaptureSegmentV3,
        idempotency_key: str,
    ) -> tuple[PhysicalMessageV4, ...]:
        scope_id = canonical_hash(
            physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        if not isinstance(segment, CaptureSegmentV3):
            raise CanonicalizationError("segment must be CaptureSegmentV3")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_MESSAGES_V4"
        request = _request_hash(
            operation,
            {
                "capture_segment_id": segment.capture_segment_id,
                "physical_scope_manifest_id": scope_id,
            },
        )
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                raw_ids = replay.get("physical_message_ids")
                if not isinstance(raw_ids, list):
                    raise PhysicalProjectionV4VerificationError(
                        "message batch result is malformed"
                    )
                return tuple(
                    self._load_record(
                        PhysicalRecordKindV4.PHYSICAL_MESSAGE, str(identity)
                    )
                    for identity in raw_ids
                )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST, scope_id
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            if scope.health_policy_id == REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4:
                self._validated_scope_adapter_policies(scope)
            self._validate_capture_segment_admission(scope=scope, segment=segment)
            first_sequence = self._last_receipt()[0] + 1
            predicted_capture_receipt = first_sequence
            row = self._connection.execute(
                """
                SELECT max(scope_message_sequence)
                FROM physical_messages WHERE physical_scope_manifest_id = ?
                """,
                (_blob_hash(scope_id, field="physical_scope_manifest_id"),),
            ).fetchone()
            first_scope_sequence = 1 if row[0] is None else int(row[0]) + 1
            messages = tuple(
                physical_message_from_v3(
                    scope=scope,
                    segment=segment,
                    envelope_ordinal=ordinal,
                    scope_message_sequence=first_scope_sequence + ordinal,
                    raw_capture_receipt_sequence=predicted_capture_receipt,
                )
                for ordinal in range(len(segment.envelopes))
            )
            capture_receipt = self._append_record(segment)
            if capture_receipt.global_sequence != predicted_capture_receipt:
                raise PhysicalProjectionV4ConflictError(
                    "capture receipt allocation drifted"
                )
            if capture_receipt.committed_at + timedelta(
                milliseconds=segment.clock_uncertainty_milliseconds
            ) < max(
                envelope.collector_received_wall_ts for envelope in segment.envelopes
            ):
                raise PhysicalProjectionV4ConflictError(
                    "capture receipt predates a collector message beyond uncertainty"
                )
            scope_blob = _blob_hash(scope_id, field="physical_scope_manifest_id")
            self._connection.execute(
                """
                INSERT INTO capture_segments(
                    capture_segment_id, physical_scope_manifest_id,
                    adapter_policy_id, capture_partition_id,
                    provider_native_key, collector_instance_id,
                    collector_boot_id, connection_id,
                    connection_generation, subscription_manifest_hash,
                    vintage, first_collector_sequence,
                    last_collector_sequence, clock_uncertainty_milliseconds,
                    parent_capture_segment_id, first_scope_message_sequence,
                    last_scope_message_sequence, envelope_count, closed_at_us,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(segment.capture_segment_id, field="capture_segment_id"),
                    scope_blob,
                    _blob_hash(segment.adapter_policy_id, field="adapter_policy_id"),
                    _blob_hash(
                        segment.capture_partition_id, field="capture_partition_id"
                    ),
                    segment.provider_native_key,
                    segment.collector_instance_id,
                    segment.collector_boot_id,
                    segment.connection_id,
                    segment.connection_generation,
                    _blob_hash(
                        segment.subscription_manifest_hash,
                        field="subscription_manifest_hash",
                    ),
                    segment.vintage.value,
                    segment.envelopes[0].collector_sequence,
                    segment.envelopes[-1].collector_sequence,
                    segment.clock_uncertainty_milliseconds,
                    None
                    if segment.parent_capture_segment_id is None
                    else _blob_hash(
                        segment.parent_capture_segment_id,
                        field="parent_capture_segment_id",
                    ),
                    messages[0].scope_message_sequence,
                    messages[-1].scope_message_sequence,
                    len(messages),
                    _timestamp_us(segment.closed_at, field="closed_at"),
                    capture_receipt.global_sequence,
                    _blob_hash(capture_receipt.content_hash, field="content_hash"),
                ),
            )
            for message in messages:
                receipt = self._append_record(message)
                self._connection.execute(
                    """
                    INSERT INTO physical_messages(
                        physical_scope_manifest_id, scope_message_sequence,
                        physical_message_id, capture_segment_id,
                        envelope_ordinal, message_receipt_id,
                        raw_payload_sha256, adapter_policy_id,
                        raw_capture_receipt_sequence, source_receipt_sequence,
                        source_content_hash
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        scope_blob,
                        message.scope_message_sequence,
                        _blob_hash(
                            message.physical_message_id, field="physical_message_id"
                        ),
                        _blob_hash(
                            message.capture_segment_id, field="capture_segment_id"
                        ),
                        message.envelope_ordinal,
                        _blob_hash(
                            message.message_receipt_id, field="message_receipt_id"
                        ),
                        _blob_hash(
                            message.raw_payload_sha256, field="raw_payload_sha256"
                        ),
                        _blob_hash(
                            message.adapter_policy_id, field="adapter_policy_id"
                        ),
                        message.raw_capture_receipt_sequence,
                        receipt.global_sequence,
                        _blob_hash(receipt.content_hash, field="content_hash"),
                    ),
                )
            self._fault("after_message_projection_insert")
            result = {
                "capture_segment_id": segment.capture_segment_id,
                "physical_message_ids": [item.physical_message_id for item in messages],
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return messages

    def _frontier(self, scope_id: bytes) -> RFC9162Frontier:
        row = self._connection.execute(
            """
            SELECT count(*) FROM message_dispositions
            WHERE physical_scope_manifest_id = ?
            """,
            (scope_id,),
        ).fetchone()
        size = int(row[0])
        if size == 0:
            return RFC9162Frontier()
        peaks: list[tuple[int, bytes]] = []
        cursor = 0
        for level in range(size.bit_length() - 1, -1, -1):
            width = 1 << level
            if size & width:
                stored = self._connection.execute(
                    """
                    SELECT hash_value FROM stored_hashes
                    WHERE physical_scope_manifest_id = ?
                      AND level = ? AND subtree_index = ?
                    """,
                    (scope_id, level, cursor >> level),
                ).fetchone()
                if stored is None:
                    raise PhysicalProjectionV4ConflictError(
                        "stored-hash frontier is incomplete"
                    )
                peaks.append((level, bytes(stored[0])))
                cursor += width
        return RFC9162Frontier(size, tuple(peaks))

    def _append_observation_records(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        message: PhysicalMessageV4,
        provider_disposition: ProviderMessageDispositionV3,
        derivation: ObservationDerivationV3,
        revision: ObservationRevisionV3,
    ) -> tuple[PhysicalProjectionReceiptV4, PhysicalProjectionReceiptV4]:
        if derivation.derivation_kind is not DerivationKind.RAW_NORMALIZATION:
            raise PhysicalProjectionV4ConflictError(
                "provider evidence accepts RAW_NORMALIZATION derivations only"
            )
        if derivation.input_message_receipt_ids != (message.message_receipt_id,):
            raise PhysicalProjectionV4ConflictError(
                "observation derivation does not consume its exact physical message"
            )
        if revision.observation_derivation_id != derivation.observation_derivation_id:
            raise PhysicalProjectionV4ConflictError(
                "observation revision references another derivation"
            )
        if (
            revision.field_ids != derivation.output_field_ids
            or revision.field_values != derivation.output_field_values
            or revision.value_digest != derivation.output_value_digest
        ):
            raise PhysicalProjectionV4ConflictError(
                "observation revision differs from its derivation output"
            )
        if provider_disposition.classified_at < revision.available_at:
            raise PhysicalProjectionV4ConflictError(
                "provider classification predates observation availability"
            )
        common_scope = (
            revision.source_member_key,
            revision.instrument_mapping_id,
            revision.asset_id,
            revision.venue_id,
            revision.concrete_contract_id,
            revision.timeframe_id,
        )
        expected_scope = (
            scope.source_member_key,
            scope.instrument_mapping_id,
            scope.asset_id,
            scope.venue_id,
            scope.concrete_contract_id,
            scope.timeframe_id,
        )
        if common_scope != expected_scope:
            raise PhysicalProjectionV4ConflictError(
                "observation coordinates differ from the physical scope"
            )
        if derivation.calendar_manifest_id != scope.calendar_manifest_id:
            raise PhysicalProjectionV4ConflictError(
                "observation derivation changes the scoped calendar"
            )
        if revision.adapter_policy_id != message.adapter_policy_id or (
            derivation.adapter_policy_id != message.adapter_policy_id
        ):
            raise PhysicalProjectionV4ConflictError(
                "observation output changes the message adapter policy"
            )
        if message.adapter_policy_id == scope.primary_adapter_policy_id:
            if (
                revision.observation_kind is not ObservationKind.BAR
                or revision.observation_name != "provider-completed-ohlcv"
                or revision.timeframe_id != "1m"
                or revision.bar_open_ts is None
                or revision.bar_close_ts is None
                or (revision.bar_close_ts - revision.bar_open_ts).total_seconds() != 60
                or _timestamp_us(revision.bar_open_ts, field="bar_open_ts") % 60_000_000
                != 0
            ):
                raise PhysicalProjectionV4ConflictError(
                    "primary V4 observation must be a UTC-grid 60-second bar"
                )
        elif message.adapter_policy_id == scope.required_status_adapter_policy_id:
            if (
                revision.observation_kind is not ObservationKind.INSTRUMENT_STATUS
                or revision.observation_name != "instrument-status"
            ):
                raise PhysicalProjectionV4ConflictError(
                    "status adapter may emit INSTRUMENT_STATUS observations only"
                )
        else:
            raise PhysicalProjectionV4ConflictError(
                "observation adapter policy is outside the physical scope"
            )
        registry = {
            bytes(row[0]).hex(): self._load_record(
                PhysicalRecordKindV4.OBSERVATION_REVISION, bytes(row[0]).hex()
            )
            for row in self._connection.execute(
                "SELECT observation_revision_id FROM observation_revisions"
            )
        }
        validate_observation_revision_lineage(revision, registry)
        derivation_receipt = self._append_record(derivation)
        revision_receipt = self._append_record(revision)
        return derivation_receipt, revision_receipt

    def _insert_observation_projection(
        self,
        *,
        scope_blob: bytes,
        derivation: ObservationDerivationV3,
        revision: ObservationRevisionV3,
        derivation_receipt: PhysicalProjectionReceiptV4,
        revision_receipt: PhysicalProjectionReceiptV4,
        admission_receipt: PhysicalProjectionReceiptV4,
    ) -> None:
        self._connection.execute(
            """
            INSERT INTO observation_derivations(
                observation_derivation_id, physical_scope_manifest_id,
                adapter_policy_id, derivation_kind,
                input_message_receipt_id, input_root,
                transform_code_hash, transform_parameters_hash,
                interval_policy_id, numeric_policy_id,
                sparse_interval_policy_id, calendar_manifest_id,
                output_field_ids_blob, output_field_values_blob,
                output_value_digest, derived_at_us,
                source_receipt_sequence, source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                _blob_hash(
                    derivation.observation_derivation_id,
                    field="observation_derivation_id",
                ),
                scope_blob,
                _blob_hash(derivation.adapter_policy_id, field="adapter_policy_id"),
                derivation.derivation_kind.value,
                _blob_hash(
                    derivation.input_message_receipt_ids[0],
                    field="input_message_receipt_id",
                ),
                _blob_hash(derivation.input_root, field="input_root"),
                _blob_hash(derivation.transform_code_hash, field="transform_code_hash"),
                _blob_hash(
                    derivation.transform_parameters_hash,
                    field="transform_parameters_hash",
                ),
                _blob_hash(derivation.interval_policy_id, field="interval_policy_id"),
                _blob_hash(derivation.numeric_policy_id, field="numeric_policy_id"),
                _blob_hash(
                    derivation.sparse_interval_policy_id,
                    field="sparse_interval_policy_id",
                ),
                _blob_hash(
                    derivation.calendar_manifest_id, field="calendar_manifest_id"
                ),
                canonical_json_bytes(list(derivation.output_field_ids)),
                canonical_json_bytes(list(derivation.output_field_values)),
                _blob_hash(derivation.output_value_digest, field="output_value_digest"),
                _timestamp_us(derivation.derived_at, field="derived_at"),
                derivation_receipt.global_sequence,
                _blob_hash(derivation_receipt.content_hash, field="content_hash"),
            ),
        )
        self._fault("after_observation_derivation_insert")
        self._connection.execute(
            """
            INSERT INTO observation_revisions(
                observation_revision_id, physical_scope_manifest_id,
                observation_derivation_id, observation_key,
                parent_observation_revision_id, adapter_policy_id,
                source_member_key, instrument_mapping_id, source_id,
                asset_id, venue_id, concrete_contract_id, timeframe_id,
                observation_name, observation_kind, bar_open_us, bar_close_us,
                source_event_us, source_publish_us, durably_appended_us,
                normalized_at_us, available_at_us, completion_state,
                completion_basis, value_digest, field_ids_blob,
                field_values_blob, correction_reason, source_receipt_sequence,
                admission_receipt_sequence, source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                _blob_hash(
                    revision.observation_revision_id, field="observation_revision_id"
                ),
                scope_blob,
                _blob_hash(
                    revision.observation_derivation_id,
                    field="observation_derivation_id",
                ),
                _blob_hash(revision.observation_key, field="observation_key"),
                None
                if revision.parent_observation_revision_id is None
                else _blob_hash(
                    revision.parent_observation_revision_id,
                    field="parent_observation_revision_id",
                ),
                _blob_hash(revision.adapter_policy_id, field="adapter_policy_id"),
                _blob_hash(revision.source_member_key, field="source_member_key"),
                _blob_hash(
                    revision.instrument_mapping_id, field="instrument_mapping_id"
                ),
                revision.source_id,
                revision.asset_id,
                revision.venue_id,
                revision.concrete_contract_id,
                revision.timeframe_id,
                revision.observation_name,
                revision.observation_kind.value,
                _optional_timestamp_us(revision.bar_open_ts, field="bar_open_ts"),
                _optional_timestamp_us(revision.bar_close_ts, field="bar_close_ts"),
                _timestamp_us(revision.source_event_ts, field="source_event_ts"),
                _optional_timestamp_us(
                    revision.source_publish_ts, field="source_publish_ts"
                ),
                _timestamp_us(
                    revision.durably_appended_ts, field="durably_appended_ts"
                ),
                _timestamp_us(revision.normalized_at, field="normalized_at"),
                _timestamp_us(revision.available_at, field="available_at"),
                revision.completion_state.value,
                revision.completion_basis.value,
                _blob_hash(revision.value_digest, field="value_digest"),
                canonical_json_bytes(list(revision.field_ids)),
                canonical_json_bytes(list(revision.field_values)),
                revision.correction_reason,
                revision_receipt.global_sequence,
                admission_receipt.global_sequence,
                _blob_hash(revision_receipt.content_hash, field="content_hash"),
            ),
        )
        self._fault("after_observation_revision_insert")

    def append_classification_batch(
        self,
        classifications: Sequence[ClassificationAppendV4],
        *,
        idempotency_key: str,
    ) -> tuple[tuple[MessageDispositionV4, EvidenceTreeHeadV4], ...]:
        if isinstance(classifications, (str, bytes, bytearray)) or not isinstance(
            classifications, Sequence
        ):
            raise CanonicalizationError("classifications must be a sequence")
        items = tuple(classifications)
        if not items or not all(
            isinstance(item, ClassificationAppendV4) for item in items
        ):
            raise CanonicalizationError(
                "classifications must contain ClassificationAppendV4 records"
            )
        dispositions = tuple(item.disposition for item in items)
        scope_ids = {item.disposition.physical_scope_manifest_id for item in items}
        if len(scope_ids) != 1:
            raise CanonicalizationError(
                "one disposition batch must belong to one physical scope"
            )
        scope_id = next(iter(scope_ids))
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_CLASSIFICATION_BATCH_V4_1"
        request = _request_hash(
            operation,
            {
                "classification_inputs": [
                    {
                        "message_disposition_id": item.disposition.message_disposition_id,
                        "observation_derivation_id": (
                            None
                            if item.derivation is None
                            else item.derivation.observation_derivation_id
                        ),
                        "observation_revision_id": (
                            None
                            if item.revision is None
                            else item.revision.observation_revision_id
                        ),
                        "provider_message_disposition_id": (
                            item.provider_disposition.provider_message_disposition_id
                        ),
                    }
                    for item in items
                ],
                "physical_scope_manifest_id": scope_id,
            },
        )
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                disposition_ids = replay.get("message_disposition_ids")
                head_ids = replay.get("evidence_tree_head_ids")
                if (
                    not isinstance(disposition_ids, list)
                    or not isinstance(head_ids, list)
                    or len(disposition_ids) != len(head_ids)
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "disposition batch result is malformed"
                    )
                return tuple(
                    (
                        self._load_record(
                            PhysicalRecordKindV4.MESSAGE_DISPOSITION,
                            str(disposition_id),
                        ),
                        self._load_record(
                            PhysicalRecordKindV4.EVIDENCE_TREE_HEAD,
                            str(head_id),
                        ),
                    )
                    for disposition_id, head_id in zip(
                        disposition_ids, head_ids, strict=True
                    )
                )
            scope_blob = _blob_hash(scope_id, field="physical_scope_manifest_id")
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST, scope_id
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            frontier = self._frontier(scope_blob)
            first_sequence = self._last_receipt()[0] + 1
            expected_sequences = tuple(
                range(
                    frontier.tree_size + 1,
                    frontier.tree_size + len(dispositions) + 1,
                )
            )
            if (
                tuple(item.scope_message_sequence for item in dispositions)
                != expected_sequences
            ):
                raise PhysicalProjectionV4ConflictError(
                    "disposition batch is not the next contiguous scope prefix"
                )
            parent: EvidenceTreeHeadV4 | None = None
            if frontier.tree_size:
                parent_row = self._connection.execute(
                    """
                    SELECT evidence_tree_head_id FROM tree_heads
                    WHERE physical_scope_manifest_id = ? AND tree_size = ?
                    """,
                    (scope_blob, frontier.tree_size),
                ).fetchone()
                if parent_row is None:
                    raise PhysicalProjectionV4ConflictError(
                        "active tree head is missing"
                    )
                parent = self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_TREE_HEAD,
                    bytes(parent_row[0]).hex(),
                )
            pairs: list[tuple[MessageDispositionV4, EvidenceTreeHeadV4]] = []
            for classification in items:
                disposition = classification.disposition
                authority_problem = _disposition_authority_problem(
                    scope=scope, disposition=disposition
                )
                if authority_problem is not None:
                    raise PhysicalProjectionV4ConflictError(authority_problem)
                message_row = self._connection.execute(
                    """
                    SELECT physical_message_id, message_receipt_id,
                           capture_segment_id, raw_payload_sha256,
                           adapter_policy_id
                    FROM physical_messages
                    WHERE physical_scope_manifest_id = ?
                      AND scope_message_sequence = ?
                    """,
                    (scope_blob, disposition.scope_message_sequence),
                ).fetchone()
                if message_row is None:
                    raise PhysicalProjectionV4ConflictError(
                        "disposition has no captured physical message"
                    )
                expected_message_fields = (
                    disposition.physical_message_id,
                    disposition.message_receipt_id,
                    disposition.capture_segment_id,
                    disposition.raw_payload_sha256,
                    disposition.adapter_policy_id,
                )
                if tuple(bytes(value).hex() for value in message_row) != (
                    expected_message_fields
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "disposition differs from its captured physical message"
                    )
                provider_disposition = classification.provider_disposition
                message = self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_MESSAGE,
                    disposition.physical_message_id,
                )
                assert isinstance(message, PhysicalMessageV4)
                self._validate_registered_classification(
                    scope=scope,
                    message=message,
                    classification=classification,
                )
                duplicate_v4_id: str | None = None
                if (
                    provider_disposition.disposition_kind
                    is MessageDispositionKind.EXACT_DUPLICATE
                ):
                    duplicate_row = self._connection.execute(
                        """
                        SELECT message_disposition_id
                        FROM disposition_provenance
                        WHERE provider_message_disposition_id = ?
                        """,
                        (
                            _blob_hash(
                                provider_disposition.duplicate_of_disposition_id,
                                field="duplicate_of_disposition_id",
                            ),
                        ),
                    ).fetchone()
                    if duplicate_row is None:
                        raise PhysicalProjectionV4ConflictError(
                            "duplicate classifier provenance is not registered"
                        )
                    duplicate_v4_id = bytes(duplicate_row[0]).hex()
                expected_disposition = message_disposition_from_v3(
                    message=message,
                    disposition=provider_disposition,
                    duplicate_of_v4_disposition_id=duplicate_v4_id,
                )
                if expected_disposition != disposition:
                    raise PhysicalProjectionV4ConflictError(
                        "V4 disposition differs from its V3 classifier provenance"
                    )
                derivation_receipt: PhysicalProjectionReceiptV4 | None = None
                revision_receipt: PhysicalProjectionReceiptV4 | None = None
                if classification.derivation is not None:
                    assert classification.revision is not None
                    derivation_receipt, revision_receipt = (
                        self._append_observation_records(
                            scope=scope,
                            message=message,
                            provider_disposition=provider_disposition,
                            derivation=classification.derivation,
                            revision=classification.revision,
                        )
                    )
                if (
                    disposition.disposition_kind
                    is MessageDispositionKind.NORMALIZED_OBSERVATION
                ):
                    prior_normalized = self._connection.execute(
                        """
                        SELECT 1
                        FROM message_dispositions AS d
                        JOIN physical_messages AS m
                          ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
                         AND m.scope_message_sequence = d.scope_message_sequence
                        WHERE d.physical_scope_manifest_id = ?
                          AND d.disposition_kind = 'NORMALIZED_OBSERVATION'
                          AND m.adapter_policy_id = ?
                          AND m.raw_payload_sha256 = ?
                          AND d.scope_message_sequence < ?
                        LIMIT 1
                        """,
                        (
                            scope_blob,
                            _blob_hash(
                                disposition.adapter_policy_id,
                                field="adapter_policy_id",
                            ),
                            _blob_hash(
                                disposition.raw_payload_sha256,
                                field="raw_payload_sha256",
                            ),
                            disposition.scope_message_sequence,
                        ),
                    ).fetchone()
                    if prior_normalized is not None:
                        raise PhysicalProjectionV4ConflictError(
                            "repeated normalized raw occurrence must be EXACT_DUPLICATE"
                        )
                if (
                    disposition.disposition_kind
                    is MessageDispositionKind.EXACT_DUPLICATE
                ):
                    original = self._connection.execute(
                        """
                        SELECT d.scope_message_sequence, d.message_disposition_id,
                               m.message_receipt_id
                        FROM message_dispositions AS d
                        JOIN physical_messages AS m
                          ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
                         AND m.scope_message_sequence = d.scope_message_sequence
                        WHERE d.physical_scope_manifest_id = ?
                          AND d.disposition_kind = 'NORMALIZED_OBSERVATION'
                          AND m.adapter_policy_id = ?
                          AND m.raw_payload_sha256 = ?
                          AND d.scope_message_sequence < ?
                        ORDER BY d.scope_message_sequence
                        LIMIT 1
                        """,
                        (
                            scope_blob,
                            _blob_hash(
                                disposition.adapter_policy_id,
                                field="adapter_policy_id",
                            ),
                            _blob_hash(
                                disposition.raw_payload_sha256,
                                field="raw_payload_sha256",
                            ),
                            disposition.scope_message_sequence,
                        ),
                    ).fetchone()
                    if original is None:
                        raise PhysicalProjectionV4ConflictError(
                            "duplicate disposition has no earlier normalized occurrence with the same raw payload"
                        )
                    if (
                        bytes(original[1]).hex()
                        != disposition.duplicate_of_disposition_id
                        or bytes(original[2]).hex()
                        != disposition.duplicate_of_message_receipt_id
                    ):
                        raise PhysicalProjectionV4ConflictError(
                            "duplicate disposition does not reference the earliest exact normalized occurrence"
                        )
                provider_receipt = self._append_record(provider_disposition)
                if provider_receipt.committed_at < provider_disposition.classified_at:
                    raise PhysicalProjectionV4ConflictError(
                        "classifier receipt predates classified_at"
                    )
                self._fault("after_provider_disposition_record_insert")
                receipt = self._append_record(disposition)
                if classification.derivation is not None:
                    assert classification.revision is not None
                    assert derivation_receipt is not None
                    assert revision_receipt is not None
                    self._insert_observation_projection(
                        scope_blob=scope_blob,
                        derivation=classification.derivation,
                        revision=classification.revision,
                        derivation_receipt=derivation_receipt,
                        revision_receipt=revision_receipt,
                        admission_receipt=receipt,
                    )
                self._connection.execute(
                    """
                    INSERT INTO message_dispositions(
                        physical_scope_manifest_id, scope_message_sequence,
                        message_disposition_id, physical_message_id,
                        classifier_result_id, disposition_kind,
                        health_severity, reason_codes_blob,
                        observation_derivation_id, observation_revision_id,
                        duplicate_of_message_receipt_id,
                        duplicate_of_message_disposition_id,
                        source_receipt_sequence, source_content_hash
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        scope_blob,
                        disposition.scope_message_sequence,
                        _blob_hash(
                            disposition.message_disposition_id,
                            field="message_disposition_id",
                        ),
                        _blob_hash(
                            disposition.physical_message_id, field="physical_message_id"
                        ),
                        _blob_hash(
                            disposition.classifier_result_id,
                            field="classifier_result_id",
                        ),
                        disposition.disposition_kind.value,
                        disposition.health_severity.value,
                        canonical_json_bytes(list(disposition.reason_codes)),
                        None
                        if not disposition.observation_derivation_ids
                        else _blob_hash(
                            disposition.observation_derivation_ids[0],
                            field="observation_derivation_id",
                        ),
                        None
                        if not disposition.observation_revision_ids
                        else _blob_hash(
                            disposition.observation_revision_ids[0],
                            field="observation_revision_id",
                        ),
                        None
                        if disposition.duplicate_of_message_receipt_id is None
                        else _blob_hash(
                            disposition.duplicate_of_message_receipt_id,
                            field="duplicate_of_message_receipt_id",
                        ),
                        None
                        if disposition.duplicate_of_disposition_id is None
                        else _blob_hash(
                            disposition.duplicate_of_disposition_id,
                            field="duplicate_of_disposition_id",
                        ),
                        receipt.global_sequence,
                        _blob_hash(receipt.content_hash, field="content_hash"),
                    ),
                )
                self._connection.execute(
                    """
                    INSERT INTO disposition_provenance(
                        provider_message_disposition_id,
                        message_disposition_id,
                        physical_scope_manifest_id,
                        scope_message_sequence,
                        classified_at_us,
                        source_receipt_sequence,
                        source_content_hash
                    ) VALUES(?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        _blob_hash(
                            provider_disposition.provider_message_disposition_id,
                            field="provider_message_disposition_id",
                        ),
                        _blob_hash(
                            disposition.message_disposition_id,
                            field="message_disposition_id",
                        ),
                        scope_blob,
                        disposition.scope_message_sequence,
                        _timestamp_us(
                            provider_disposition.classified_at,
                            field="classified_at",
                        ),
                        provider_receipt.global_sequence,
                        _blob_hash(
                            provider_receipt.content_hash,
                            field="content_hash",
                        ),
                    ),
                )
                self._fault("after_disposition_provenance_insert")
                head, frontier, stored = append_disposition_tree_head_v4(
                    disposition=disposition,
                    frontier=frontier,
                    cutoff_global_sequence=receipt.global_sequence,
                    cutoff_receipt_hash=receipt.receipt_hash,
                    parent=parent,
                )
                for stored_hash in stored:
                    self._insert_stored_hash(
                        scope_blob=scope_blob,
                        stored_hash=stored_hash,
                        created_tree_size=frontier.tree_size,
                        disposition=disposition,
                    )
                head_receipt = self._append_record(head)
                self._connection.execute(
                    """
                    INSERT INTO tree_heads(
                        physical_scope_manifest_id, tree_size,
                        evidence_tree_head_id, tree_root,
                        last_message_disposition_id, cutoff_global_sequence,
                        cutoff_receipt_hash, parent_evidence_tree_head_id,
                        source_receipt_sequence, source_content_hash
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        scope_blob,
                        head.tree_size,
                        _blob_hash(
                            head.evidence_tree_head_id, field="evidence_tree_head_id"
                        ),
                        _blob_hash(head.tree_root, field="tree_root"),
                        _blob_hash(
                            head.last_message_disposition_id,
                            field="last_message_disposition_id",
                        ),
                        head.cutoff_global_sequence,
                        _blob_hash(
                            head.cutoff_receipt_hash, field="cutoff_receipt_hash"
                        ),
                        None
                        if head.parent_evidence_tree_head_id is None
                        else _blob_hash(
                            head.parent_evidence_tree_head_id,
                            field="parent_evidence_tree_head_id",
                        ),
                        head_receipt.global_sequence,
                        _blob_hash(head_receipt.content_hash, field="content_hash"),
                    ),
                )
                self._fault("after_disposition_tree_head_insert")
                pairs.append((disposition, head))
                parent = head
            result = {
                "evidence_tree_head_ids": [
                    head.evidence_tree_head_id for _, head in pairs
                ],
                "message_disposition_ids": [
                    disposition.message_disposition_id for disposition, _ in pairs
                ],
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return tuple(pairs)

    def _insert_stored_hash(
        self,
        *,
        scope_blob: bytes,
        stored_hash: RFC9162StoredHash,
        created_tree_size: int,
        disposition: MessageDispositionV4,
    ) -> None:
        self._connection.execute(
            """
            INSERT INTO stored_hashes(
                physical_scope_manifest_id, level, subtree_index,
                hash_value, created_tree_size, message_disposition_id
            ) VALUES(?, ?, ?, ?, ?, ?)
            """,
            (
                scope_blob,
                stored_hash.level,
                stored_hash.subtree_index,
                stored_hash.value,
                created_tree_size,
                _blob_hash(
                    disposition.message_disposition_id,
                    field="message_disposition_id",
                ),
            ),
        )

    @staticmethod
    def _coverage_stats(
        connection: sqlite3.Connection,
        *,
        table: str,
        scope_blob: bytes,
        before_receipt_sequence: int | None = None,
    ) -> tuple[int, int]:
        if table not in {"physical_messages", "message_dispositions", "tree_heads"}:
            raise AssertionError("unsupported coverage table")
        sequence_column = (
            "tree_size" if table == "tree_heads" else "scope_message_sequence"
        )
        sql = (
            f"SELECT {sequence_column} FROM {table} "
            "WHERE physical_scope_manifest_id = ?"
        )
        params: tuple[Any, ...] = (scope_blob,)
        if before_receipt_sequence is not None:
            sql += " AND source_receipt_sequence <= ?"
            params += (before_receipt_sequence,)
        sql += f" ORDER BY {sequence_column}"
        values = [int(row[0]) for row in connection.execute(sql, params)]
        if not values:
            return 0, 0
        expected = list(range(1, len(values) + 1))
        if values != expected:
            raise PhysicalProjectionV4ConflictError(
                f"{table} contains an explicit sequence gap"
            )
        return len(values), values[-1]

    @staticmethod
    def _derived_event_time_watermark_us(
        connection: sqlite3.Connection,
        *,
        scope_blob: bytes,
        primary_adapter_policy_blob: bytes,
        source_member_key_blob: bytes,
        cutoff_global_sequence: int,
        knowledge_cutoff_us: int,
    ) -> int | None:
        row = connection.execute(
            """
            SELECT max(r.bar_close_us)
            FROM observation_revisions AS r
                 INDEXED BY observation_revision_select_complete_bar_v4
            WHERE r.physical_scope_manifest_id = ?
              AND r.adapter_policy_id = ?
              AND r.source_member_key = ?
              AND r.observation_kind = 'BAR'
              AND r.completion_state = 'COMPLETE'
              AND r.timeframe_id = '1m'
              AND r.admission_receipt_sequence <= ?
              AND r.available_at_us <= ?
              AND r.bar_close_us <= ?
              AND NOT EXISTS (
                  SELECT 1 FROM observation_revisions AS successor
                  WHERE successor.parent_observation_revision_id =
                            r.observation_revision_id
                    AND successor.admission_receipt_sequence <= ?
                    AND successor.available_at_us <= ?
              )
            """,
            (
                scope_blob,
                primary_adapter_policy_blob,
                source_member_key_blob,
                cutoff_global_sequence,
                knowledge_cutoff_us,
                knowledge_cutoff_us,
                cutoff_global_sequence,
                knowledge_cutoff_us,
            ),
        ).fetchone()
        return None if row is None or row[0] is None else int(row[0])

    def _append_cutoff_record(
        self, cutoff: EvidenceCutoffV4
    ) -> PhysicalProjectionReceiptV4:
        """Append one already-derived cutoff and its exact typed projection."""

        receipt = self._append_record(cutoff)
        self._connection.execute(
            """
            INSERT INTO evidence_cutoffs(
                evidence_cutoff_id, physical_scope_manifest_id,
                evidence_tree_head_id, tree_size, tree_root,
                cutoff_global_sequence, cutoff_receipt_hash,
                knowledge_cutoff_us, raw_message_count,
                raw_message_high_water_sequence, disposition_count,
                disposition_high_water_sequence,
                current_required_status_revision_id, vintage, health,
                health_reason_codes_blob, event_time_watermark_us,
                health_valid_until_us, parent_evidence_cutoff_id,
                source_receipt_sequence, source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                _blob_hash(cutoff.evidence_cutoff_id, field="evidence_cutoff_id"),
                _blob_hash(
                    cutoff.physical_scope_manifest_id,
                    field="physical_scope_manifest_id",
                ),
                None
                if cutoff.evidence_tree_head_id is None
                else _blob_hash(
                    cutoff.evidence_tree_head_id,
                    field="evidence_tree_head_id",
                ),
                cutoff.tree_size,
                _blob_hash(cutoff.tree_root, field="tree_root"),
                cutoff.cutoff_global_sequence,
                _blob_hash(cutoff.cutoff_receipt_hash, field="cutoff_receipt_hash"),
                _timestamp_us(cutoff.knowledge_cutoff_ts, field="knowledge_cutoff_ts"),
                cutoff.raw_message_count,
                cutoff.raw_message_high_water_sequence,
                cutoff.disposition_count,
                cutoff.disposition_high_water_sequence,
                None
                if cutoff.current_required_status_revision_id is None
                else _blob_hash(
                    cutoff.current_required_status_revision_id,
                    field="current_required_status_revision_id",
                ),
                cutoff.vintage.value,
                cutoff.health.value,
                canonical_json_bytes(list(cutoff.health_reason_codes)),
                _optional_timestamp_us(
                    cutoff.event_time_watermark,
                    field="event_time_watermark",
                ),
                _timestamp_us(cutoff.health_valid_until, field="health_valid_until"),
                None
                if cutoff.parent_evidence_cutoff_id is None
                else _blob_hash(
                    cutoff.parent_evidence_cutoff_id,
                    field="parent_evidence_cutoff_id",
                ),
                receipt.global_sequence,
                _blob_hash(receipt.content_hash, field="content_hash"),
            ),
        )
        self._fault("after_cutoff_projection_insert")
        return receipt

    def append_health_policy(
        self,
        policy: PhysicalHealthPolicyV4 = REVIEWED_PHYSICAL_HEALTH_POLICY_V4,
        *,
        idempotency_key: str,
    ) -> PhysicalHealthPolicyV4:
        """Register the sole reviewed V4.3 executable health policy."""

        if not isinstance(policy, PhysicalHealthPolicyV4):
            raise CanonicalizationError("policy must be PhysicalHealthPolicyV4")
        if policy != REVIEWED_PHYSICAL_HEALTH_POLICY_V4:
            raise PhysicalProjectionV4ConflictError(
                "only the reviewed V4.3 health policy may be registered"
            )
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_PHYSICAL_HEALTH_POLICY_V4_3"
        request = _request_hash(operation, policy.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_HEALTH_POLICY,
                    str(replay["physical_health_policy_id"]),
                )
                assert isinstance(loaded, PhysicalHealthPolicyV4)
                return loaded
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(policy)
            self._connection.execute(
                """
                INSERT INTO physical_health_policies(
                    physical_health_policy_id, policy_name, interval_seconds,
                    primary_freshness_seconds, status_freshness_seconds,
                    max_clock_uncertainty_milliseconds,
                    recovery_consecutive_completed_bars, required_vintage,
                    bound_subscription_ack_required, required_status_value,
                    required_contract_type_value, state_precedence_blob,
                    blocker_recovery_rules_blob, source_receipt_sequence,
                    source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        policy.physical_health_policy_id,
                        field="physical_health_policy_id",
                    ),
                    policy.policy_name,
                    policy.interval_seconds,
                    policy.primary_freshness_seconds,
                    policy.status_freshness_seconds,
                    policy.max_clock_uncertainty_milliseconds,
                    policy.recovery_consecutive_completed_bars,
                    policy.required_vintage.value,
                    int(policy.bound_subscription_ack_required),
                    policy.required_status_value,
                    policy.required_contract_type_value,
                    canonical_json_bytes(
                        [item.value for item in policy.state_precedence]
                    ),
                    canonical_json_bytes(
                        [item.as_dict() for item in policy.blocker_recovery_rules]
                    ),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_physical_health_policy_insert")
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={"physical_health_policy_id": policy.physical_health_policy_id},
            )
            return policy

    def _health_evidence_sql(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        cutoff_global_sequence: int,
        knowledge_cutoff_ts: datetime,
    ) -> tuple[HealthEvidenceItemV4, ...]:
        """Build reducer inputs through typed indexes only."""

        scope_blob = _blob_hash(
            scope.physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        knowledge_us = _timestamp_us(knowledge_cutoff_ts, field="knowledge_cutoff_ts")
        rows = self._connection.execute(
            """
            SELECT d.scope_message_sequence, d.source_receipt_sequence,
                   d.message_disposition_id, d.disposition_kind,
                   m.adapter_policy_id, m.capture_segment_id,
                   p.classified_at_us, d.observation_revision_id,
                   r.admission_receipt_sequence, r.available_at_us
            FROM message_dispositions AS d
            JOIN physical_messages AS m
              ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
             AND m.scope_message_sequence = d.scope_message_sequence
            JOIN disposition_provenance AS p
              ON p.message_disposition_id = d.message_disposition_id
            LEFT JOIN observation_revisions AS r
              ON r.observation_revision_id = d.observation_revision_id
            WHERE d.physical_scope_manifest_id = ?
              AND d.source_receipt_sequence <= ?
            ORDER BY d.scope_message_sequence
            """,
            (scope_blob, cutoff_global_sequence),
        ).fetchall()
        evidence: list[HealthEvidenceItemV4] = []
        for row in rows:
            classified_us = int(row[6])
            if classified_us > knowledge_us:
                continue
            revision: ObservationRevisionV3 | None = None
            admission: int | None = None
            if row[7] is not None:
                if row[8] is None or row[9] is None:
                    raise PhysicalProjectionV4VerificationError(
                        "typed normalized disposition lacks its revision clocks"
                    )
                admission = int(row[8])
                if admission > cutoff_global_sequence or int(row[9]) > knowledge_us:
                    continue
                revision = self._load_record(
                    PhysicalRecordKindV4.OBSERVATION_REVISION,
                    bytes(row[7]).hex(),
                )
                assert isinstance(revision, ObservationRevisionV3)
            segment = self._load_record(
                PhysicalRecordKindV4.CAPTURE_SEGMENT,
                bytes(row[5]).hex(),
            )
            assert isinstance(segment, CaptureSegmentV3)
            evidence.append(
                HealthEvidenceItemV4(
                    scope_message_sequence=int(row[0]),
                    disposition_receipt_sequence=int(row[1]),
                    message_disposition_id=bytes(row[2]).hex(),
                    disposition_kind=str(row[3]),
                    adapter_policy_id=bytes(row[4]).hex(),
                    classified_at=_datetime_from_us(classified_us),
                    capture_segment=segment,
                    observation_revision=revision,
                    observation_admission_receipt_sequence=admission,
                )
            )
        return tuple(evidence)

    def _health_evidence_replay(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        cutoff_global_sequence: int,
        knowledge_cutoff_ts: datetime,
    ) -> tuple[HealthEvidenceItemV4, ...]:
        """Independently rebuild reducer inputs from canonical records."""

        records = self._connection.execute(
            """
            SELECT record_kind, canonical_blob, first_receipt_sequence
            FROM canonical_records
            WHERE first_receipt_sequence <= ?
            ORDER BY first_receipt_sequence
            """,
            (cutoff_global_sequence,),
        ).fetchall()
        messages: dict[str, PhysicalMessageV4] = {}
        segments: dict[str, CaptureSegmentV3] = {}
        revisions: dict[str, ObservationRevisionV3] = {}
        providers: list[ProviderMessageDispositionV3] = []
        dispositions: list[tuple[MessageDispositionV4, int]] = []
        for kind_value, blob, sequence in records:
            kind = PhysicalRecordKindV4(str(kind_value))
            record = _parse_record(kind, bytes(blob))
            if isinstance(record, PhysicalMessageV4):
                messages[record.physical_message_id] = record
            elif isinstance(record, CaptureSegmentV3):
                segments[record.capture_segment_id] = record
            elif isinstance(record, ObservationRevisionV3):
                revisions[record.observation_revision_id] = record
            elif isinstance(record, ProviderMessageDispositionV3):
                providers.append(record)
            elif (
                isinstance(record, MessageDispositionV4)
                and record.physical_scope_manifest_id
                == scope.physical_scope_manifest_id
            ):
                dispositions.append((record, int(sequence)))
        evidence: list[HealthEvidenceItemV4] = []
        for disposition, disposition_sequence in sorted(
            dispositions, key=lambda item: item[0].scope_message_sequence
        ):
            message = messages.get(disposition.physical_message_id)
            if message is None:
                raise PhysicalProjectionV4VerificationError(
                    "canonical disposition lacks its physical message"
                )
            candidates = [
                item
                for item in providers
                if item.message_receipt_id == disposition.message_receipt_id
                and item.capture_segment_id == disposition.capture_segment_id
                and item.adapter_policy_id == disposition.adapter_policy_id
                and item.raw_payload_sha256 == disposition.raw_payload_sha256
                and item.classifier_release_hash == disposition.classifier_release_hash
                and item.disposition_kind is disposition.disposition_kind
                and item.observation_revision_id
                == (
                    None
                    if not disposition.observation_revision_ids
                    else disposition.observation_revision_ids[0]
                )
                and item.observation_derivation_id
                == (
                    None
                    if not disposition.observation_derivation_ids
                    else disposition.observation_derivation_ids[0]
                )
                and item.duplicate_of_message_receipt_id
                == disposition.duplicate_of_message_receipt_id
                and item.provider_diagnostic_code
                == disposition.provider_diagnostic_code
                and item.provider_diagnostic_digest
                == disposition.provider_diagnostic_digest
            ]
            if len(candidates) != 1:
                raise PhysicalProjectionV4VerificationError(
                    "canonical disposition does not resolve exactly one classifier provenance"
                )
            provider = candidates[0]
            if provider.classified_at > knowledge_cutoff_ts:
                continue
            segment = segments.get(message.capture_segment_id)
            if segment is None:
                raise PhysicalProjectionV4VerificationError(
                    "canonical message lacks its capture segment"
                )
            revision: ObservationRevisionV3 | None = None
            admission: int | None = None
            if disposition.observation_revision_ids:
                revision = revisions.get(disposition.observation_revision_ids[0])
                if revision is None:
                    raise PhysicalProjectionV4VerificationError(
                        "canonical normalized disposition lacks its revision"
                    )
                admission = disposition_sequence
                if revision.available_at > knowledge_cutoff_ts:
                    continue
            evidence.append(
                HealthEvidenceItemV4(
                    scope_message_sequence=disposition.scope_message_sequence,
                    disposition_receipt_sequence=disposition_sequence,
                    message_disposition_id=disposition.message_disposition_id,
                    disposition_kind=disposition.disposition_kind,
                    adapter_policy_id=disposition.adapter_policy_id,
                    classified_at=provider.classified_at,
                    capture_segment=segment,
                    observation_revision=revision,
                    observation_admission_receipt_sequence=admission,
                )
            )
        return tuple(evidence)

    def _transport_authority_sql(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        cutoff_global_sequence: int,
    ) -> TransportAuthorityContextV4 | None:
        """Select the causal transport chain in the stable V4.5 identity domain."""

        scope_blob = _blob_hash(
            scope.physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        adapter_blob = _blob_hash(
            scope.primary_adapter_policy_id, field="adapter_policy_id"
        )
        session_row = self._connection.execute(
            """
            SELECT transport_session_id, transport_subscription_policy_id,
                   capture_partition_id, collector_boot_id,
                   connection_generation, source_receipt_sequence
            FROM transport_session_attestations
            WHERE physical_scope_manifest_id = ?
              AND adapter_policy_id = ?
              AND source_receipt_sequence <= ?
            ORDER BY source_receipt_sequence DESC LIMIT 1
            """,
            (scope_blob, adapter_blob, cutoff_global_sequence),
        ).fetchone()
        if session_row is None:
            return None
        session_blob = bytes(session_row[0])
        control_fence_row = self._connection.execute(
            """
            SELECT max(source_receipt_sequence) FROM (
                SELECT source_receipt_sequence
                FROM inbound_rfc_control_triggers
                WHERE transport_session_id = ?
                  AND opcode = 'CLOSE'
                  AND source_receipt_sequence <= ?
                UNION ALL
                SELECT source_receipt_sequence
                FROM inbound_websocket_protocol_failures
                WHERE transport_session_id = ?
                  AND source_receipt_sequence <= ?
                UNION ALL
                SELECT source_receipt_sequence
                FROM outbound_control_intents
                WHERE transport_session_id = ?
                  AND fences_session_authority = 1
                  AND source_receipt_sequence <= ?
                UNION ALL
                SELECT source_receipt_sequence
                FROM outbound_control_dispatch_results
                WHERE transport_session_id = ?
                  AND disposition = 'UNKNOWN_DELIVERY'
                  AND source_receipt_sequence <= ?
                UNION ALL
                SELECT p.source_receipt_sequence
                FROM outbound_control_write_permits_consumed AS p
                WHERE p.transport_session_id = ?
                  AND p.source_receipt_sequence <= ?
                  AND NOT EXISTS (
                      SELECT 1 FROM outbound_control_dispatch_results AS d
                      WHERE d.permit_id = p.permit_id
                        AND d.source_receipt_sequence <= ?
                  )
            )
            """,
            (
                session_blob,
                cutoff_global_sequence,
                session_blob,
                cutoff_global_sequence,
                session_blob,
                cutoff_global_sequence,
                session_blob,
                cutoff_global_sequence,
                session_blob,
                cutoff_global_sequence,
                cutoff_global_sequence,
            ),
        ).fetchone()
        if control_fence_row is not None and control_fence_row[0] is not None:
            return None
        intent_row = self._connection.execute(
            """
            SELECT outbound_subscription_intent_id,
                   subscription_manifest_hash, source_receipt_sequence
            FROM outbound_subscription_intents
            WHERE transport_session_id = ?
              AND source_receipt_sequence <= ?
            ORDER BY source_receipt_sequence DESC LIMIT 1
            """,
            (session_blob, cutoff_global_sequence),
        ).fetchone()
        intent_id: str | None = None
        intent_sequence: int | None = None
        manifest_hash = _NO_SUBSCRIPTION_INTENT_MANIFEST_HASH_V4
        binding_id: str | None = None
        bound_disposition_id: str | None = None
        binding_sequence: int | None = None
        if intent_row is not None:
            intent_blob = bytes(intent_row[0])
            intent_id = intent_blob.hex()
            manifest_hash = bytes(intent_row[1]).hex()
            intent_sequence = int(intent_row[2])
            binding_row = self._connection.execute(
                """
                SELECT subscription_ack_binding_id, message_disposition_id,
                       source_receipt_sequence
                FROM subscription_ack_bindings
                WHERE outbound_subscription_intent_id = ?
                  AND source_receipt_sequence <= ?
                """,
                (intent_blob, cutoff_global_sequence),
            ).fetchone()
            if binding_row is not None:
                binding_id = bytes(binding_row[0]).hex()
                bound_disposition_id = bytes(binding_row[1]).hex()
                binding_sequence = int(binding_row[2])
        termination_row = self._connection.execute(
            """
            SELECT transport_session_termination_id, source_receipt_sequence
            FROM transport_session_terminations
            WHERE transport_session_id = ?
              AND source_receipt_sequence <= ?
            """,
            (session_blob, cutoff_global_sequence),
        ).fetchone()
        return TransportAuthorityContextV4(
            physical_scope_manifest_id=scope.physical_scope_manifest_id,
            adapter_policy_id=scope.primary_adapter_policy_id,
            transport_subscription_policy_id=bytes(session_row[1]).hex(),
            transport_session_id=session_blob.hex(),
            transport_session_receipt_sequence=int(session_row[5]),
            capture_partition_id=bytes(session_row[2]).hex(),
            collector_boot_id=str(session_row[3]),
            connection_generation=int(session_row[4]),
            subscription_manifest_hash=manifest_hash,
            outbound_subscription_intent_id=intent_id,
            outbound_subscription_intent_receipt_sequence=intent_sequence,
            subscription_ack_binding_id=binding_id,
            bound_message_disposition_id=bound_disposition_id,
            subscription_ack_binding_receipt_sequence=binding_sequence,
            transport_session_termination_id=(
                None if termination_row is None else bytes(termination_row[0]).hex()
            ),
            transport_session_termination_receipt_sequence=(
                None if termination_row is None else int(termination_row[1])
            ),
        )

    def _transport_authority_replay(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        cutoff_global_sequence: int,
    ) -> TransportAuthorityContextV4 | None:
        """Independently select the same chain from canonical record bytes."""

        records = self._connection.execute(
            """
            SELECT record_kind, canonical_blob, first_receipt_sequence
            FROM canonical_records
            WHERE first_receipt_sequence <= ?
              AND record_kind IN (
                  'TRANSPORT_SESSION_ATTESTATION_V4',
                  'INBOUND_WEBSOCKET_PROTOCOL_FAILURE_V4',
                  'INBOUND_RFC_CONTROL_TRIGGER_V4',
                  'OUTBOUND_CONTROL_INTENT_V4',
                  'OUTBOUND_CONTROL_WRITE_PERMIT_CONSUMED_V4',
                  'OUTBOUND_CONTROL_DISPATCH_RESULT_V4',
                  'OUTBOUND_SUBSCRIPTION_INTENT_V4',
                  'SUBSCRIPTION_ACK_BINDING_V4',
                  'TRANSPORT_SESSION_TERMINATION_V4'
              )
            ORDER BY first_receipt_sequence
            """,
            (cutoff_global_sequence,),
        ).fetchall()
        decoded = [
            (str(kind), _parse_mapping(bytes(blob), context=str(kind)), int(sequence))
            for kind, blob, sequence in records
        ]
        sessions = [
            (payload, sequence)
            for kind, payload, sequence in decoded
            if kind == "TRANSPORT_SESSION_ATTESTATION_V4"
            and payload.get("physical_scope_manifest_id")
            == scope.physical_scope_manifest_id
            and payload.get("adapter_policy_id") == scope.primary_adapter_policy_id
        ]
        if not sessions:
            return None
        session, session_sequence = sessions[-1]
        session_id = str(session["transport_session_id"])
        if any(
            (
                kind == "INBOUND_RFC_CONTROL_TRIGGER_V4"
                and payload.get("transport_session_id") == session_id
                and payload.get("opcode") == "CLOSE"
            )
            or (
                kind == "INBOUND_WEBSOCKET_PROTOCOL_FAILURE_V4"
                and payload.get("transport_session_id") == session_id
            )
            or (
                kind == "OUTBOUND_CONTROL_INTENT_V4"
                and payload.get("transport_session_id") == session_id
                and payload.get("fences_session_authority") is True
            )
            or (
                kind == "OUTBOUND_CONTROL_DISPATCH_RESULT_V4"
                and payload.get("transport_session_id") == session_id
                and payload.get("disposition") == "UNKNOWN_DELIVERY"
            )
            for kind, payload, _ in decoded
        ):
            return None
        permits = {
            str(payload.get("permit_id"))
            for kind, payload, _ in decoded
            if kind == "OUTBOUND_CONTROL_WRITE_PERMIT_CONSUMED_V4"
            and payload.get("transport_session_id") == session_id
        }
        completed_permits = {
            str(payload.get("permit_id"))
            for kind, payload, _ in decoded
            if kind == "OUTBOUND_CONTROL_DISPATCH_RESULT_V4"
            and payload.get("transport_session_id") == session_id
        }
        if permits - completed_permits:
            return None
        intents = [
            (payload, sequence)
            for kind, payload, sequence in decoded
            if kind == "OUTBOUND_SUBSCRIPTION_INTENT_V4"
            and payload.get("transport_session_id") == session_id
        ]
        intent: Mapping[str, Any] | None = None
        intent_sequence: int | None = None
        binding: Mapping[str, Any] | None = None
        binding_sequence: int | None = None
        manifest_hash = _NO_SUBSCRIPTION_INTENT_MANIFEST_HASH_V4
        if intents:
            intent, intent_sequence = intents[-1]
            manifest_hash = str(intent["subscription_manifest_hash"])
            bindings = [
                (payload, sequence)
                for kind, payload, sequence in decoded
                if kind == "SUBSCRIPTION_ACK_BINDING_V4"
                and payload.get("outbound_subscription_intent_id")
                == intent.get("outbound_subscription_intent_id")
            ]
            if bindings:
                binding, binding_sequence = bindings[-1]
        terminations = [
            (payload, sequence)
            for kind, payload, sequence in decoded
            if kind == "TRANSPORT_SESSION_TERMINATION_V4"
            and payload.get("transport_session_id") == session_id
        ]
        termination, termination_sequence = (
            (None, None) if not terminations else terminations[-1]
        )
        return TransportAuthorityContextV4(
            physical_scope_manifest_id=scope.physical_scope_manifest_id,
            adapter_policy_id=scope.primary_adapter_policy_id,
            transport_subscription_policy_id=str(
                session["transport_subscription_policy_id"]
            ),
            transport_session_id=session_id,
            transport_session_receipt_sequence=session_sequence,
            capture_partition_id=str(session["capture_partition_id"]),
            collector_boot_id=str(session["collector_boot_id"]),
            connection_generation=int(session["connection_generation"]),
            subscription_manifest_hash=manifest_hash,
            outbound_subscription_intent_id=(
                None
                if intent is None
                else str(intent["outbound_subscription_intent_id"])
            ),
            outbound_subscription_intent_receipt_sequence=intent_sequence,
            subscription_ack_binding_id=(
                None if binding is None else str(binding["subscription_ack_binding_id"])
            ),
            bound_message_disposition_id=(
                None if binding is None else str(binding["message_disposition_id"])
            ),
            subscription_ack_binding_receipt_sequence=binding_sequence,
            transport_session_termination_id=(
                None
                if termination is None
                else str(termination["transport_session_termination_id"])
            ),
            transport_session_termination_receipt_sequence=termination_sequence,
        )

    def _derive_health_result(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        cutoff_global_sequence: int,
        knowledge_cutoff_ts: datetime,
        covered_message_count: int,
    ) -> HealthReductionResultV4:
        sql_evidence = self._health_evidence_sql(
            scope=scope,
            cutoff_global_sequence=cutoff_global_sequence,
            knowledge_cutoff_ts=knowledge_cutoff_ts,
        )
        replay_evidence = self._health_evidence_replay(
            scope=scope,
            cutoff_global_sequence=cutoff_global_sequence,
            knowledge_cutoff_ts=knowledge_cutoff_ts,
        )
        if sql_evidence != replay_evidence:
            raise PhysicalProjectionV4VerificationError(
                "typed health evidence differs from canonical replay"
            )
        sql_transport = self._transport_authority_sql(
            scope=scope,
            cutoff_global_sequence=cutoff_global_sequence,
        )
        replay_transport = self._transport_authority_replay(
            scope=scope,
            cutoff_global_sequence=cutoff_global_sequence,
        )
        if sql_transport != replay_transport:
            raise PhysicalProjectionV4VerificationError(
                "typed transport authority differs from canonical replay"
            )
        sql_result = reduce_physical_health_v4(
            policy=REVIEWED_PHYSICAL_HEALTH_POLICY_V4,
            scope=scope,
            evidence=sql_evidence,
            transport_authority=sql_transport,
            covered_message_count=covered_message_count,
            knowledge_cutoff_ts=knowledge_cutoff_ts,
        )
        replay_result = reduce_physical_health_v4(
            policy=REVIEWED_PHYSICAL_HEALTH_POLICY_V4,
            scope=scope,
            evidence=replay_evidence,
            transport_authority=replay_transport,
            covered_message_count=covered_message_count,
            knowledge_cutoff_ts=knowledge_cutoff_ts,
        )
        if sql_result != replay_result:
            raise PhysicalProjectionV4VerificationError(
                "health reducer differs from canonical replay oracle"
            )
        return sql_result

    def _append_health_transition_record(
        self, transition: PhysicalHealthTransitionV4
    ) -> PhysicalProjectionReceiptV4:
        receipt = self._append_record(transition)
        self._connection.execute(
            """
            INSERT INTO physical_health_transitions(
                physical_health_transition_id, physical_scope_manifest_id,
                ledger_id, physical_health_policy_id, evidence_cutoff_id,
                cutoff_global_sequence, cutoff_receipt_hash,
                knowledge_cutoff_us, tree_size, tree_root,
                parent_physical_health_transition_id, prior_health,
                current_health, health_reason_codes_blob,
                unresolved_blocker_count, unresolved_blocker_root,
                recovery_consecutive_completed_bars,
                current_required_status_revision_id,
                current_transport_session_id,
                current_outbound_subscription_intent_id,
                current_subscription_ack_binding_id,
                event_time_watermark_us, health_valid_until_us,
                evaluated_at_us, source_receipt_sequence, source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                _blob_hash(
                    transition.physical_health_transition_id,
                    field="physical_health_transition_id",
                ),
                _blob_hash(
                    transition.physical_scope_manifest_id,
                    field="physical_scope_manifest_id",
                ),
                _blob_hash(transition.ledger_id, field="ledger_id"),
                _blob_hash(
                    transition.physical_health_policy_id,
                    field="physical_health_policy_id",
                ),
                _blob_hash(transition.evidence_cutoff_id, field="evidence_cutoff_id"),
                transition.cutoff_global_sequence,
                _blob_hash(transition.cutoff_receipt_hash, field="cutoff_receipt_hash"),
                _timestamp_us(
                    transition.knowledge_cutoff_ts, field="knowledge_cutoff_ts"
                ),
                transition.tree_size,
                _blob_hash(transition.tree_root, field="tree_root"),
                None
                if transition.parent_physical_health_transition_id is None
                else _blob_hash(
                    transition.parent_physical_health_transition_id,
                    field="parent_physical_health_transition_id",
                ),
                transition.prior_health.value,
                transition.current_health.value,
                canonical_json_bytes(list(transition.health_reason_codes)),
                transition.unresolved_blocker_count,
                _blob_hash(
                    transition.unresolved_blocker_root,
                    field="unresolved_blocker_root",
                ),
                transition.recovery_consecutive_completed_bars,
                None
                if transition.current_required_status_revision_id is None
                else _blob_hash(
                    transition.current_required_status_revision_id,
                    field="current_required_status_revision_id",
                ),
                None
                if transition.current_transport_session_id is None
                else _blob_hash(
                    transition.current_transport_session_id,
                    field="current_transport_session_id",
                ),
                None
                if transition.current_outbound_subscription_intent_id is None
                else _blob_hash(
                    transition.current_outbound_subscription_intent_id,
                    field="current_outbound_subscription_intent_id",
                ),
                None
                if transition.current_subscription_ack_binding_id is None
                else _blob_hash(
                    transition.current_subscription_ack_binding_id,
                    field="current_subscription_ack_binding_id",
                ),
                _optional_timestamp_us(
                    transition.event_time_watermark,
                    field="event_time_watermark",
                ),
                _timestamp_us(
                    transition.health_valid_until, field="health_valid_until"
                ),
                _timestamp_us(transition.evaluated_at, field="evaluated_at"),
                receipt.global_sequence,
                _blob_hash(receipt.content_hash, field="content_hash"),
            ),
        )
        self._fault("after_physical_health_transition_insert")
        return receipt

    def append_derived_health_cutoff(
        self,
        *,
        physical_scope_manifest_id: str,
        knowledge_cutoff_ts: datetime | str,
        idempotency_key: str,
    ) -> tuple[EvidenceCutoffV4, PhysicalHealthTransitionV4]:
        """Atomically derive and persist one authoritative V4.3 health tick.

        ``knowledge_cutoff_ts`` is also the explicit health evaluation clock.
        Advancing it with no new messages therefore deterministically evaluates
        staleness, while preventing a caller from excluding newly knowable facts
        through a second, older information clock.
        """

        scope_id = canonical_hash(
            physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        knowledge = utc_datetime(knowledge_cutoff_ts, field="knowledge_cutoff_ts")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_DERIVED_HEALTH_CUTOFF_V4_3"
        request_payload = {
            "knowledge_cutoff_ts": utc_iso(knowledge),
            "physical_scope_manifest_id": scope_id,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                cutoff = self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_CUTOFF,
                    str(replay["evidence_cutoff_id"]),
                )
                transition = self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_HEALTH_TRANSITION,
                    str(replay["physical_health_transition_id"]),
                )
                assert isinstance(cutoff, EvidenceCutoffV4)
                assert isinstance(transition, PhysicalHealthTransitionV4)
                return cutoff, transition
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST, scope_id
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            if scope.health_policy_id != REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4:
                raise PhysicalProjectionV4ConflictError(
                    "scope is not bound to the reviewed V4.3 health policy"
                )
            self._validated_scope_adapter_policies(scope)
            if knowledge < scope.frozen_at:
                raise PhysicalProjectionV4ConflictError(
                    "health knowledge cutoff precedes the frozen scope"
                )
            policy_row = self._connection.execute(
                """
                SELECT 1 FROM physical_health_policies
                WHERE physical_health_policy_id = ?
                """,
                (
                    _blob_hash(
                        REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4,
                        field="physical_health_policy_id",
                    ),
                ),
            ).fetchone()
            if policy_row is None:
                raise PhysicalProjectionV4ConflictError(
                    "reviewed V4.3 health policy is not registered"
                )
            scope_blob = _blob_hash(scope_id, field="physical_scope_manifest_id")
            raw_count, raw_high = self._coverage_stats(
                self._connection, table="physical_messages", scope_blob=scope_blob
            )
            disposition_count, disposition_high = self._coverage_stats(
                self._connection,
                table="message_dispositions",
                scope_blob=scope_blob,
            )
            head_count, head_high = self._coverage_stats(
                self._connection, table="tree_heads", scope_blob=scope_blob
            )
            missing = self._connection.execute(
                """
                SELECT m.scope_message_sequence
                FROM physical_messages AS m
                LEFT JOIN message_dispositions AS d
                  ON d.physical_scope_manifest_id = m.physical_scope_manifest_id
                 AND d.scope_message_sequence = m.scope_message_sequence
                WHERE m.physical_scope_manifest_id = ?
                  AND d.scope_message_sequence IS NULL
                LIMIT 1
                """,
                (scope_blob,),
            ).fetchone()
            if not (
                missing is None
                and raw_count
                == raw_high
                == disposition_count
                == disposition_high
                == head_count
                == head_high
            ):
                raise PhysicalProjectionV4ConflictError(
                    "derived health cutoff requires gap-free exact-one coverage"
                )
            cutoff_sequence, cutoff_hash = self._last_receipt()
            if cutoff_sequence < 1:
                raise PhysicalProjectionV4ConflictError(
                    "derived health cutoff has no predecessor receipt"
                )
            head: EvidenceTreeHeadV4 | None = None
            if raw_count:
                head_row = self._connection.execute(
                    """
                    SELECT evidence_tree_head_id FROM tree_heads
                    WHERE physical_scope_manifest_id = ? AND tree_size = ?
                    """,
                    (scope_blob, head_high),
                ).fetchone()
                if head_row is None:
                    raise PhysicalProjectionV4ConflictError(
                        "derived health cutoff tree head is missing"
                    )
                head = self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_TREE_HEAD,
                    bytes(head_row[0]).hex(),
                )
                assert isinstance(head, EvidenceTreeHeadV4)
                frontier = self._frontier(scope_blob)
                if (
                    frontier.tree_size != head.tree_size
                    or frontier.root_hash.hex() != head.tree_root
                ):
                    raise PhysicalProjectionV4VerificationError(
                        "derived health tree differs from stored-hash frontier"
                    )
            result = self._derive_health_result(
                scope=scope,
                cutoff_global_sequence=cutoff_sequence,
                knowledge_cutoff_ts=knowledge,
                covered_message_count=raw_count,
            )
            watermark_us = self._derived_event_time_watermark_us(
                self._connection,
                scope_blob=scope_blob,
                primary_adapter_policy_blob=_blob_hash(
                    scope.primary_adapter_policy_id,
                    field="primary_adapter_policy_id",
                ),
                source_member_key_blob=_blob_hash(
                    scope.source_member_key, field="source_member_key"
                ),
                cutoff_global_sequence=cutoff_sequence,
                knowledge_cutoff_us=_timestamp_us(
                    knowledge, field="knowledge_cutoff_ts"
                ),
            )
            if watermark_us != _optional_timestamp_us(
                result.event_time_watermark, field="event_time_watermark"
            ):
                raise PhysicalProjectionV4VerificationError(
                    "health reducer watermark differs from indexed causal heads"
                )
            parent_cutoff_row = self._connection.execute(
                """
                SELECT evidence_cutoff_id FROM evidence_cutoffs
                WHERE physical_scope_manifest_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (scope_blob,),
            ).fetchone()
            parent_cutoff_id = (
                None if parent_cutoff_row is None else bytes(parent_cutoff_row[0]).hex()
            )
            if parent_cutoff_id is not None:
                parent_cutoff = self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_CUTOFF, parent_cutoff_id
                )
                assert isinstance(parent_cutoff, EvidenceCutoffV4)
                if knowledge < parent_cutoff.knowledge_cutoff_ts:
                    raise PhysicalProjectionV4ConflictError(
                        "derived health knowledge cutoff regresses"
                    )
            cutoff = EvidenceCutoffV4(
                physical_scope_manifest_id=scope_id,
                ledger_id=self.ledger_id,
                evidence_tree_head_id=(
                    None if head is None else head.evidence_tree_head_id
                ),
                tree_size=raw_count,
                tree_root=(
                    rfc9162_empty_root().hex() if head is None else head.tree_root
                ),
                cutoff_global_sequence=cutoff_sequence,
                cutoff_receipt_hash=cutoff_hash.hex(),
                knowledge_cutoff_ts=knowledge,
                raw_message_count=raw_count,
                raw_message_high_water_sequence=raw_high,
                disposition_count=disposition_count,
                disposition_high_water_sequence=disposition_high,
                current_required_status_revision_id=(
                    result.current_required_status_revision_id
                ),
                vintage=result.vintage,
                health=result.health,
                health_reason_codes=result.reason_codes,
                event_time_watermark=result.event_time_watermark,
                health_valid_until=result.health_valid_until,
                parent_evidence_cutoff_id=parent_cutoff_id,
            )
            first_sequence = cutoff_sequence + 1
            self._append_cutoff_record(cutoff)
            parent_transition_row = self._connection.execute(
                """
                SELECT physical_health_transition_id
                FROM physical_health_transitions
                WHERE physical_scope_manifest_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (scope_blob,),
            ).fetchone()
            parent_transition: PhysicalHealthTransitionV4 | None = None
            if parent_transition_row is not None:
                parent_transition = self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_HEALTH_TRANSITION,
                    bytes(parent_transition_row[0]).hex(),
                )
                assert isinstance(parent_transition, PhysicalHealthTransitionV4)
            transition = PhysicalHealthTransitionV4(
                physical_scope_manifest_id=scope_id,
                ledger_id=self.ledger_id,
                physical_health_policy_id=REVIEWED_PHYSICAL_HEALTH_POLICY_ID_V4,
                evidence_cutoff_id=cutoff.evidence_cutoff_id,
                cutoff_global_sequence=cutoff.cutoff_global_sequence,
                cutoff_receipt_hash=cutoff.cutoff_receipt_hash,
                knowledge_cutoff_ts=cutoff.knowledge_cutoff_ts,
                tree_size=cutoff.tree_size,
                tree_root=cutoff.tree_root,
                parent_physical_health_transition_id=(
                    None
                    if parent_transition is None
                    else parent_transition.physical_health_transition_id
                ),
                prior_health=(
                    PrefixHealth.BOOTSTRAPPING
                    if parent_transition is None
                    else parent_transition.current_health
                ),
                current_health=result.health,
                health_reason_codes=result.reason_codes,
                unresolved_blocker_count=len(result.unresolved_blocker_ids),
                unresolved_blocker_root=health_blocker_root_v4(
                    result.unresolved_blocker_ids
                ),
                recovery_consecutive_completed_bars=(
                    result.recovery_consecutive_completed_bars
                ),
                current_required_status_revision_id=(
                    result.current_required_status_revision_id
                ),
                current_transport_session_id=(result.current_transport_session_id),
                current_outbound_subscription_intent_id=(
                    result.current_outbound_subscription_intent_id
                ),
                current_subscription_ack_binding_id=(
                    result.current_subscription_ack_binding_id
                ),
                event_time_watermark=result.event_time_watermark,
                health_valid_until=result.health_valid_until,
                evaluated_at=knowledge,
            )
            if parent_transition is not None:
                try:
                    validate_health_transition_successor_v4(
                        parent_transition, transition
                    )
                except CanonicalizationError as exc:
                    raise PhysicalProjectionV4ConflictError(
                        "derived health transition does not extend its live chain"
                    ) from exc
            self._append_health_transition_record(transition)
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={
                    "evidence_cutoff_id": cutoff.evidence_cutoff_id,
                    "physical_health_transition_id": (
                        transition.physical_health_transition_id
                    ),
                },
            )
            return cutoff, transition

    def append_cutoff(
        self,
        *,
        physical_scope_manifest_id: str,
        knowledge_cutoff_ts: datetime | str,
        vintage: PhysicalVintage | str,
        health: PrefixHealth | str,
        health_reason_codes: Sequence[str],
        health_valid_until: datetime | str,
        idempotency_key: str,
        current_required_status_revision_id: str | None = None,
        event_time_watermark: datetime | str | None = None,
    ) -> EvidenceCutoffV4:
        """Append a non-authoritative research/selection cutoff.

        V4.3 deliberately forbids callers from using this compatibility path to
        assert ``HEALTHY``.  Authoritative health is emitted only by the
        deterministic reducer together with a replay-verifiable health
        transition.  Keeping non-healthy cutoffs here preserves historical and
        research selection without allowing this method to mint trading
        authority.
        """
        scope_id = canonical_hash(
            physical_scope_manifest_id, field="physical_scope_manifest_id"
        )
        reasons = canonical_reason_codes(
            health_reason_codes, field="health_reason_codes"
        )
        request_payload = {
            "current_required_status_revision_id": (
                current_required_status_revision_id
            ),
            "event_time_watermark": "DERIVED_FROM_CAUSAL_HEADS",
            "health": health.value if isinstance(health, PrefixHealth) else health,
            "health_reason_codes": list(reasons),
            "health_valid_until": utc_iso(
                utc_datetime(health_valid_until, field="health_valid_until")
            ),
            "knowledge_cutoff_ts": utc_iso(
                utc_datetime(knowledge_cutoff_ts, field="knowledge_cutoff_ts")
            ),
            "physical_scope_manifest_id": scope_id,
            "vintage": vintage.value
            if isinstance(vintage, PhysicalVintage)
            else vintage,
        }
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_EVIDENCE_CUTOFF_V4"
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                return self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_CUTOFF,
                    str(replay["evidence_cutoff_id"]),
                )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST, scope_id
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            scope_blob = _blob_hash(scope_id, field="physical_scope_manifest_id")
            raw_count, raw_high = self._coverage_stats(
                self._connection, table="physical_messages", scope_blob=scope_blob
            )
            disposition_count, disposition_high = self._coverage_stats(
                self._connection,
                table="message_dispositions",
                scope_blob=scope_blob,
            )
            head_count, head_high = self._coverage_stats(
                self._connection, table="tree_heads", scope_blob=scope_blob
            )
            normalized_health = (
                health if isinstance(health, PrefixHealth) else PrefixHealth(health)
            )
            if normalized_health is PrefixHealth.HEALTHY:
                raise PhysicalProjectionV4ConflictError(
                    "caller-selected HEALTHY is forbidden; use the deterministic "
                    "V4 health reducer"
                )
            missing = self._connection.execute(
                """
                SELECT m.scope_message_sequence
                FROM physical_messages AS m
                LEFT JOIN message_dispositions AS d
                  ON d.physical_scope_manifest_id = m.physical_scope_manifest_id
                 AND d.scope_message_sequence = m.scope_message_sequence
                WHERE m.physical_scope_manifest_id = ?
                  AND d.scope_message_sequence IS NULL
                LIMIT 1
                """,
                (scope_blob,),
            ).fetchone()
            exact_coverage = (
                missing is None
                and raw_count
                == raw_high
                == disposition_count
                == disposition_high
                == head_count
                == head_high
            )
            if not exact_coverage:
                raise PhysicalProjectionV4ConflictError(
                    "cutoff requires gap-free exact-one message/disposition/head coverage"
                )
            head: EvidenceTreeHeadV4 | None
            if raw_count == 0:
                if normalized_health is not PrefixHealth.BOOTSTRAPPING:
                    raise PhysicalProjectionV4ConflictError(
                        "empty cutoff must be BOOTSTRAPPING"
                    )
                if event_time_watermark is not None:
                    raise PhysicalProjectionV4ConflictError(
                        "empty cutoff cannot claim an event-time watermark"
                    )
                head = None
                tree_size = 0
                tree_root = rfc9162_empty_root().hex()
            else:
                head_row = self._connection.execute(
                    """
                    SELECT evidence_tree_head_id FROM tree_heads
                    WHERE physical_scope_manifest_id = ? AND tree_size = ?
                    """,
                    (scope_blob, head_high),
                ).fetchone()
                if head_row is None:
                    raise PhysicalProjectionV4ConflictError(
                        "covered cutoff tree head is missing"
                    )
                head = self._load_record(
                    PhysicalRecordKindV4.EVIDENCE_TREE_HEAD,
                    bytes(head_row[0]).hex(),
                )
                assert isinstance(head, EvidenceTreeHeadV4)
                frontier = self._frontier(scope_blob)
                if frontier.tree_size != head.tree_size or frontier.root_hash.hex() != (
                    head.tree_root
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "cutoff tree head differs from stored-hash frontier"
                    )
                tree_size = head.tree_size
                tree_root = head.tree_root
            if normalized_health is PrefixHealth.HEALTHY:
                blocker = self._connection.execute(
                    """
                    SELECT 1 FROM message_dispositions
                    WHERE physical_scope_manifest_id = ? AND health_severity = 'HALT'
                    LIMIT 1
                    """,
                    (scope_blob,),
                ).fetchone()
                if blocker is not None:
                    raise PhysicalProjectionV4ConflictError(
                        "first-slice store cannot mark a scope healthy after a HALT disposition"
                    )
                if (
                    scope.required_status_adapter_policy_id is not None
                    and current_required_status_revision_id is None
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "healthy scope requires its current status revision"
                    )
            if current_required_status_revision_id is not None:
                if scope.required_status_adapter_policy_id is None:
                    raise PhysicalProjectionV4ConflictError(
                        "scope without a required status policy cannot claim a status revision"
                    )
                status_blob = _blob_hash(
                    current_required_status_revision_id,
                    field="current_required_status_revision_id",
                )
                if (
                    self._connection.execute(
                        """
                    SELECT 1
                    FROM message_dispositions AS d
                    JOIN physical_messages AS m
                      ON m.physical_scope_manifest_id = d.physical_scope_manifest_id
                     AND m.scope_message_sequence = d.scope_message_sequence
                    WHERE d.physical_scope_manifest_id = ?
                      AND d.observation_revision_id = ?
                      AND m.adapter_policy_id = ?
                    LIMIT 1
                    """,
                        (
                            scope_blob,
                            status_blob,
                            _blob_hash(
                                scope.required_status_adapter_policy_id,
                                field="required_status_adapter_policy_id",
                            ),
                        ),
                    ).fetchone()
                    is None
                ):
                    raise PhysicalProjectionV4ConflictError(
                        "status revision is not an output of the required status policy"
                    )
            cutoff_sequence, cutoff_hash = self._last_receipt()
            if cutoff_sequence < 1:
                raise PhysicalProjectionV4ConflictError(
                    "cutoff has no predecessor receipt"
                )
            knowledge_cutoff_us = _timestamp_us(
                knowledge_cutoff_ts, field="knowledge_cutoff_ts"
            )
            derived_watermark_us = self._derived_event_time_watermark_us(
                self._connection,
                scope_blob=scope_blob,
                primary_adapter_policy_blob=_blob_hash(
                    scope.primary_adapter_policy_id,
                    field="primary_adapter_policy_id",
                ),
                source_member_key_blob=_blob_hash(
                    scope.source_member_key,
                    field="source_member_key",
                ),
                cutoff_global_sequence=cutoff_sequence,
                knowledge_cutoff_us=knowledge_cutoff_us,
            )
            asserted_watermark_us = _optional_timestamp_us(
                event_time_watermark, field="event_time_watermark"
            )
            if (
                asserted_watermark_us is not None
                and asserted_watermark_us != derived_watermark_us
            ):
                raise PhysicalProjectionV4ConflictError(
                    "event-time watermark differs from causal observation heads"
                )
            derived_watermark = (
                None
                if derived_watermark_us is None
                else _datetime_from_us(derived_watermark_us)
            )
            parent_row = self._connection.execute(
                """
                SELECT evidence_cutoff_id FROM evidence_cutoffs
                WHERE physical_scope_manifest_id = ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (scope_blob,),
            ).fetchone()
            cutoff = EvidenceCutoffV4(
                physical_scope_manifest_id=scope_id,
                ledger_id=self.ledger_id,
                evidence_tree_head_id=(
                    None if head is None else head.evidence_tree_head_id
                ),
                tree_size=tree_size,
                tree_root=tree_root,
                cutoff_global_sequence=cutoff_sequence,
                cutoff_receipt_hash=cutoff_hash.hex(),
                knowledge_cutoff_ts=knowledge_cutoff_ts,
                raw_message_count=raw_count,
                raw_message_high_water_sequence=raw_high,
                disposition_count=disposition_count,
                disposition_high_water_sequence=disposition_high,
                current_required_status_revision_id=(
                    current_required_status_revision_id
                ),
                vintage=vintage,
                health=health,
                health_reason_codes=reasons,
                event_time_watermark=derived_watermark,
                health_valid_until=health_valid_until,
                parent_evidence_cutoff_id=(
                    None if parent_row is None else bytes(parent_row[0]).hex()
                ),
            )
            first_sequence = cutoff_sequence + 1
            self._append_cutoff_record(cutoff)
            result = {"evidence_cutoff_id": cutoff.evidence_cutoff_id}
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return cutoff

    def append_protocol_binding(
        self,
        binding: PhysicalProtocolBindingV4,
        *,
        idempotency_key: str,
    ) -> PhysicalProtocolBindingV4:
        if not isinstance(binding, PhysicalProtocolBindingV4):
            raise CanonicalizationError("binding must be PhysicalProtocolBindingV4")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_PHYSICAL_PROTOCOL_BINDING_V4_1"
        request = _request_hash(operation, binding.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                return self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_PROTOCOL_BINDING,
                    str(replay["physical_protocol_binding_id"]),
                )
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                binding.physical_scope_manifest_id,
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            if (
                binding.source_member_key != scope.source_member_key
                or binding.calendar_manifest_id != scope.calendar_manifest_id
                or binding.selection_query_spec_id != scope.selection_query_spec_id
            ):
                raise PhysicalProjectionV4ConflictError(
                    "protocol binding differs from its physical scope"
                )
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(binding)
            self._connection.execute(
                """
                INSERT INTO physical_protocol_bindings(
                    physical_protocol_binding_id,
                    physical_scope_manifest_id, protocol_manifest_id,
                    source_manifest_id, calendar_manifest_id,
                    feature_schema_id, dependency_slot_id, source_member_id,
                    source_member_key, observation_selection_policy_id,
                    selection_query_spec_id, selection_mode,
                    anchor_lag_intervals, requested_count,
                    maximum_age_seconds, continuity_policy,
                    interval_seconds, tie_break_policy, frozen_at_us,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        binding.physical_protocol_binding_id,
                        field="physical_protocol_binding_id",
                    ),
                    _blob_hash(
                        binding.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(
                        binding.protocol_manifest_id, field="protocol_manifest_id"
                    ),
                    _blob_hash(binding.source_manifest_id, field="source_manifest_id"),
                    _blob_hash(
                        binding.calendar_manifest_id, field="calendar_manifest_id"
                    ),
                    _blob_hash(binding.feature_schema_id, field="feature_schema_id"),
                    _blob_hash(binding.dependency_slot_id, field="dependency_slot_id"),
                    _blob_hash(binding.source_member_id, field="source_member_id"),
                    _blob_hash(binding.source_member_key, field="source_member_key"),
                    _blob_hash(
                        binding.observation_selection_policy_id,
                        field="observation_selection_policy_id",
                    ),
                    _blob_hash(
                        binding.selection_query_spec_id,
                        field="selection_query_spec_id",
                    ),
                    selection_mode_name_v4(binding.selection_mode),
                    binding.anchor_lag_intervals,
                    binding.requested_count,
                    binding.maximum_age_seconds,
                    binding.continuity_policy.value,
                    binding.interval_seconds,
                    binding.tie_break_policy,
                    _timestamp_us(binding.frozen_at, field="frozen_at"),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_protocol_binding_insert")
            result = {
                "physical_protocol_binding_id": (binding.physical_protocol_binding_id)
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return binding

    def append_information_set(
        self,
        information_set: InformationSetV3,
        *,
        idempotency_key: str,
    ) -> InformationSetV3:
        """Persist the exact logical decision input needed for V4 gate replay."""

        if not isinstance(information_set, InformationSetV3):
            raise CanonicalizationError("information_set must be InformationSetV3")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "APPEND_INFORMATION_SET_V4_2"
        request = _request_hash(operation, information_set.as_dict())
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.INFORMATION_SET,
                    str(replay["information_set_id"]),
                )
                assert isinstance(loaded, InformationSetV3)
                return loaded
            first_sequence = self._last_receipt()[0] + 1
            receipt = self._append_record(information_set)
            self._connection.execute(
                """
                INSERT INTO information_sets(
                    information_set_id, record_hash,
                    asset_id, venue_id, contract_id, timeframe_id,
                    observation_cutoff_us, assembled_at_us,
                    source_manifest_id, protocol_manifest_id,
                    calendar_manifest_id, feature_schema_id,
                    vintage_class, point_in_time_certified,
                    dependency_count, dependency_root,
                    state_dependency_count, state_dependency_root,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        information_set.information_set_id,
                        field="information_set_id",
                    ),
                    _blob_hash(information_set.record_hash, field="record_hash"),
                    information_set.asset_id,
                    information_set.venue_id,
                    information_set.contract_id,
                    information_set.timeframe_id,
                    _timestamp_us(
                        information_set.observation_cutoff_ts,
                        field="observation_cutoff_ts",
                    ),
                    _timestamp_us(
                        information_set.assembled_at,
                        field="assembled_at",
                    ),
                    _blob_hash(
                        information_set.source_manifest_id,
                        field="source_manifest_id",
                    ),
                    _blob_hash(
                        information_set.protocol_manifest_id,
                        field="protocol_manifest_id",
                    ),
                    _blob_hash(
                        information_set.calendar_manifest_id,
                        field="calendar_manifest_id",
                    ),
                    _blob_hash(
                        information_set.feature_schema_id,
                        field="feature_schema_id",
                    ),
                    information_set.vintage_class.value,
                    int(information_set.point_in_time_certified),
                    len(information_set.dependencies),
                    _information_dependency_root(information_set),
                    len(information_set.state_dependencies),
                    _state_dependency_root(information_set),
                    receipt.global_sequence,
                    _blob_hash(receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_information_set_projection_insert")
            result = {"information_set_id": information_set.information_set_id}
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return information_set

    @staticmethod
    def _selection_target_close_us(
        *, binding: PhysicalProtocolBindingV4, observation_cutoff_us: int
    ) -> int:
        interval_us = binding.interval_seconds * 1_000_000
        completed_intervals = observation_cutoff_us // interval_us
        return (completed_intervals - binding.anchor_lag_intervals) * interval_us

    def _select_observations_sql(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        binding: PhysicalProtocolBindingV4,
        cutoff: EvidenceCutoffV4,
    ) -> tuple[tuple[str, ...], tuple[str, ...]]:
        knowledge_us = _timestamp_us(
            cutoff.knowledge_cutoff_ts, field="knowledge_cutoff_ts"
        )
        target_close_us = self._selection_target_close_us(
            binding=binding, observation_cutoff_us=knowledge_us
        )
        exact = binding.selection_mode is DependencySelectionMode.EXACT_EVENT
        limit = 2 if exact else binding.requested_count
        close_predicate = "r.bar_close_us = ?" if exact else "r.bar_close_us <= ?"
        rows = self._connection.execute(
            f"""
            SELECT r.observation_revision_id, r.bar_open_us, r.bar_close_us,
                   r.available_at_us, r.admission_receipt_sequence
            FROM observation_revisions AS r
                 INDEXED BY observation_revision_select_complete_bar_v4
            WHERE r.physical_scope_manifest_id = ?
              AND r.adapter_policy_id = ?
              AND r.source_member_key = ?
              AND r.observation_kind = 'BAR'
              AND r.completion_state = 'COMPLETE'
              AND r.timeframe_id = '1m'
              AND r.bar_close_us - r.bar_open_us = 60000000
              AND r.bar_open_us % 60000000 = 0
              AND r.admission_receipt_sequence <= ?
              AND r.available_at_us <= ?
              AND r.bar_close_us <= ?
              AND {close_predicate}
              AND NOT EXISTS (
                  SELECT 1 FROM observation_revisions AS successor
                  WHERE successor.parent_observation_revision_id =
                            r.observation_revision_id
                    AND successor.admission_receipt_sequence <= ?
                    AND successor.available_at_us <= ?
              )
            ORDER BY r.bar_close_us DESC, r.available_at_us DESC,
                     r.admission_receipt_sequence DESC,
                     r.observation_revision_id DESC
            LIMIT ?
            """,
            (
                _blob_hash(
                    scope.physical_scope_manifest_id,
                    field="physical_scope_manifest_id",
                ),
                _blob_hash(
                    scope.primary_adapter_policy_id,
                    field="primary_adapter_policy_id",
                ),
                _blob_hash(binding.source_member_key, field="source_member_key"),
                cutoff.cutoff_global_sequence,
                knowledge_us,
                knowledge_us,
                target_close_us,
                cutoff.cutoff_global_sequence,
                knowledge_us,
                limit,
            ),
        ).fetchall()
        reasons: list[str] = []
        selected_rows: list[tuple[Any, ...]] = []
        if exact:
            if len(rows) != 1:
                reasons.append("EXACT_EVENT_MISSING_OR_AMBIGUOUS")
            else:
                selected_rows = list(rows)
        elif binding.selection_mode is DependencySelectionMode.LATEST_AVAILABLE_ASOF:
            if not rows:
                reasons.append("LATEST_AVAILABLE_NOT_PROVABLE")
            else:
                selected_rows = list(rows[:1])
        else:
            selected_rows = list(reversed(rows))
            if len(selected_rows) != binding.requested_count:
                reasons.append("TRAILING_WINDOW_SHORT")
            elif binding.continuity_policy is ContinuityPolicy.STRICT_INTERVAL_GRID:
                if any(
                    int(left[2]) != int(right[1])
                    for left, right in zip(selected_rows, selected_rows[1:])
                ):
                    reasons.append("TRAILING_WINDOW_GAPPED")
        if selected_rows and not reasons:
            oldest_close_us = min(int(row[2]) for row in selected_rows)
            if knowledge_us - oldest_close_us > binding.maximum_age_seconds * 1_000_000:
                reasons.append("SELECTED_OBSERVATION_TOO_OLD")
        if reasons:
            return (), tuple(sorted(set(reasons)))
        selected_rows.sort(
            key=lambda row: (int(row[2]), int(row[3]), int(row[4]), bytes(row[0]))
        )
        return tuple(bytes(row[0]).hex() for row in selected_rows), ()

    def _select_observations_replay(
        self,
        *,
        scope: PhysicalScopeManifestV4,
        binding: PhysicalProtocolBindingV4,
        cutoff: EvidenceCutoffV4,
    ) -> tuple[tuple[str, ...], tuple[str, ...]]:
        revisions: list[ObservationRevisionV3] = []
        for (canonical_blob,) in self._connection.execute(
            """
            SELECT canonical_blob FROM canonical_records
            WHERE record_kind = ? ORDER BY first_receipt_sequence
            """,
            (PhysicalRecordKindV4.OBSERVATION_REVISION.value,),
        ):
            item = ObservationRevisionV3.from_mapping(
                _parse_mapping(bytes(canonical_blob), context="ObservationRevisionV3")
            )
            if (
                item.source_member_key == scope.source_member_key
                and item.instrument_mapping_id == scope.instrument_mapping_id
                and item.asset_id == scope.asset_id
                and item.venue_id == scope.venue_id
                and item.concrete_contract_id == scope.concrete_contract_id
                and item.timeframe_id == scope.timeframe_id
                and item.adapter_policy_id == scope.primary_adapter_policy_id
            ):
                revisions.append(item)
        admission_by_revision: dict[str, int] = {}
        for identity_blob, canonical_blob, first_sequence in self._connection.execute(
            """
            SELECT identity_id, canonical_blob, first_receipt_sequence
            FROM canonical_records WHERE record_kind = ?
            ORDER BY first_receipt_sequence
            """,
            (PhysicalRecordKindV4.MESSAGE_DISPOSITION.value,),
        ):
            disposition = MessageDispositionV4.from_mapping(
                _parse_mapping(bytes(canonical_blob), context="MessageDispositionV4")
            )
            if disposition.observation_revision_ids:
                revision_id = disposition.observation_revision_ids[0]
                if revision_id in admission_by_revision:
                    raise PhysicalProjectionV4VerificationError(
                        "canonical replay found two admissions for one revision"
                    )
                if bytes(identity_blob).hex() != disposition.message_disposition_id:
                    raise PhysicalProjectionV4VerificationError(
                        "canonical disposition identity metadata differs"
                    )
                admission_by_revision[revision_id] = int(first_sequence)
        knowledge = cutoff.knowledge_cutoff_ts
        eligible: list[ObservationRevisionV3] = []
        for revision in revisions:
            admission = admission_by_revision.get(revision.observation_revision_id)
            if admission is None:
                raise PhysicalProjectionV4VerificationError(
                    "canonical observation has no admission disposition"
                )
            if (
                admission <= cutoff.cutoff_global_sequence
                and revision.available_at <= knowledge
            ):
                eligible.append(revision)
        superseded = {
            revision.parent_observation_revision_id
            for revision in eligible
            if revision.parent_observation_revision_id is not None
        }
        target_close_us = self._selection_target_close_us(
            binding=binding,
            observation_cutoff_us=_timestamp_us(knowledge, field="knowledge_cutoff_ts"),
        )
        candidates = [
            revision
            for revision in eligible
            if revision.observation_revision_id not in superseded
            and revision.observation_kind is ObservationKind.BAR
            and revision.completion_state.value == "COMPLETE"
            and revision.timeframe_id == "1m"
            and revision.bar_open_ts is not None
            and revision.bar_close_ts is not None
            and (revision.bar_close_ts - revision.bar_open_ts).total_seconds() == 60
            and _timestamp_us(revision.bar_open_ts, field="bar_open_ts") % 60_000_000
            == 0
            and revision.bar_close_ts <= knowledge
            and _timestamp_us(revision.bar_close_ts, field="bar_close_ts")
            <= target_close_us
        ]
        candidates.sort(
            key=lambda revision: (
                revision.bar_close_ts,
                revision.available_at,
                admission_by_revision[revision.observation_revision_id],
                bytes.fromhex(revision.observation_revision_id),
            )
        )
        reasons: list[str] = []
        selected: list[ObservationRevisionV3] = []
        if binding.selection_mode is DependencySelectionMode.EXACT_EVENT:
            exact = [
                revision
                for revision in candidates
                if _timestamp_us(revision.bar_close_ts, field="bar_close_ts")
                == target_close_us
            ]
            if len(exact) != 1:
                reasons.append("EXACT_EVENT_MISSING_OR_AMBIGUOUS")
            else:
                selected = exact
        elif binding.selection_mode is DependencySelectionMode.LATEST_AVAILABLE_ASOF:
            if not candidates:
                reasons.append("LATEST_AVAILABLE_NOT_PROVABLE")
            else:
                selected = [candidates[-1]]
        else:
            selected = candidates[-binding.requested_count :]
            if len(selected) != binding.requested_count:
                reasons.append("TRAILING_WINDOW_SHORT")
            elif any(
                left.bar_close_ts != right.bar_open_ts
                for left, right in zip(selected, selected[1:])
            ):
                reasons.append("TRAILING_WINDOW_GAPPED")
        if selected and not reasons:
            oldest_close = min(
                revision.bar_close_ts
                for revision in selected
                if revision.bar_close_ts is not None
            )
            if (knowledge - oldest_close).total_seconds() > binding.maximum_age_seconds:
                reasons.append("SELECTED_OBSERVATION_TOO_OLD")
        if reasons:
            return (), tuple(sorted(set(reasons)))
        return tuple(revision.observation_revision_id for revision in selected), ()

    def select_observations(
        self,
        *,
        physical_protocol_binding_id: str,
        evidence_cutoff_id: str,
        observation_cutoff_ts: datetime | str,
        computed_at: datetime | str,
        idempotency_key: str,
    ) -> tuple[ObservationSelectionProofV4, SelectionResultChunkV4 | None]:
        binding_id = canonical_hash(
            physical_protocol_binding_id, field="physical_protocol_binding_id"
        )
        cutoff_id = canonical_hash(evidence_cutoff_id, field="evidence_cutoff_id")
        observation_cutoff = utc_datetime(
            observation_cutoff_ts, field="observation_cutoff_ts"
        )
        computed = utc_datetime(computed_at, field="computed_at")
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "SELECT_OBSERVATIONS_V4_1"
        request_payload = {
            "computed_at": utc_iso(computed),
            "evidence_cutoff_id": cutoff_id,
            "observation_cutoff_ts": utc_iso(observation_cutoff),
            "physical_protocol_binding_id": binding_id,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                proof = self._load_record(
                    PhysicalRecordKindV4.OBSERVATION_SELECTION_PROOF,
                    str(replay["observation_selection_proof_id"]),
                )
                assert isinstance(proof, ObservationSelectionProofV4)
                chunk = (
                    None
                    if proof.selection_result_chunk_id is None
                    else self._load_record(
                        PhysicalRecordKindV4.SELECTION_RESULT_CHUNK,
                        proof.selection_result_chunk_id,
                    )
                )
                assert chunk is None or isinstance(chunk, SelectionResultChunkV4)
                return proof, chunk
            binding = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_PROTOCOL_BINDING, binding_id
            )
            cutoff = self._load_record(PhysicalRecordKindV4.EVIDENCE_CUTOFF, cutoff_id)
            assert isinstance(binding, PhysicalProtocolBindingV4)
            assert isinstance(cutoff, EvidenceCutoffV4)
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                binding.physical_scope_manifest_id,
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            if cutoff.physical_scope_manifest_id != scope.physical_scope_manifest_id:
                raise PhysicalProjectionV4ConflictError(
                    "selection cutoff differs from protocol-bound scope"
                )
            if cutoff.ledger_id != self.ledger_id:
                raise PhysicalProjectionV4ConflictError(
                    "selection cutoff belongs to another ledger"
                )
            if observation_cutoff != cutoff.knowledge_cutoff_ts:
                raise PhysicalProjectionV4ConflictError(
                    "V4.1 selector requires the exact evidence knowledge cutoff"
                )
            if computed < cutoff.knowledge_cutoff_ts:
                raise PhysicalProjectionV4ConflictError(
                    "selection was computed before its evidence cutoff"
                )
            sql_result = self._select_observations_sql(
                scope=scope, binding=binding, cutoff=cutoff
            )
            replay_result = self._select_observations_replay(
                scope=scope, binding=binding, cutoff=cutoff
            )
            if sql_result != replay_result:
                raise PhysicalProjectionV4VerificationError(
                    "typed SQL selector differs from independent canonical replay"
                )
            selected_ids, reasons = sql_result
            chunk = (
                None
                if not selected_ids
                else SelectionResultChunkV4(
                    physical_scope_manifest_id=scope.physical_scope_manifest_id,
                    physical_protocol_binding_id=binding.physical_protocol_binding_id,
                    evidence_cutoff_id=cutoff.evidence_cutoff_id,
                    ordered_observation_revision_ids=selected_ids,
                )
            )
            proof = ObservationSelectionProofV4(
                physical_scope_manifest_id=scope.physical_scope_manifest_id,
                ledger_id=self.ledger_id,
                evidence_cutoff_id=cutoff.evidence_cutoff_id,
                cutoff_global_sequence=cutoff.cutoff_global_sequence,
                cutoff_receipt_hash=cutoff.cutoff_receipt_hash,
                knowledge_cutoff_ts=cutoff.knowledge_cutoff_ts,
                physical_protocol_binding_id=binding.physical_protocol_binding_id,
                selection_query_spec_id=binding.selection_query_spec_id,
                observation_selection_policy_id=(
                    binding.observation_selection_policy_id
                ),
                dependency_slot_id=binding.dependency_slot_id,
                source_member_id=binding.source_member_id,
                source_member_key=binding.source_member_key,
                observation_cutoff_ts=observation_cutoff,
                status=(
                    SelectionStatus.SELECTED
                    if chunk is not None
                    else SelectionStatus.ABSTAIN
                ),
                selected_result_count=(
                    0 if chunk is None else chunk.selected_result_count
                ),
                selected_result_root=(
                    rfc9162_empty_root().hex()
                    if chunk is None
                    else chunk.selected_result_root
                ),
                selection_result_chunk_id=(
                    None if chunk is None else chunk.selection_result_chunk_id
                ),
                abstention_reason_codes=reasons,
                computed_at=computed,
            )
            validate_observation_selection_proof_v4(
                proof=proof, binding=binding, chunk=chunk
            )
            first_sequence = self._last_receipt()[0] + 1
            if chunk is not None:
                chunk_receipt = self._append_record(chunk)
                chunk_blob = _blob_hash(
                    chunk.selection_result_chunk_id,
                    field="selection_result_chunk_id",
                )
                self._connection.execute(
                    """
                    INSERT INTO selection_result_chunks(
                        selection_result_chunk_id, physical_scope_manifest_id,
                        physical_protocol_binding_id, evidence_cutoff_id,
                        result_count, result_root, source_receipt_sequence,
                        source_content_hash
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        chunk_blob,
                        _blob_hash(
                            chunk.physical_scope_manifest_id,
                            field="physical_scope_manifest_id",
                        ),
                        _blob_hash(
                            chunk.physical_protocol_binding_id,
                            field="physical_protocol_binding_id",
                        ),
                        _blob_hash(
                            chunk.evidence_cutoff_id, field="evidence_cutoff_id"
                        ),
                        chunk.selected_result_count,
                        _blob_hash(
                            chunk.selected_result_root, field="selected_result_root"
                        ),
                        chunk_receipt.global_sequence,
                        _blob_hash(chunk_receipt.content_hash, field="content_hash"),
                    ),
                )
                self._connection.executemany(
                    """
                    INSERT INTO selection_result_items(
                        selection_result_chunk_id, ordinal,
                        observation_revision_id
                    ) VALUES(?, ?, ?)
                    """,
                    tuple(
                        (
                            chunk_blob,
                            ordinal,
                            _blob_hash(revision_id, field="observation_revision_id"),
                        )
                        for ordinal, revision_id in enumerate(
                            chunk.ordered_observation_revision_ids
                        )
                    ),
                )
                self._fault("after_selection_result_chunk_insert")
            proof_receipt = self._append_record(proof)
            self._connection.execute(
                """
                INSERT INTO observation_selection_proofs(
                    observation_selection_proof_id,
                    physical_scope_manifest_id, ledger_id,
                    evidence_cutoff_id, cutoff_global_sequence,
                    cutoff_receipt_hash, knowledge_cutoff_us,
                    physical_protocol_binding_id, selection_query_spec_id,
                    observation_selection_policy_id, dependency_slot_id,
                    source_member_id, source_member_key,
                    observation_cutoff_us, status, selected_result_count,
                    selected_result_root, selection_result_chunk_id,
                    abstention_reason_codes_blob, computed_at_us,
                    source_receipt_sequence, source_content_hash
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    _blob_hash(
                        proof.observation_selection_proof_id,
                        field="observation_selection_proof_id",
                    ),
                    _blob_hash(
                        proof.physical_scope_manifest_id,
                        field="physical_scope_manifest_id",
                    ),
                    _blob_hash(proof.ledger_id, field="ledger_id"),
                    _blob_hash(proof.evidence_cutoff_id, field="evidence_cutoff_id"),
                    proof.cutoff_global_sequence,
                    _blob_hash(proof.cutoff_receipt_hash, field="cutoff_receipt_hash"),
                    _timestamp_us(
                        proof.knowledge_cutoff_ts, field="knowledge_cutoff_ts"
                    ),
                    _blob_hash(
                        proof.physical_protocol_binding_id,
                        field="physical_protocol_binding_id",
                    ),
                    _blob_hash(
                        proof.selection_query_spec_id,
                        field="selection_query_spec_id",
                    ),
                    _blob_hash(
                        proof.observation_selection_policy_id,
                        field="observation_selection_policy_id",
                    ),
                    _blob_hash(proof.dependency_slot_id, field="dependency_slot_id"),
                    _blob_hash(proof.source_member_id, field="source_member_id"),
                    _blob_hash(proof.source_member_key, field="source_member_key"),
                    _timestamp_us(
                        proof.observation_cutoff_ts, field="observation_cutoff_ts"
                    ),
                    proof.status.value,
                    proof.selected_result_count,
                    _blob_hash(
                        proof.selected_result_root, field="selected_result_root"
                    ),
                    None
                    if proof.selection_result_chunk_id is None
                    else _blob_hash(
                        proof.selection_result_chunk_id,
                        field="selection_result_chunk_id",
                    ),
                    canonical_json_bytes(list(proof.abstention_reason_codes)),
                    _timestamp_us(proof.computed_at, field="computed_at"),
                    proof_receipt.global_sequence,
                    _blob_hash(proof_receipt.content_hash, field="content_hash"),
                ),
            )
            self._fault("after_observation_selection_proof_insert")
            result = {
                "observation_selection_proof_id": (
                    proof.observation_selection_proof_id
                ),
                "selection_result_chunk_id": (proof.selection_result_chunk_id),
            }
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result=result,
            )
            return proof, chunk

    def _gate_proof_ids(
        self,
        *,
        information_set: InformationSetV3,
        evaluation_receipt_sequence: int,
    ) -> tuple[str, ...]:
        rows = self._connection.execute(
            """
            SELECT p.observation_selection_proof_id
            FROM observation_selection_proofs AS p
            JOIN physical_protocol_bindings AS b
              ON b.physical_protocol_binding_id =
                 p.physical_protocol_binding_id
            WHERE p.observation_cutoff_us = ?
              AND p.source_receipt_sequence <= ?
              AND b.protocol_manifest_id = ?
              AND b.source_manifest_id = ?
              AND b.calendar_manifest_id = ?
              AND b.feature_schema_id = ?
            ORDER BY b.dependency_slot_id, b.source_member_id,
                     p.observation_selection_proof_id
            """,
            (
                _timestamp_us(
                    information_set.observation_cutoff_ts,
                    field="observation_cutoff_ts",
                ),
                evaluation_receipt_sequence,
                _blob_hash(
                    information_set.protocol_manifest_id,
                    field="protocol_manifest_id",
                ),
                _blob_hash(
                    information_set.source_manifest_id,
                    field="source_manifest_id",
                ),
                _blob_hash(
                    information_set.calendar_manifest_id,
                    field="calendar_manifest_id",
                ),
                _blob_hash(
                    information_set.feature_schema_id,
                    field="feature_schema_id",
                ),
            ),
        ).fetchall()
        return tuple(bytes(row[0]).hex() for row in rows)

    def _derive_physical_gate(
        self,
        *,
        information_set: InformationSetV3,
        gate_stage: PhysicalGateStage,
        evaluated_at: datetime,
        evaluation_receipt_sequence: int,
        evaluation_receipt_hash: str,
    ) -> tuple[PhysicalEvidenceGateV4, tuple[str, ...], tuple[str, ...]]:
        """Derive a gate from records visible at one immutable receipt boundary."""

        reasons: set[str] = set()
        if gate_stage is PhysicalGateStage.EXECUTION_BAR:
            reasons.add("EXECUTION_GATE_BRIDGE_NOT_IMPLEMENTED")
        if (
            information_set.vintage_class is not VintageClass.LIVE_FIRST_SEEN_CERTIFIED
            or not information_set.point_in_time_certified
            or information_set.certification_blockers
        ):
            reasons.add("INFORMATION_SET_NOT_CERTIFIED_LIVE")
        if information_set.data_quality_flags:
            reasons.add("INFORMATION_SET_DATA_QUALITY_BLOCKED")
        if information_set.state_dependencies:
            reasons.add("STATE_DEPENDENCIES_NOT_PHYSICALLY_PROVED")
        if information_set.universe_snapshot_id is not None:
            reasons.add("UNIVERSE_SNAPSHOT_NOT_PHYSICALLY_PROVED")
        if not information_set.dependencies:
            reasons.add("INFORMATION_SET_HAS_NO_SOURCE_DEPENDENCIES")
        if evaluated_at < information_set.assembled_at:
            reasons.add("GATE_EVALUATION_PRECEDES_INFORMATION_SET")

        proof_ids = self._gate_proof_ids(
            information_set=information_set,
            evaluation_receipt_sequence=evaluation_receipt_sequence,
        )
        expected_groups: dict[tuple[str, str], list[Any]] = {}
        for dependency in information_set.dependencies:
            expected_groups.setdefault(
                (dependency.dependency_slot_id, dependency.source_member_id), []
            ).append(dependency)
        proof_groups: dict[tuple[str, str], list[ObservationSelectionProofV4]] = {}
        proof_records: list[ObservationSelectionProofV4] = []
        proof_scopes: dict[str, PhysicalScopeManifestV4] = {}
        cutoff_ids_by_scope: dict[str, set[str]] = {}
        for proof_id in proof_ids:
            proof = self._load_record(
                PhysicalRecordKindV4.OBSERVATION_SELECTION_PROOF, proof_id
            )
            assert isinstance(proof, ObservationSelectionProofV4)
            proof_records.append(proof)
            proof_groups.setdefault(
                (proof.dependency_slot_id, proof.source_member_id), []
            ).append(proof)
            binding = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_PROTOCOL_BINDING,
                proof.physical_protocol_binding_id,
            )
            cutoff = self._load_record(
                PhysicalRecordKindV4.EVIDENCE_CUTOFF, proof.evidence_cutoff_id
            )
            assert isinstance(binding, PhysicalProtocolBindingV4)
            assert isinstance(cutoff, EvidenceCutoffV4)
            scope = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_SCOPE_MANIFEST,
                proof.physical_scope_manifest_id,
            )
            assert isinstance(scope, PhysicalScopeManifestV4)
            proof_scopes[scope.physical_scope_manifest_id] = scope
            cutoff_ids_by_scope.setdefault(scope.physical_scope_manifest_id, set()).add(
                cutoff.evidence_cutoff_id
            )
            try:
                chunk = (
                    None
                    if proof.selection_result_chunk_id is None
                    else self._load_record(
                        PhysicalRecordKindV4.SELECTION_RESULT_CHUNK,
                        proof.selection_result_chunk_id,
                    )
                )
                assert chunk is None or isinstance(chunk, SelectionResultChunkV4)
                validate_observation_selection_proof_v4(
                    proof=proof, binding=binding, chunk=chunk
                )
            except (CanonicalizationError, AssertionError):
                reasons.add("SELECTION_PROOF_CONTRACT_INVALID")
                chunk = None
            if (
                binding.protocol_manifest_id != information_set.protocol_manifest_id
                or binding.source_manifest_id != information_set.source_manifest_id
                or binding.calendar_manifest_id != information_set.calendar_manifest_id
                or binding.feature_schema_id != information_set.feature_schema_id
            ):
                reasons.add("PROTOCOL_BINDING_MANIFEST_MISMATCH")
            if (
                scope.asset_id != information_set.asset_id
                or scope.venue_id != information_set.venue_id
                or scope.concrete_contract_id != information_set.contract_id
                or scope.timeframe_id != information_set.timeframe_id
                or scope.source_member_key != binding.source_member_key
            ):
                reasons.add("PHYSICAL_SCOPE_INFORMATION_SET_MISMATCH")
            if (
                proof.observation_cutoff_ts != information_set.observation_cutoff_ts
                or proof.knowledge_cutoff_ts != information_set.observation_cutoff_ts
                or cutoff.knowledge_cutoff_ts != information_set.observation_cutoff_ts
            ):
                reasons.add("SELECTION_CUTOFF_MISMATCH")
            if proof.computed_at > evaluated_at:
                reasons.add("GATE_EVALUATION_PRECEDES_SELECTION_PROOF")
            if proof.status is not SelectionStatus.SELECTED or chunk is None:
                reasons.add("SELECTION_PROOF_ABSTAINED")

        if set(proof_groups) != set(expected_groups):
            reasons.add("PROOF_GROUP_SET_MISMATCH")
        if any(len(values) != 1 for values in proof_groups.values()):
            reasons.add("PROOF_GROUP_AMBIGUOUS")
        if any(len(values) != 1 for values in cutoff_ids_by_scope.values()):
            reasons.add("DECISION_CUTOFF_AMBIGUOUS")
        for group, dependencies in expected_groups.items():
            proofs = proof_groups.get(group, [])
            if len(proofs) != 1:
                continue
            proof = proofs[0]
            if proof.selection_result_chunk_id is None:
                continue
            chunk = self._load_record(
                PhysicalRecordKindV4.SELECTION_RESULT_CHUNK,
                proof.selection_result_chunk_id,
            )
            assert isinstance(chunk, SelectionResultChunkV4)
            expected_revision_ids = {
                dependency.observation_revision_id for dependency in dependencies
            }
            if set(chunk.ordered_observation_revision_ids) != expected_revision_ids:
                reasons.add("SELECTED_DEPENDENCY_SET_MISMATCH")
                continue
            for dependency in dependencies:
                revision = self._load_record(
                    PhysicalRecordKindV4.OBSERVATION_REVISION,
                    dependency.observation_revision_id,
                )
                assert isinstance(revision, ObservationRevisionV3)
                try:
                    validate_dependency_against_observation(dependency, revision)
                except CanonicalizationError:
                    reasons.add("DEPENDENCY_PHYSICAL_VALUE_MISMATCH")
                if (
                    revision.source_member_key
                    != self._load_record(
                        PhysicalRecordKindV4.PHYSICAL_PROTOCOL_BINDING,
                        proof.physical_protocol_binding_id,
                    ).source_member_key
                    or revision.asset_id != information_set.asset_id
                    or revision.venue_id != information_set.venue_id
                    or revision.concrete_contract_id != information_set.contract_id
                    or revision.timeframe_id != information_set.timeframe_id
                ):
                    reasons.add("DEPENDENCY_PHYSICAL_SCOPE_MISMATCH")

        decision_transitions: dict[str, PhysicalHealthTransitionV4] = {}
        for proof in proof_records:
            row = self._connection.execute(
                """
                SELECT physical_health_transition_id
                FROM physical_health_transitions
                WHERE evidence_cutoff_id = ?
                  AND source_receipt_sequence <= ?
                """,
                (
                    _blob_hash(proof.evidence_cutoff_id, field="evidence_cutoff_id"),
                    evaluation_receipt_sequence,
                ),
            ).fetchone()
            if row is None:
                reasons.add("DECISION_HEALTH_TRANSITION_MISSING")
                continue
            transition = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_HEALTH_TRANSITION,
                bytes(row[0]).hex(),
            )
            assert isinstance(transition, PhysicalHealthTransitionV4)
            decision_transitions[transition.physical_scope_manifest_id] = transition
            decision_use_time = max(information_set.assembled_at, proof.computed_at)
            if (
                transition.current_health is not PrefixHealth.HEALTHY
                or transition.knowledge_cutoff_ts
                != information_set.observation_cutoff_ts
                or transition.health_valid_until <= decision_use_time
                or transition.physical_scope_manifest_id
                != proof.physical_scope_manifest_id
            ):
                reasons.add("DECISION_HEALTH_NOT_ELIGIBLE")

        current_transitions: dict[str, PhysicalHealthTransitionV4] = {}
        for scope_id, _scope in sorted(proof_scopes.items()):
            row = self._connection.execute(
                """
                SELECT physical_health_transition_id
                FROM physical_health_transitions
                WHERE physical_scope_manifest_id = ?
                  AND source_receipt_sequence <= ?
                ORDER BY source_receipt_sequence DESC LIMIT 1
                """,
                (
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                ),
            ).fetchone()
            if row is None:
                reasons.add("CURRENT_HEALTH_TRANSITION_MISSING")
                continue
            transition = self._load_record(
                PhysicalRecordKindV4.PHYSICAL_HEALTH_TRANSITION,
                bytes(row[0]).hex(),
            )
            assert isinstance(transition, PhysicalHealthTransitionV4)
            current_transitions[scope_id] = transition
            if (
                transition.current_health is not PrefixHealth.HEALTHY
                or transition.evaluated_at > evaluated_at
                or transition.health_valid_until <= evaluated_at
            ):
                reasons.add("CURRENT_HEALTH_NOT_ELIGIBLE")
            control_fence_receipt = self._connection.execute(
                """
                SELECT max(source_receipt_sequence) FROM (
                    SELECT source_receipt_sequence
                    FROM inbound_rfc_control_triggers
                    WHERE transport_session_id = (
                        SELECT transport_session_id
                        FROM transport_session_attestations
                        WHERE physical_scope_manifest_id = ?
                          AND source_receipt_sequence <= ?
                        ORDER BY source_receipt_sequence DESC LIMIT 1
                    )
                      AND opcode = 'CLOSE'
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM outbound_control_intents
                    WHERE transport_session_id = (
                        SELECT transport_session_id
                        FROM transport_session_attestations
                        WHERE physical_scope_manifest_id = ?
                          AND source_receipt_sequence <= ?
                        ORDER BY source_receipt_sequence DESC LIMIT 1
                    )
                      AND fences_session_authority = 1
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM outbound_control_dispatch_results
                    WHERE transport_session_id = (
                        SELECT transport_session_id
                        FROM transport_session_attestations
                        WHERE physical_scope_manifest_id = ?
                          AND source_receipt_sequence <= ?
                        ORDER BY source_receipt_sequence DESC LIMIT 1
                    )
                      AND disposition = 'UNKNOWN_DELIVERY'
                      AND source_receipt_sequence <= ?
                )
                """,
                (
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    evaluation_receipt_sequence,
                ),
            ).fetchone()[0]
            if control_fence_receipt is not None:
                reasons.add("TRANSPORT_CONTROL_FENCED")
            newer_provider_evidence = self._connection.execute(
                """
                SELECT max(source_receipt_sequence) FROM (
                    SELECT source_receipt_sequence
                    FROM physical_messages
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM message_dispositions
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM transport_session_attestations
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM outbound_subscription_intents
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM subscription_ack_bindings
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM transport_session_terminations
                    WHERE physical_scope_manifest_id = ?
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM inbound_rfc_control_triggers
                    WHERE physical_scope_manifest_id = ?
                      AND opcode = 'CLOSE'
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT source_receipt_sequence
                    FROM outbound_control_intents
                    WHERE physical_scope_manifest_id = ?
                      AND fences_session_authority = 1
                      AND source_receipt_sequence <= ?
                    UNION ALL
                    SELECT d.source_receipt_sequence
                    FROM outbound_control_dispatch_results AS d
                    JOIN outbound_control_intents AS i
                      ON i.outbound_control_intent_id =
                         d.outbound_control_intent_id
                    WHERE i.physical_scope_manifest_id = ?
                      AND d.disposition = 'UNKNOWN_DELIVERY'
                      AND d.source_receipt_sequence <= ?
                )
                """,
                (
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                    _blob_hash(scope_id, field="physical_scope_manifest_id"),
                    evaluation_receipt_sequence,
                ),
            ).fetchone()[0]
            if (
                newer_provider_evidence is not None
                and int(newer_provider_evidence) > transition.cutoff_global_sequence
            ):
                reasons.add("CURRENT_HEALTH_LAGS_PROVIDER_EVIDENCE")

        decision_order = tuple(
            transition.physical_health_transition_id
            for _, transition in sorted(decision_transitions.items())
        )
        current_order = tuple(
            transition.physical_health_transition_id
            for _, transition in sorted(current_transitions.items())
            if transition.physical_health_transition_id not in decision_order
        )
        health_ids = decision_order + current_order
        if not proof_ids:
            reasons.add("NO_V4_SELECTION_PROOFS")
        if not health_ids:
            reasons.add("NO_V4_HEALTH_TRANSITIONS")
        verdict = (
            PhysicalGateVerdict.PASS if not reasons else PhysicalGateVerdict.ABSTAIN
        )
        if verdict is PhysicalGateVerdict.PASS:
            valid_until = min(
                transition.health_valid_until
                for transition in current_transitions.values()
            )
        else:
            valid_until = evaluated_at + timedelta(microseconds=1)
        gate = PhysicalEvidenceGateV4(
            physical_gate_policy_id=V4_PHYSICAL_GATE_POLICY_ID,
            gate_stage=gate_stage,
            ledger_id=self.ledger_id,
            information_set_id=information_set.information_set_id,
            information_set_record_hash=information_set.record_hash,
            observation_cutoff_ts=information_set.observation_cutoff_ts,
            evaluation_receipt_sequence=evaluation_receipt_sequence,
            evaluation_receipt_hash=evaluation_receipt_hash,
            proof_link_count=len(proof_ids),
            proof_link_root=gate_proof_link_root_v4(proof_ids),
            health_link_count=len(health_ids),
            health_link_root=gate_health_link_root_v4(health_ids),
            verdict=verdict,
            abstention_reason_codes=tuple(reasons),
            evaluated_at=evaluated_at,
            valid_until=valid_until,
        )
        return gate, proof_ids, health_ids

    def _append_physical_gate_record(
        self,
        *,
        gate: PhysicalEvidenceGateV4,
        proof_ids: Sequence[str],
        health_ids: Sequence[str],
    ) -> PhysicalProjectionReceiptV4:
        receipt = self._append_record(gate)
        if receipt.committed_at < gate.evaluated_at:
            raise PhysicalProjectionV4ConflictError(
                "physical gate receipt clock precedes its authority evaluation"
            )
        gate_blob = _blob_hash(
            gate.physical_evidence_gate_id, field="physical_evidence_gate_id"
        )
        self._connection.execute(
            """
            INSERT INTO physical_evidence_gates(
                physical_evidence_gate_id, physical_gate_policy_id,
                gate_stage, ledger_id, information_set_id,
                information_set_record_hash, observation_cutoff_us,
                evaluation_receipt_sequence, evaluation_receipt_hash,
                proof_link_count, proof_link_root, health_link_count,
                health_link_root, verdict, abstention_reason_codes_blob,
                evaluated_at_us, valid_until_us, source_receipt_sequence,
                source_content_hash
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                gate_blob,
                _blob_hash(
                    gate.physical_gate_policy_id, field="physical_gate_policy_id"
                ),
                gate.gate_stage.value,
                _blob_hash(gate.ledger_id, field="ledger_id"),
                _blob_hash(gate.information_set_id, field="information_set_id"),
                _blob_hash(
                    gate.information_set_record_hash,
                    field="information_set_record_hash",
                ),
                _timestamp_us(
                    gate.observation_cutoff_ts, field="observation_cutoff_ts"
                ),
                gate.evaluation_receipt_sequence,
                _blob_hash(
                    gate.evaluation_receipt_hash,
                    field="evaluation_receipt_hash",
                ),
                gate.proof_link_count,
                _blob_hash(gate.proof_link_root, field="proof_link_root"),
                gate.health_link_count,
                _blob_hash(gate.health_link_root, field="health_link_root"),
                gate.verdict.value,
                canonical_json_bytes(list(gate.abstention_reason_codes)),
                _timestamp_us(gate.evaluated_at, field="evaluated_at"),
                _timestamp_us(gate.valid_until, field="valid_until"),
                receipt.global_sequence,
                _blob_hash(receipt.content_hash, field="content_hash"),
            ),
        )
        self._connection.executemany(
            """
            INSERT INTO physical_gate_proof_links(
                physical_evidence_gate_id, ordinal,
                observation_selection_proof_id
            ) VALUES(?, ?, ?)
            """,
            tuple(
                (
                    gate_blob,
                    ordinal,
                    _blob_hash(proof_id, field="observation_selection_proof_id"),
                )
                for ordinal, proof_id in enumerate(proof_ids)
            ),
        )
        self._connection.executemany(
            """
            INSERT INTO physical_gate_health_links(
                physical_evidence_gate_id, ordinal,
                physical_health_transition_id
            ) VALUES(?, ?, ?)
            """,
            tuple(
                (
                    gate_blob,
                    ordinal,
                    _blob_hash(transition_id, field="physical_health_transition_id"),
                )
                for ordinal, transition_id in enumerate(health_ids)
            ),
        )
        self._fault("after_physical_evidence_gate_insert")
        return receipt

    def evaluate_physical_gate(
        self,
        *,
        information_set_id: str,
        gate_stage: PhysicalGateStage | str,
        idempotency_key: str,
    ) -> PhysicalEvidenceGateV4:
        """Derive a local V4.3 verdict at one transaction-owned clock sample."""

        information_id = canonical_hash(information_set_id, field="information_set_id")
        try:
            stage = (
                gate_stage
                if isinstance(gate_stage, PhysicalGateStage)
                else PhysicalGateStage(gate_stage)
            )
        except (TypeError, ValueError) as exc:
            raise CanonicalizationError("unsupported physical gate stage") from exc
        key = canonical_identifier(
            idempotency_key, field="idempotency_key", maximum=256
        )
        operation = "EVALUATE_PHYSICAL_EVIDENCE_GATE_V4_2"
        request_payload = {
            "gate_stage": stage.value,
            "information_set_id": information_id,
        }
        request = _request_hash(operation, request_payload)
        with self._transaction():
            replay = self._batch_result(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
            )
            if replay is not None:
                loaded = self._load_record(
                    PhysicalRecordKindV4.PHYSICAL_EVIDENCE_GATE,
                    str(replay["physical_evidence_gate_id"]),
                )
                assert isinstance(loaded, PhysicalEvidenceGateV4)
                return loaded
            evaluated = self._now()
            information_set = self._load_record(
                PhysicalRecordKindV4.INFORMATION_SET, information_id
            )
            assert isinstance(information_set, InformationSetV3)
            if evaluated < information_set.observation_cutoff_ts:
                raise PhysicalProjectionV4ConflictError(
                    "physical gate evaluation precedes the information cutoff"
                )
            boundary_sequence, boundary_hash = self._last_receipt()
            if boundary_sequence < 1:
                raise PhysicalProjectionV4ConflictError(
                    "physical gate has no durable evaluation boundary"
                )
            gate, proof_ids, health_ids = self._derive_physical_gate(
                information_set=information_set,
                gate_stage=stage,
                evaluated_at=evaluated,
                evaluation_receipt_sequence=boundary_sequence,
                evaluation_receipt_hash=boundary_hash.hex(),
            )
            first_sequence = boundary_sequence + 1
            self._append_physical_gate_record(
                gate=gate, proof_ids=proof_ids, health_ids=health_ids
            )
            self._finish_batch(
                idempotency_key=key,
                operation=operation,
                request_hash=request,
                first_receipt_sequence=first_sequence,
                result={"physical_evidence_gate_id": gate.physical_evidence_gate_id},
            )
            return gate

    def _verify_schema(self) -> None:
        profile = self._projection_schema_profile_v4()
        integrity = self._connection.execute("PRAGMA integrity_check").fetchall()
        if integrity != [("ok",)]:
            raise PhysicalProjectionV4VerificationError(
                f"SQLite integrity_check failed: {integrity}"
            )
        if self._connection.execute("PRAGMA foreign_key_check").fetchone() is not None:
            raise PhysicalProjectionV4VerificationError(
                "SQLite foreign_key_check failed"
            )
        if (
            _schema_fingerprint(
                self._connection,
                fingerprint_domain=profile.fingerprint_domain,
            )
            != self._projection_schema_fingerprint_bytes_v4()
        ):
            raise PhysicalProjectionV4VerificationError(
                "SQLite schema differs from the certified V4 projection schema"
            )

    def _verify_receipts(self) -> tuple[int, bytes]:
        expected_sequence = 1
        previous = PHYSICAL_PROJECTION_V4_GENESIS_HASH
        previous_committed_at: datetime | None = None
        ledger_blob = _blob_hash(self.ledger_id, field="ledger_id")
        for row in self._connection.execute(
            """
            SELECT global_sequence, receipt_hash, previous_receipt_hash,
                   record_kind, identity_id, content_hash, committed_at
            FROM receipts ORDER BY global_sequence
            """
        ):
            sequence = int(row[0])
            if sequence != expected_sequence:
                raise PhysicalProjectionV4VerificationError(
                    "receipt chain contains a sequence gap"
                )
            try:
                kind = PhysicalRecordKindV4(str(row[3]))
                committed_at = utc_datetime(row[6], field="committed_at")
            except (ValueError, CanonicalizationError) as exc:
                raise PhysicalProjectionV4VerificationError(
                    "receipt contains malformed metadata"
                ) from exc
            if (
                previous_committed_at is not None
                and committed_at < previous_committed_at
            ):
                raise PhysicalProjectionV4VerificationError(
                    "receipt committed clock regresses"
                )
            identity = bytes(row[4])
            content = bytes(row[5])
            receipt_hash = bytes(row[1])
            if bytes(row[2]) != previous or receipt_hash != _receipt_hash(
                ledger_id=ledger_blob,
                sequence=sequence,
                previous_receipt_hash=previous,
                record_kind=kind,
                identity_id=identity,
                content_hash=content,
            ):
                raise PhysicalProjectionV4VerificationError(
                    "receipt hash chain is inconsistent"
                )
            previous = receipt_hash
            previous_committed_at = committed_at
            expected_sequence += 1
        return expected_sequence - 1, previous

    def _verify_canonical_records(self) -> int:
        count = 0
        max_bytes = int(
            self._connection.execute(
                "SELECT max_object_bytes FROM projection_meta WHERE singleton = 1"
            ).fetchone()[0]
        )
        for row in self._connection.execute(
            """
            SELECT identity_id, record_kind, content_hash,
                   canonical_blob, first_receipt_sequence
            FROM canonical_records ORDER BY first_receipt_sequence
            """
        ):
            try:
                kind = PhysicalRecordKindV4(str(row[1]))
                blob = bytes(row[3])
                record = _parse_record(kind, blob)
            except (ValueError, CanonicalizationError) as exc:
                raise PhysicalProjectionV4VerificationError(
                    "canonical record cannot be decoded"
                ) from exc
            if len(blob) > max_bytes or canonical_json_bytes(record.as_dict()) != blob:
                raise PhysicalProjectionV4VerificationError(
                    "canonical record bytes are not exact"
                )
            identity = _blob_hash(_record_identity(record), field="identity_id")
            content = _content_hash(blob)
            if bytes(row[0]) != identity or bytes(row[2]) != content:
                raise PhysicalProjectionV4VerificationError(
                    "canonical record metadata differs from content"
                )
            receipt = self._connection.execute(
                """
                SELECT record_kind, identity_id, content_hash FROM receipts
                WHERE global_sequence = ?
                """,
                (int(row[4]),),
            ).fetchone()
            if receipt is None or (
                str(receipt[0]),
                bytes(receipt[1]),
                bytes(receipt[2]),
            ) != (kind.value, identity, content):
                raise PhysicalProjectionV4VerificationError(
                    "canonical record has no exact receipt bijection"
                )
            count += 1
        receipt_count = int(
            self._connection.execute("SELECT count(*) FROM receipts").fetchone()[0]
        )
        if count != receipt_count:
            raise PhysicalProjectionV4VerificationError(
                "canonical records and receipts are not bijective"
            )
        return count

